window.SSG_COURSES = window.SSG_COURSES || {};
window.SSG_COURSES.SSG104 = {"code": "SSG104", "sections": [{"id": "interview", "title": "Phỏng vấn, CV, Cover Letter & Nghề nghiệp", "tag": "Phỏng vấn & CV", "questions": [{"id": "SSG104_016", "index": 16, "question": "Which of the following should take place before you interview for a job?", "options": {"A": "Practice Answering common questions", "B": "Research the company or organization", "C": "Review the Job Description", "D": "All of the answers are correct"}, "correct": ["D"], "vi_explanation": "D. Tất cả các bước trên đều cần làm trước buổi phỏng vấn.\nNghiên cứu công ty, đọc kỹ JD và luyện trả lời câu hỏi phổ biến là chuẩn bị cơ bản trước khi đi phỏng vấn.", "has_visual": false}, {"id": "SSG104_023", "index": 23, "question": "Hung, who is 25 years old, recently took an aptitude test and a self-reported personality assessment to gain a clearer understanding of his interests and strengths. He has identified a career field that aligns with his degree. Which career development stage will Hung enter next?", "options": {"A": "Reinventing", "B": "Exploring", "C": "Establishing", "D": "Maintaining"}, "correct": ["C"], "vi_explanation": "C. Giai đoạn Thiết lập sự nghiệp (Establishing).\nSau khi tự khám phá bản thân và chọn xong ngành nghề phù hợp (Exploring), bước tiếp theo ở độ tuổi 25 là bắt đầu gây dựng vị trí trong nghề (Establishing).", "has_visual": false}, {"id": "SSG104_027", "index": 27, "question": "What should be considered suitable when answering the question 'Tell me about yourself' in a job interview? (Choose 2 answers)", "options": {"A": "Begin with a brief introduction to your hobbies.", "B": "Provide a brief introduction about yourself and a summary of your relevant work experiences.", "C": "Lying or exaggerating.", "D": "Highlight a few key achievements or projects that demonstrate your abilities and success in previous roles.", "E": "Negative experiences"}, "correct": ["B", "D"], "vi_explanation": "B, D. Giới thiệu ngắn gọn về bản thân, kinh nghiệm liên quan và nêu bật các thành tựu/dự án tiêu biểu.\nTránh nói lan man sở thích cá nhân, nói dối hay kể trải nghiệm tiêu cực.", "has_visual": false}, {"id": "SSG104_036", "index": 36, "question": "The resume opening should include a", "options": {"A": "heading, job or career objective, and a summary of your qualifications.", "B": "section with information for contacting your references.", "C": "summary of education.", "D": "list of special skills, honors, and activities."}, "correct": ["A"], "vi_explanation": "A. Tiêu đề/thông tin liên hệ, mục tiêu nghề nghiệp và tóm tắt năng lực nổi bật.\nPhần mở đầu CV cần cho nhà tuyển dụng thấy ngay bạn là ai và mang lại giá trị gì.", "has_visual": false}, {"id": "SSG104_040", "index": 40, "question": "What is the purpose of including references in a resume?(Thủy Tiên)", "options": {"A": "To provide contact information for past employers", "B": "To showcase professional connections", "C": "To demonstrate credibility and character", "D": "To list personal references for character assessment"}, "correct": ["C"], "vi_explanation": "C. Chứng minh độ tin cậy và tư cách nghề nghiệp của ứng viên.\nNgười tham chiếu (References) giúp nhà tuyển dụng kiểm chứng năng lực và phẩm chất thực tế qua góc nhìn bên thứ ba.", "has_visual": false}, {"id": "SSG104_041", "index": 41, "question": "You are conducting a job campaign to obtain employment . What should you do after analyzing your qualifications and job preferences?", "options": {"A": "start an interview for a job", "B": "obtain information about employment opportunities", "C": "email cover letter to potential companies", "D": "go to gym to prepare good health and appearance for the job interview"}, "correct": ["B"], "vi_explanation": "B. Tìm hiểu thông tin về các cơ hội việc làm phù hợp.\nSau bước tự phân tích năng lực và sở thích nghề nghiệp, bước kế tiếp là săn tìm vị trí tuyển dụng tương ứng.", "has_visual": false}, {"id": "SSG104_045", "index": 45, "question": "What does a career roadmap primarily aim to provide?", "options": {"A": "A detailed plan for retirement", "B": "A step-by-step guide to searching for a new job or change career paths", "C": "A list of potential job opportunities", "D": "A summary of past work experiences"}, "correct": ["B"], "vi_explanation": "B. Lộ trình từng bước để tìm việc mới hoặc chuyển hướng sự nghiệp.\nCareer roadmap vạch rõ các mốc hành động từ tự đánh giá đến chuẩn bị kỹ năng và ứng tuyển.", "has_visual": false}, {"id": "SSG104_049", "index": 49, "question": "What is the primary purpose of a cover letter?", "options": {"A": "To list work experience", "B": "To provide a summary of qualifications", "C": "To demonstrate personality", "D": "To introduce oneself and explaining why they are suited for a position."}, "correct": ["D"], "vi_explanation": "D. Tự giới thiệu bản thân và giải thích vì sao mình phù hợp với vị trí ứng tuyển.\nĐây là chức năng cốt lõi của Cover letter khi đi kèm với CV.", "has_visual": false}, {"id": "SSG104_051", "index": 51, "question": "Which of the following is optional in a resume?", "options": {"A": "Work experience", "B": "Education background", "C": "Job-related skills", "D": "Hobbies/interests"}, "correct": ["D"], "vi_explanation": "D. Sở thích cá nhân (Hobbies/interests).\nKinh nghiệm làm việc, học vấn và kỹ năng chuyên môn là phần cốt lõi bắt buộc; sở thích chỉ là phần bổ sung tùy chọn.", "has_visual": false}, {"id": "SSG104_052", "index": 52, "question": "Which of the following advices is NOT suitable for a job interview?", "options": {"A": "Research the company", "B": "Research other companies in the same industry", "C": "Practice answer questions about the job", "D": "Practice answer questions about personal life"}, "correct": ["D"], "vi_explanation": "D. Ôn luyện trả lời các câu hỏi về đời tư cá nhân.\nPhỏng vấn chuyên nghiệp tập trung vào năng lực công việc, công ty và ngành nghề chứ không đi sâu chuyện đời tư.", "has_visual": false}, {"id": "SSG104_066", "index": 66, "question": "When evaluating your career plan, what should you do first?", "options": {"A": "Looking for a career", "B": "Perform a self-assessment", "C": "Always review and revise your plan", "D": "Focus on developing goals"}, "correct": ["B"], "vi_explanation": "B. Thực hiện tự đánh giá bản thân (Perform a self-assessment).\nMuốn đánh giá hay lập kế hoạch nghề nghiệp phải bắt đầu từ việc hiểu rõ năng lực, giá trị và điểm mạnh của chính mình.", "has_visual": false}, {"id": "SSG104_068", "index": 68, "question": "In which stage of career development do individuals often experience a period of stability and may begin to reassess their long-term career goals?", "options": {"A": "Growth", "B": "Exploration", "C": "Establishment", "D": "Maintenance"}, "correct": ["D"], "vi_explanation": "D. Giai đoạn Duy trì (Maintenance).\nỞ giai đoạn này sự nghiệp đã ổn định và cá nhân thường nhìn lại để điều chỉnh mục tiêu dài hạn.", "has_visual": false}, {"id": "SSG104_071", "index": 71, "question": "What is a good advice to communicate effectively in a job interview?", "options": {"A": "Using jargon", "B": "Rambling", "C": "Keep eye contact", "D": "Over friendly"}, "correct": ["C"], "vi_explanation": "C. Duy trì giao tiếp bằng mắt (Keep eye contact).\nÁnh mắt tự nhiên thể hiện sự tự tin và tôn trọng người phỏng vấn, tránh dùng tiếng lóng hay nói lan man.", "has_visual": false}, {"id": "SSG104_076", "index": 76, "question": "A person with individualistio orientation tends to..........", "options": {"A": "bring about positive outcomes to others", "B": "show their preferences when dividing resources between themselves and others", "C": "find opportunities to undermine others to get ahead", "D": "show less concerns about the outcomes of others"}, "correct": ["D"], "vi_explanation": "D. Ít quan tâm đến kết quả của người khác.\nNgười mang định hướng cá nhân (Individualistic SVO) tập trung tối đa hóa lợi ích cho riêng mình mà ít bận tâm bên kia được gì.", "has_visual": false}, {"id": "SSG104_094", "index": 94, "question": "You don't have a job yet, but you're applying for your first job. What should you write in the work experience section?", "options": {"A": "Just write something down, anything even if it's not real.", "B": "I helped my mom with the housework every weekend.", "C": "I volunteered for three months at \"SOS Children's Village\" to help children.", "D": "I volunteered before, but it wasn't really a job."}, "correct": ["C"], "vi_explanation": "C. Nêu kinh nghiệm tình nguyện 3 tháng tại Làng trẻ em SOS.\nKhi chưa đi làm chính thức, hoạt động tình nguyện có tính chất công việc cụ thể vẫn chứng minh được kỹ năng và trách nhiệm.", "has_visual": false}, {"id": "SSG104_106", "index": 106, "question": "Choose the best answer for the interview question \"How old are you?\"", "options": {"A": "Old enough to have the knowledge to do the job well but not too old to be excited about continuing to improve and do it better.", "B": "Old enough to take this job.", "C": "22 years old.", "D": "My age is written in my resume. I am a very young. active, energetic person."}, "correct": ["A"], "vi_explanation": "A. \"Đủ lớn để có kiến thức làm tốt việc, nhưng vẫn đủ trẻ để hào hứng học hỏi và cải tiến.\"\nCâu trả lời khéo léo chuyển câu hỏi tuổi tác thành điểm mạnh về kinh nghiệm lẫn tinh thần cầu tiến.", "has_visual": false}, {"id": "SSG104_109", "index": 109, "question": "You are invited into the office for an interview. What should you not do?", "options": {"A": "Plop down in a chair then pull your phone out", "B": "Wait quietly until they are seated first", "C": "Shake hands with the interviewees then take a seat", "D": "Say thank you, and then ask if you can take a seat"}, "correct": ["A"], "vi_explanation": "A. Ngồi phịch xuống ghế rồi rút điện thoại ra bấm.\nĐây là hành vi thiếu chuyên nghiệp và thiếu tôn trọng nhà tuyển dụng nhất.", "has_visual": false}, {"id": "SSG104_110", "index": 110, "question": "When analyzing your qualifications and job preferences, you will look into your most positive attributes including", "options": {"A": "your awards. education. qualifications. hobbies", "B": "your achievements. background. soft skills. professional referees", "C": "yourstrengths. weaknesses. interests. skills", "D": "your accomplishments. education. experience. and personal traits"}, "correct": ["D"], "vi_explanation": "D. Thành tựu, học vấn, kinh nghiệm và phẩm chất cá nhân.\nKhi tự đánh giá năng lực xin việc, cần tập trung vào các điểm mạnh tích cực mang lại giá trị cho công việc.", "has_visual": false}, {"id": "SSG104_118", "index": 118, "question": "Which of Maslow's Hierarchy of Needs is primarily met when you find a job to gain financial balance.", "options": {"A": "Physiological", "B": "Esteem.", "C": "Safety.", "D": "Love and belonging."}, "correct": ["C"], "vi_explanation": "C. Nhu cầu an toàn (Safety).\nTìm việc làm để ổn định tài chính (hoặc lập nhóm tuần tra khu phố phòng tội phạm) nhằm đảm bảo sự an tâm và ổn định cuộc sống.", "has_visual": false}, {"id": "SSG104_135", "index": 135, "question": "An interview question that asks about one of your weaknesses would be answered best by", "options": {"A": "admitting the weakness.", "B": "asking if it is necessary to talk about weaknesses.", "C": "naming a weakness and turning it into a strength.", "D": "saying that you do not have any weaknesses."}, "correct": ["C"], "vi_explanation": "C. Nêu một điểm yếu thật nhưng khéo léo chỉ ra cách bạn đang khắc phục để biến nó thành điểm tích cực.\nTránh nói \"tôi không có điểm yếu\" vì thiếu chân thực, cũng không né tránh câu hỏi.", "has_visual": false}, {"id": "SSG104_136", "index": 136, "question": "What are five main stages of career development?", "options": {"A": "Growing Exploring - Establishing - Promoting - Reinventing.", "B": "Growing-Exploring - Establishing - Maintaining - Reinventing.", "C": "Finding-Reinventing - Establishing - Maintaining - Modifying.", "D": "Growing-Modifying - Establishing - Promoting - Reinventing."}, "correct": ["B"], "vi_explanation": "B. Growing → Exploring → Establishing → Maintaining → Reinventing.\nĐây là đúng thứ tự 5 giai đoạn phát triển sự nghiệp xuyên suốt đời người.", "has_visual": false}, {"id": "SSG104_139", "index": 139, "question": "What topics of information should you not include on your résumé?", "options": {"A": "Skills.", "B": "Love Life.", "C": "Education.", "D": "Work Experiences."}, "correct": ["B"], "vi_explanation": "B. Đời sống tình cảm (Love Life).\nCV chỉ nên đưa thông tin nghề nghiệp như học vấn, kỹ năng và kinh nghiệm làm việc.", "has_visual": false}, {"id": "SSG104_140", "index": 140, "question": "What should you do right after a job interview?", "options": {"A": "Do nothing.", "B": "Wait patiently for the HR department to call you.", "C": "Send an email to HR department asking about the result of the interview.", "D": "Send thank you email to the interviewer."}, "correct": ["D"], "vi_explanation": "D. Gửi email cảm ơn người phỏng vấn (thank you email).\nĐây là phép lịch sự chuyên nghiệp giúp ghi điểm và nhắc nhớ nhà tuyển dụng về bạn.", "has_visual": false}, {"id": "SSG104_156", "index": 156, "question": "In a job interview, which of the following answers is most appropriate to answer the question \"Are you planning a family in the near future?\"", "options": {"A": "I suppose everyone has a family plan in their own way. What will be will be!", "B": "May I not answer this over personal question?", "C": "As an active person in the young generation, I am quite open to this issue, I am working hard to support my parents first, and then I gaining a high social status for my future children.", "D": "Currently I am focused on my career. Although having a family is always a possibility, it is not a priority at the moment."}, "correct": ["D"], "vi_explanation": "D. Khẳng định hiện tại ưu tiên phát triển sự nghiệp, chuyện gia đình chưa phải ưu tiên lúc này.\nCách trả lời điềm tĩnh, chuyên nghiệp, vừa bảo vệ đời tư vừa trấn an nhà tuyển dụng về sự tập trung công việc.", "has_visual": false}, {"id": "SSG104_164", "index": 164, "question": "What are the four cyclical steps of the career roadmap identifies?", "options": {"A": "Know yourself, Explore and choose options, Gain knowledge and experience, Put it all together the job search process", "B": "Know yourself, Increase income, Gain more business relationship, Put it all together: the job search process", "C": "Know the job market, Know leadership, Explore and choose options, Improve living standard of self and family", "D": "Know employees' requirement, Explore your passion, Gain money, Gain social relationship"}, "correct": ["A"], "vi_explanation": "A. Hiểu bản thân → Khám phá & chọn hướng → Tích lũy kiến thức/kinh nghiệm → Ghép nối tìm việc.\nĐây là 4 bước tuần hoàn chuẩn của lộ trình phát triển nghề nghiệp.", "has_visual": false}, {"id": "SSG104_172", "index": 172, "question": "Which of the following interview questions is a behavioral question?", "options": {"A": "Where do you want to be in the next five years?", "B": "What type of work environment, structured or unstructured, is your most productive work setting?", "C": "You are younger than most people you will supervise. Do you think that is a problem?", "D": "Tell an experience of a time when you faced a major problem in group projects and how have you dealt with it?"}, "correct": ["D"], "vi_explanation": "D. \"Hãy kể lại một lần bạn gặp vấn đề lớn trong dự án nhóm và cách bạn xử lý.\"\nCâu hỏi hành vi luôn yêu cầu kể lại tình huống đã xảy ra trong quá khứ để đánh giá cách ứng xử thực tế.", "has_visual": false}, {"id": "SSG104_174", "index": 174, "question": "If you are applying for a job that is new or you have little or no experience, you should:", "options": {"A": "Let your personality shine through.", "B": "Read and leam as much as you can about the job before you apply.", "C": "Just accept that you probably won't get hired and do not apply at all.", "D": "Whatever happens will come, just let it be."}, "correct": ["B"], "vi_explanation": "B. Tìm hiểu thật kỹ về công việc đó trước khi nộp đơn.\nDù chưa có kinh nghiệm, việc chủ động nghiên cứu cho thấy sự nghiêm túc và khả năng nắm bắt nhanh.", "has_visual": false}, {"id": "SSG104_175", "index": 175, "question": "When analyzing job preferences, which of the following questions is not necessary to consider?", "options": {"A": "Do you like working indoors, outside an office environment, or in varied work environments?", "B": "Do you want to work in a large company with a structured work environment, or do you prefer a small or less-structured company?", "C": "Do you want to work alone, working with other people or being in charge?", "D": "Do you want to work in a comfortable and open environment with people who share the same hobbies and personal life with you?"}, "correct": ["D"], "vi_explanation": "D. Đòi hỏi môi trường làm việc với những người có chung sở thích và đời sống cá nhân.\nKhi xét tiêu chí công việc, trọng tâm là không gian làm việc, quy mô công ty và cách phối hợp — không phải gu đời tư.", "has_visual": false}, {"id": "SSG104_182", "index": 182, "question": "Which date format is best for a cover letter?", "options": {"A": "October 9, 2023", "B": "9/10/23", "C": "9/10/2023", "D": "9th October 23"}, "correct": ["A"], "vi_explanation": "A. October 9, 2023.\nTrong thư xin việc chuẩn tiếng Anh, viết đầy đủ tên tháng giúp tránh hiểu nhầm định dạng ngày/tháng giữa chuẩn Mỹ và Anh.", "has_visual": false}, {"id": "SSG104_183", "index": 183, "question": "Pay raises, promotions, desirable job assignments, more responsibility, new equipment are example of", "options": {"A": "Reward power", "B": "Legitimate", "C": "Expert Power", "D": "Coercive Power"}, "correct": ["A"], "vi_explanation": "A. Quyền lực khen thưởng (Reward power).\nTăng lương, thăng chức hay giao thiết bị mới đều là công cụ phần thưởng nhằm tạo động lực.", "has_visual": false}, {"id": "SSG104_190", "index": 190, "question": "Who do potential employers consider references from as the best type of references?", "options": {"A": "Your friends.", "B": "Your lecturers or your previous manager.", "C": "Your family.", "D": "Your best friends."}, "correct": ["B"], "vi_explanation": "B. Giảng viên hoặc quản lý cũ của bạn.\nHọ đánh giá khách quan nhất về năng lực học tập và thái độ làm việc chuyên môn, đáng tin hơn người thân hay bạn bè.", "has_visual": false}, {"id": "SSG104_199", "index": 199, "question": "What happens in fantasy stage of career development ?", "options": {"A": "Young boys' choices were related to their fathers' careers", "B": "Interests are the major factor in the selection of career choices during childhood", "C": "Aware of job availability", "D": "Children begin to think about which careers they might like to do in the future"}, "correct": ["D"], "vi_explanation": "D. Trẻ em bắt đầu tưởng tượng về các nghề nghiệp chúng thích làm trong tương lai.\nGiai đoạn Ảo tưởng (Fantasy stage) ở tuổi nhỏ phản ánh ước mơ nghề nghiệp mang tính tưởng tượng trước khi xét đến thực tế.", "has_visual": false}, {"id": "SSG104_202", "index": 202, "question": "In a job interview how should you best respond to interview questions?", "options": {"A": "Be enthusiastic, honest, sincere, and state your accomplishments in a specific and positive manner.", "B": "Embellish your achievements and accomplishments to make sure the employer remembers them.", "C": "Say that your achievements and accomplishments are detailed on your resume.", "D": "Use caution when describing what you have accomplished so you will not appear to be bragging on yourself."}, "correct": ["A"], "vi_explanation": "A. Nhiệt tình, trung thực, chân thành và nêu cụ thể thành tựu một cách tích cực.\nTránh nói phóng đại sai sự thật (B) hoặc trả lời cộc lốc \"xem trên CV\" (C).", "has_visual": false}, {"id": "SSG104_204", "index": 204, "question": "What should you always do after an interview?", "options": {"A": "Runaway.", "B": "Ask about salary.", "C": "Thank the interviewer.", "D": "Call them several times."}, "correct": ["C"], "vi_explanation": "C. Gửi lời cảm ơn người phỏng vấn.\nThể hiện phép lịch sự và sự trân trọng cơ hội, tránh làm phiền gọi dồn dập hay vội vã đòi hỏi.", "has_visual": false}, {"id": "SSG104_209", "index": 209, "question": "What type of information should you include on a résumé?", "options": {"A": "Your social security number", "B": "Your family information", "C": "Your job skills and working history", "D": "Your family tree"}, "correct": ["C"], "vi_explanation": "C. Kỹ năng nghề nghiệp và lịch sử làm việc.\nKhông bao giờ ghi số an sinh xã hội hay gia phả lên CV vì rủi ro lộ thông tin cá nhân.", "has_visual": false}, {"id": "SSG104_210", "index": 210, "question": "Below are questions that a job applicant should prepare to ask during an interview EXCEPT", "options": {"A": "What are the major responsibilities of the job?", "B": "Please describe the normal routine of this position?", "C": "How is job performance evaluated and how often?", "D": "How much can the company pay me?"}, "correct": ["D"], "vi_explanation": "D. \"Công ty có thể trả cho tôi bao nhiêu tiền?\"\nKhông nên hỏi thẳng chuyện lương bổng quá sớm ở vòng phỏng vấn đầu khi chưa chứng minh giá trị bản thân.", "has_visual": false}, {"id": "SSG104_211", "index": 211, "question": "Which of the following is NOT a characteristic of a cover letter:", "options": {"A": "It determines the position you are interested in.", "B": "It shows how you find out about the position or company.", "C": "It sets you apart from every possible competitor.", "D": "It explains why you are not satisfied with your performance."}, "correct": ["D"], "vi_explanation": "D. \"Giải thích vì sao bạn không hài lòng với hiệu suất của mình\" không phải đặc điểm của cover letter.\nCover letter phải làm nổi bật điểm mạnh, động lực ứng tuyển và lý do bạn phù hợp.", "has_visual": false}, {"id": "SSG104_214", "index": 214, "question": "What should you put in the Education part in a resume?", "options": {"A": "academic degrees, professional development, certificates, internships.", "B": "most recent jobs you have experience; include the title of the position, employer's name, employment dates.", "C": "5-10 skills you have gained in your field.", "D": "Personal contact."}, "correct": ["A"], "vi_explanation": "A. Bằng cấp học thuật, chứng chỉ chuyên môn, khóa bồi dưỡng và thực tập.\nKinh nghiệm làm việc nằm ở mục Work experience, còn mục Education tập trung vào nền tảng đào tạo.", "has_visual": false}, {"id": "SSG104_215", "index": 215, "question": "What should you put in the Work experience part in a resume?", "options": {"A": "Academic degrees, professional development, certificates, internships", "B": "Most recent jobs you have experience; include the title of the position, employer's name, location, employment dates", "C": "5-10 skills you have gained in your field", "D": "Personal contact"}, "correct": ["B"], "vi_explanation": "B. Các công việc gần đây nhất kèm chức danh, tên công ty, địa điểm và thời gian làm việc.\nĐây là cấu trúc chuẩn của mục Kinh nghiệm làm việc trong CV.", "has_visual": false}, {"id": "SSG104_222", "index": 222, "question": "When writing your cover letter, you should:", "options": {"A": "Simply copy and paste the same letter over and over.", "B": "Create an original letter for each job application-", "C": "Copy and paste the first and last paragraphs, but tailor the rest to the employer-", "D": "Establish a candldate's qualifrcations for a position in order to eiiminate the compatition"}, "correct": ["B"], "vi_explanation": "B. Viết một lá thư riêng phù hợp cho từng vị trí ứng tuyển.\nViệc cá nhân hóa cover letter cho thấy sự đầu tư và mức độ phù hợp với từng nhà tuyển dụng.", "has_visual": false}, {"id": "SSG104_224", "index": 224, "question": "... is the continuous process of building your skills, knowledge and experiences related to your professional life", "options": {"A": "Employment", "B": "An occupation", "C": "A career", "D": "None are correct"}, "correct": ["C"], "vi_explanation": "C. Sự nghiệp (A career).\nKhác với một công việc nhất thời (employment/job), sự nghiệp là quá trình phát triển kỹ năng và kinh nghiệm dài lâu.", "has_visual": false}, {"id": "SSG104_229", "index": 229, "question": "Which of the following is incorrect about resume?", "options": {"A": "A résumé is a \"selfie\" for business purposes.", "B": "It is a written picture of who you are-it's a marketing tool, and a promotion of you as an in any job you may be interested in.", "C": "The word résumé comes from the French word résumé, which means \"a summary.\"", "D": "Resume is to show to your family what you do for a living."}, "correct": ["D"], "vi_explanation": "D. \"CV dùng để khoe với gia đình bạn làm nghề gì\" là SAI.\nResume là công cụ tiếp thị bản thân chuyên nghiệp gửi tới nhà tuyển dụng.", "has_visual": false}, {"id": "SSG104_230", "index": 230, "question": "Which questions below that a job applicant should prepare to ask during an interview?", "options": {"A": "Please describe the normal routine of this position in a typical day?", "B": "How can I gain promotion?", "C": "When do you expect to make a hiring decision as it is said in the recruitment advertisement position is in urgent need?", "D": "How much is the Salary?"}, "correct": ["A"], "vi_explanation": "A. \"Anh/chị có thể mô tả một ngày làm việc điển hình của vị trí này không?\"\nĐây là câu hỏi thông minh thể hiện sự quan tâm thực tế đến công việc, tránh hỏi vồ vập về lương hay thăng tiến ngay.", "has_visual": false}, {"id": "SSG104_232", "index": 232, "question": "An interviewer may intentionally challenge you by asking difficult questions to .....", "options": {"A": "see how you handle different situations-", "B": "see you panic.", "C": "show you the working environment can be stressful.", "D": "avoid being friendly."}, "correct": ["A"], "vi_explanation": "A. Xem cách bạn xử lý các tình huống áp lực khác nhau ra sao.\nCâu hỏi khó giúp nhà tuyển dụng kiểm tra bản lĩnh, tư duy phản xạ và thái độ bình tĩnh của ứng viên.", "has_visual": false}, {"id": "SSG104_239", "index": 239, "question": "What is the best way to dress to impress employers in an interview?", "options": {"A": "No matter what you wear", "B": "Be trendy (crop top, Jordans, etc...)", "C": "Wear a formal suit", "D": "Wear a Nike jogging suit"}, "correct": ["C"], "vi_explanation": "C. Mặc vest/trang phục công sở trang trọng (formal suit).\nTrang phục chỉn chu thể hiện sự chuyên nghiệp và tôn trọng buổi phỏng vấn.", "has_visual": false}, {"id": "SSG104_242", "index": 242, "question": "Your cover letter should be addressed to:", "options": {"A": "The company's name", "B": "A specific person", "C": "The company's president", "D": "Any manager related to the company"}, "correct": ["B"], "vi_explanation": "B. Gửi tới một cá nhân cụ thể (như tên trưởng phòng/người tuyển dụng).\nViết đúng tên người nhận tạo thiện cảm cá nhân tốt hơn là ghi chung chung tên công ty.", "has_visual": false}, {"id": "SSG104_260", "index": 260, "question": "What is the first thing to do before we come to a job interview?", "options": {"A": "Dress appropriately.", "B": "The usage of body language.", "C": "Read the job description carefully.", "D": "Follow up the interview result."}, "correct": ["C"], "vi_explanation": "C. Đọc kỹ bản mô tả công việc (job description).\nHiểu rõ yêu cầu vị trí là bước chuẩn bị đầu tiên để trả lời phỏng vấn trúng trọng tâm.", "has_visual": false}, {"id": "SSG104_261", "index": 261, "question": "What kind of students has been shown by research to stay in college longer, be more goal focused and motivated, and have a more satisfying and fulfilling college experience?", "options": {"A": "Students who have good social relationships", "B": "Students who have excellent leadership skills", "C": "Students who show great passion for the subjects they are studying *", "D": "Students who get involved in career-planning activities early"}, "correct": ["D"], "vi_explanation": "D. Sinh viên tham gia hoạt động định hướng nghề nghiệp sớm.\nNghiên cứu cho thấy nhóm sinh viên lập kế hoạch nghề nghiệp từ sớm có động lực học tập rõ ràng và gắn bó với đại học hơn.", "has_visual": false}, {"id": "SSG104_266", "index": 266, "question": "What is the typical length of a cover letter?", "options": {"A": "1-2 paragraphs.", "B": "2-3 paragraphs.", "C": "3-4 paragraphs.", "D": "More than 4 paragraphs."}, "correct": ["C"], "vi_explanation": "C. 3–4 đoạn văn ngắn (3-4 paragraphs).\nĐây là độ dài chuẩn giúp thư xin việc vừa đủ ý (mở đầu, năng lực, lý do hợp công ty, kết thư) trên một trang giấy.", "has_visual": false}, {"id": "SSG104_285", "index": 285, "question": "What is career development?", "options": {"A": "It's a lifelong process in which we become aware of, interested in, knowledgeable about, and skilled in a career.", "B": "It's a key part of human development as our identity forms and our life unfolds.", "C": "It's a development process that varies from person to person on the life journey to discover themselves.", "D": "All are correct."}, "correct": ["D"], "vi_explanation": "D. Tất cả các ý trên đều đúng.\nPhát triển sự nghiệp là quá trình suốt đời gắn với nhận thức, sở thích, tri thức và quá trình khám phá bản thân của mỗi người.", "has_visual": false}, {"id": "SSG104_296", "index": 296, "question": "An inventory of your education, work experience, job-related skills, accomplishments, volunteer history internships, residencies, and/or more. Which of the following definition could match the above description?", "options": {"A": "Cover letter.", "B": "Proposal.", "C": "Résumé.", "D": "Outline."}, "correct": ["C"], "vi_explanation": "C. Bản sơ yếu lý lịch nghề nghiệp (Résumé).\nTổng hợp quá trình học tập, kinh nghiệm, kỹ năng và thành tích chuyên môn của ứng viên.", "has_visual": false}, {"id": "SSG104_301", "index": 301, "question": "What is an example of Expert Power?", "options": {"A": "Professors presumably have power in the classroom because of their mastery of a particular subject matter.", "B": "A supervisor has a right to assign work.", "C": "Salary and promotion among most blue-collar workers is based on a labor contract, not a performance appraisal.", "D": "In many organizations, supervisors and managers really do not control very many rewards."}, "correct": ["A"], "vi_explanation": "A. Giáo sư có quyền lực trong lớp nhờ nắm vững kiến thức chuyên môn sâu rộng.\nĐây là ví dụ điển hình cho Expert Power, khác với quyền chức vụ (B) hay quyền thưởng (C, D).", "has_visual": false}, {"id": "SSG104_302", "index": 302, "question": "A cover letter can also be called:", "options": {"A": "A résumé or CV.", "B": "A letter of application.", "C": "An application form.", "D": "A CV sales letter."}, "correct": ["B"], "vi_explanation": "B. Thư xin việc / Thư ứng tuyển (A letter of application).\nCover letter và Application letter đều là tên gọi cho lá thư đi kèm CV khi ứng tuyển.", "has_visual": false}, {"id": "SSG104_310", "index": 310, "question": "When developing an application letter, which of the following should not be added in the opening of the letter?", "options": {"A": "The name of your referee who introduced this job to you.", "B": "Your knowledge about the position or the company.", "C": "Reasons why you find this position interesting.", "D": "Your most significant accomplishments."}, "correct": ["D"], "vi_explanation": "D. Những thành tựu nổi bật nhất của bạn (nên đưa vào phần thân thư chứ không phải đoạn mở đầu).\nPhần mở đầu thư xin việc chỉ nên nêu vị trí ứng tuyển, người giới thiệu (nếu có) và sự hiểu biết/hứng thú với công ty.", "has_visual": false}, {"id": "SSG104_324", "index": 324, "question": "What is a consequence of Coercive power ?(choose 2 options)", "options": {"A": "It is difficult to control.", "B": "Its pressure leads to increased job performance.", "C": "Subordinates often see little reason for cooperating.", "D": "It depends on the official position a person holds."}, "correct": ["A", "C"], "vi_explanation": "A, C. Khó kiểm soát hậu quả và khiến cấp dưới mất động lực hợp tác tự nguyện.\nQuyền lực cưỡng chế tạo áp lực sợ hãi nhất thời chứ không mang lại sự gắn kết lâu dài.", "has_visual": false}, {"id": "SSG104_326", "index": 326, "question": "Which interview format is especially for weeding out candidates?", "options": {"A": "Panel interview.", "B": "Group interview.", "C": "Web Conference interview.", "D": "Screening interview."}, "correct": ["D"], "vi_explanation": "D. Phỏng vấn sàng lọc (Screening interview).\nThường diễn ra ngắn gọn ở vòng đầu để loại bớt ứng viên không đạt tiêu chuẩn cơ bản.", "has_visual": false}, {"id": "SSG104_329", "index": 329, "question": "What can a student put in his or her cover letter?", "options": {"A": "GPA.", "B": "Soft skills.", "C": "Volunteer works.", "D": "All are correct."}, "correct": ["D"], "vi_explanation": "D. Tất cả các thông tin trên đều đưa vào được.\nSinh viên mới ra trường nên tận dụng điểm GPA tốt, kỹ năng mềm và hoạt động tình nguyện để làm nổi bật hồ sơ trong cover letter.", "has_visual": false}, {"id": "SSG104_330", "index": 330, "question": "In career development, who has the role of offering job and discussing variety of career paths?", "options": {"A": "Individual role.", "B": "Manager role.", "C": "Line manager.", "D": "Employer role."}, "correct": ["D"], "vi_explanation": "D. Vai trò của nhà tuyển dụng / tổ chức (Employer role).\nTổ chức là bên cung cấp cơ hội việc làm, cơ cấu vị trí và lộ trình thăng tiến cho nhân viên.", "has_visual": false}, {"id": "SSG104_332", "index": 332, "question": "Which of the following advice is NOT suitable for a job interview?", "options": {"A": "Review job description.", "B": "Be confident.", "C": "Come prepared.", "D": "Dress casually."}, "correct": ["D"], "vi_explanation": "D. Mặc đồ quá xuề xòa/tùy tiện (Dress casually).\nĐi phỏng vấn cần ăn mặc lịch sự, chuyên nghiệp phù hợp môi trường công sở.", "has_visual": false}, {"id": "SSG104_334", "index": 334, "question": "What is one thing that you should NOT do during the first interview?", "options": {"A": "Ask about salary.", "B": "Connect with interviewer.", "C": "Communicate why you are a good fit.", "D": "Close by arranging next interview."}, "correct": ["A"], "vi_explanation": "A. Hỏi về mức lương ngay trong buổi phỏng vấn đầu tiên.\nHãy tập trung thể hiện sự phù hợp và kết nối với nhà tuyển dụng trước khi bàn đãi ngộ.", "has_visual": false}, {"id": "SSG104_341", "index": 341, "question": "What is Social Value Orientation (SVO)?", "options": {"A": "People prefer to organize and distribute work between themselves", "B": "People's preferences when dividing resources between themselves and others", "C": "People dislike others' work and try to prove their outcome is much better", "D": "People are not cooperative and tend to work alone"}, "correct": ["B"], "vi_explanation": "B. Khuynh hướng ưu tiên của con người khi phân chia nguồn lực giữa bản thân và người khác.\nSVO phân loại cách mỗi người chọn chia lợi ích theo hướng hợp tác, cá nhân hay cạnh tranh.", "has_visual": false}, {"id": "SSG104_345", "index": 345, "question": "When being asked \"please tell us your strengths?\" in a job interview, what should you focus", "options": {"A": "Tell about your academic awards, your successful school projects.", "B": "Tell about your two key personal qualifications.", "C": "Tell your work-related accomplishments, mention how your previous supervisor or mana with your work performance.", "D": "Tell about your skills and knowledge and explain how they satisfy the job requirements."}, "correct": ["D"], "vi_explanation": "D. Nêu kỹ năng, kiến thức và giải thích chúng đáp ứng yêu cầu công việc ra sao.\nCâu trả lời điểm mạnh hay nhất luôn gắn trực tiếp giá trị của bạn với nhu cầu tuyển dụng của công ty.", "has_visual": false}, {"id": "SSG104_346", "index": 346, "question": "For new college graduates with limited experience, the preferred number of pages for a resume is", "options": {"A": "one.", "B": "two.", "C": "three.", "D": "four."}, "correct": ["A"], "vi_explanation": "A. 1 trang (one page).\nSinh viên mới tốt nghiệp ít kinh nghiệm nên gói gọn CV trong 1 trang súc tích, dễ đọc.", "has_visual": false}, {"id": "SSG104_351", "index": 351, "question": "\"I am the first person in my family to complete a Bachelor degree; and now that I have want to give something back to my family by getting a good job with a company like yours. I while attending school, so I have work experience at food stores. I am a hard worker, I grew and could drive any kind of machinery.\"\nThis part of an application letter to software developer position is not effective because ________________", "options": {"A": "It uses impersonal salutation.", "B": "It does not relate to the company needs.", "C": "It conveys negative tones.", "D": "It provides the family background of the applicant."}, "correct": ["B"], "vi_explanation": "B. Không gắn kết được kinh nghiệm với nhu cầu của công ty tuyển dụng.\nỨng tuyển lập trình viên nhưng lại kể chuyện gia đình và lái máy nông nghiệp không liên quan đến năng lực phần mềm công ty cần.", "has_visual": false}]}, {"id": "psych", "title": "Tâm lý xã hội, Maslow, Stress & Văn hóa", "tag": "Tâm lý & Văn hóa", "questions": [{"id": "SSG104_007", "index": 7, "question": "Which solutions below can help managing stress? Choose 3 answers.", "options": {"A": "Manage your time", "B": "Use drugs and alcohol when the stress level is likely out of control", "C": "Find support", "D": "Slow down and cut out distractions for a while"}, "correct": ["A", "C", "D"], "vi_explanation": "A, C, D. Quản lý thời gian, tìm sự hỗ trợ và giảm bớt xao nhãng giúp kiểm soát căng thẳng lành mạnh.\nDùng rượu bia hay chất kích thích (B) chỉ làm stress trầm trọng thêm.", "has_visual": false}, {"id": "SSG104_010", "index": 10, "question": "Which of the following is not a characteristic of critical thinkers?", "options": {"A": "Uncovering biases", "B": "Examining assumptions", "C": "Blind acceptance of authority", "D": "Skepticism"}, "correct": ["C"], "vi_explanation": "C. Tin tưởng mù quáng vào người có thẩm quyền.\nNgười có tư duy phản biện luôn đặt câu hỏi, kiểm tra giả định và hoài nghi có cơ sở thay vì nghe theo một cách mù quáng.", "has_visual": false}, {"id": "SSG104_014", "index": 14, "question": "Important factor(s) that determine whether people will engage in social comparison is (are):", "options": {"A": "Relevance", "B": "Similarity", "C": "Interest", "D": "Emotion", "E": "Cognitive domain", "F": "All of the answers are correct"}, "correct": ["F"], "vi_explanation": "F. Tất cả các yếu tố trên đều đúng.\nViệc con người có so sánh xã hội hay không phụ thuộc vào mức độ liên quan, sự tương đồng, mối quan tâm, cảm xúc và lĩnh vực nhận thức.", "has_visual": false}, {"id": "SSG104_022", "index": 22, "question": "What does the Self-Evaluation Maintenance Model show?", "options": {"A": "Managers may prefer sub-optimal candidates who aren't likely to challenge their standing in the organization.", "B": "Managers will not accept bad applications", "C": "Managers accept all applications", "D": "It does not relevant with social comparison theory"}, "correct": ["A"], "vi_explanation": "A. Quản lý có thể ưu tiên tuyển ứng viên kém hơn một chút để không đe dọa vị thế của họ.\nTheo mô hình Duy trì Tự đánh giá (SEM), người ở vị trí cao dễ dè chừng người giỏi tương đương ở lĩnh vực sát sườn với mình.", "has_visual": false}, {"id": "SSG104_046", "index": 46, "question": "Your manager displays a high level of integrity. Which two traits best represent the manager?", "options": {"A": "Articulate and self-confident", "B": "Dependable and diligent", "C": "Trustworthy and honest", "D": "Self-confident and empathetic"}, "correct": ["C"], "vi_explanation": "C. Đáng tin cậy và trung thực (Trustworthy and honest).\nTính chính trực (Integrity) cốt lõi là sự nhất quán giữa lời nói, chuẩn mực đạo đức và hành động trung thực.", "has_visual": false}, {"id": "SSG104_048", "index": 48, "question": "Why being socially connected is an important way of dealing with stress?", "options": {"A": "Because it's easy to isolate yourself when you feel stressed", "B": "Because it helps you to maintain a normal routine", "C": "Because other people can give you good advices about your problems", "D": "Because it can help distract you from your problems for a while"}, "correct": ["A"], "vi_explanation": "A. Vì khi căng thẳng con người rất dễ thu mình cô lập bản thân.\nDuy trì kết nối xã hội giúp chống lại xu hướng tự cô lập và giảm áp lực tâm lý.", "has_visual": false}, {"id": "SSG104_050", "index": 50, "question": "What is true about chronic stress?", "options": {"A": "Chronic stress can impair your immune system and disrupt almost all of your body's processes, leading to increased risk of numerous health problems.", "B": "Chronic stress can help you develop skills needed to manage potentially challenging or threatening situations in life.", "C": "Preparing for a holiday trip or a final exam can cause chronic stress.", "D": "Chronic stress does not cause severe problems such as heart disease and the impairment of memory and concentration."}, "correct": ["A"], "vi_explanation": "A. Stress kéo dài làm suy yếu hệ miễn dịch và rối loạn hầu hết cơ quan, tăng nguy cơ bệnh lý.\nKhác với stress cấp tính nhẹ, stress mãn tính rất hại cho sức khỏe thể chất và trí nhớ.", "has_visual": false}, {"id": "SSG104_059", "index": 59, "question": "When the number of comparison targets increase, social comparison tends to", "options": {"A": "increase", "B": "remain the same", "C": "be distorted", "D": "decrease"}, "correct": ["D"], "vi_explanation": "D. Có xu hướng giảm (decrease).\nTheo hiệu ứng N-effect, khi số lượng đối thủ hoặc đối tượng so sánh tăng lên quá nhiều, động lực so sánh xã hội của mỗi cá nhân lại giảm xuống.", "has_visual": false}, {"id": "SSG104_064", "index": 64, "question": "Which implication does Self-Evaluation Maintenance (SEM) Model suggest?", "options": {"A": "People are more likely to compare with friends or co-workers than they are to industry or national averages.", "B": "Average students have a higher academic self-concept when attending a below-average school.", "C": "Managers may prefer sub-optimal candidates who aren't likely to challenge their standing in the organization.", "D": "Unskilled people often think they are on par or superior to their peers in tasks such as test-taking abilities."}, "correct": ["C"], "vi_explanation": "C. Quản lý có xu hướng chọn ứng viên dưới tầm để tránh bị đe dọa vị thế.\nTheo mô hình SEM, việc người khác giỏi hơn ở lĩnh vực mình quan tâm sẽ làm giảm tự đánh giá bản thân, nên quản lý đôi khi né tuyển người quá vượt trội.", "has_visual": false}, {"id": "SSG104_067", "index": 67, "question": "Choose the best answer for this question: 'How do you handle stress and pressure?", "options": {"A": "I don't know.", "B": "I can't. I don't know how.", "C": "It was my role to manage the invoicing process.", "D": "I try to react to situations, rather than to stress."}, "correct": ["D"], "vi_explanation": "D. \"Tôi cố gắng tập trung phản ứng giải quyết tình huống thay vì để stress chi phối.\"\nĐây là câu trả lời tích cực, cho thấy khả năng giữ bình tĩnh và xử lý vấn đề dưới áp lực.", "has_visual": false}, {"id": "SSG104_072", "index": 72, "question": "One of the key findings in the Dunning-Kruger effect experiments is unskilled people are", "options": {"A": "always satisfied with results", "B": "often jealous with others", "C": "unrewarded and biased", "D": "overconfident with results"}, "correct": ["D"], "vi_explanation": "D. Quá tự tin vào kết quả của bản thân (overconfident with results).\nHiệu ứng Dunning–Kruger chỉ ra người thiếu kỹ năng thường đánh giá quá cao năng lực mình vì không đủ kiến thức để nhận ra sai sót.", "has_visual": false}, {"id": "SSG104_074", "index": 74, "question": "Thought and thinking can be understood as ............within the mind.", "options": {"A": "Patterns - Systems and Schemes", "B": "Order and Structure", "C": "Act and Control", "D": "Analyze and Evaluate"}, "correct": ["A"], "vi_explanation": "A. Các khuôn mẫu, hệ thống và lược đồ (Patterns - Systems and Schemes).\nTư duy vận hành dựa trên các mô hình và cấu trúc nhận thức sẵn có trong tâm trí.", "has_visual": false}, {"id": "SSG104_078", "index": 78, "question": "Which words should you use to when you want to give contrast ideas?", "options": {"A": "Signifrcantly, primarily, especially", "B": "Nevertheless, however, by contrast", "C": "For example, to illustrate, like", "D": "First, second, last"}, "correct": ["B"], "vi_explanation": "B. Nevertheless, however, by contrast.\nĐây là nhóm từ nối chuyên dùng để thể hiện sự tương phản hoặc đối lập ý.", "has_visual": false}, {"id": "SSG104_079", "index": 79, "question": "Signs of stress include........", "options": {"A": "heart pounding", "B": "shortness of breath", "C": "upset stomach", "D": "All are correct."}, "correct": ["D"], "vi_explanation": "D. Tất cả các triệu chứng trên đều đúng.\nTim đập nhanh, hụt hơi và đau bụng là những phản ứng sinh lý phổ biến khi căng thẳng.", "has_visual": false}, {"id": "SSG104_083", "index": 83, "question": "People are ... by social comparison when the comparison is ....", "options": {"A": "more influenced - more localized", "B": "more influenced - less localized", "C": "more influenced - broad and general", "D": "less influenced - more localized"}, "correct": ["A"], "vi_explanation": "A. Chịu ảnh hưởng mạnh hơn khi sự so sánh mang tính cục bộ/gần gũi hơn (more localized).\nTa thường so với bạn bè, đồng nghiệp quanh mình hơn là số liệu trung bình toàn quốc.", "has_visual": false}, {"id": "SSG104_092", "index": 92, "question": "The need for self-evaluation experiment has shown that people come to know about themsel", "options": {"A": "having positive attitude in life", "B": "comparing with others", "C": "seeking happiness", "D": "feeling complete"}, "correct": ["B"], "vi_explanation": "B. So sánh với người khác (comparing with others).\nThuyết so sánh xã hội của Festinger chỉ ra con người tự đánh giá bản thân qua việc đối chiếu với người xung quanh khi thiếu thước đo khách quan.", "has_visual": false}, {"id": "SSG104_098", "index": 98, "question": "People usually compare themselves with friends or co-workers rather than comparing to industry or national averages. What is this comparison called in situational factors?", "options": {"A": "Number", "B": "Local", "C": "Proximity toastandard", "D": "Self-relevant"}, "correct": ["B"], "vi_explanation": "B. So sánh cục bộ (Local).\nĐối chiếu với bạn bè hoặc đồng nghiệp gần gũi xung quanh thay vì chuẩn mực xa xôi gọi là so sánh cục bộ.", "has_visual": true, "image_local": "images/SSG104_098.png", "images": ["https://o.quizlet.com/vyM7BAXqndo1bTcZ4MfXIw_m.png"]}, {"id": "SSG104_104", "index": 104, "question": "Which do you believe required the greatest amounts of cooperation?", "options": {"A": "Hunting Wild animals", "B": "Go fishing", "C": "kayaking", "D": "Skiing"}, "correct": ["A"], "vi_explanation": "A. Săn thú hoang dã (Hunting Wild animals).\nSo với câu cá, chèo kayak hay trượt tuyết cá nhân, săn thú lớn đòi hỏi sự phối hợp tổ chức cao nhất giữa nhiều người.", "has_visual": false}, {"id": "SSG104_107", "index": 107, "question": "Andrew is a good listener and he always tries to understand what people think and why people feel in their own way. Andrew has ability of", "options": {"A": "empathy", "B": "interdependence", "C": "caring", "D": "considerable skills"}, "correct": ["A"], "vi_explanation": "A. Sự thấu cảm (empathy).\nLắng nghe sâu và hiểu cảm xúc lẫn góc nhìn của người khác chính là biểu hiện của thấu cảm.", "has_visual": false}, {"id": "SSG104_108", "index": 108, "question": "Which of the following countries represent individualistic cultures?", "options": {"A": "Cuba", "B": "The United States", "C": "Wetnam", "D": "Japan"}, "correct": ["B"], "vi_explanation": "B. Hoa Kỳ (The United States).\nMỹ là quốc gia tiêu biểu cho văn hóa đề cao chủ nghĩa cá nhân (Individualistic), khác với văn hóa tập thể ở Việt Nam, Nhật Bản hay Cuba.", "has_visual": false}, {"id": "SSG104_117", "index": 117, "question": "What are symptoms of chronic stress? (Select 4 options)", "options": {"A": "Sleep problems.", "B": "Weight goin.", "C": "Digestive problems.", "D": "Enhance memory and concentration.", "E": "Heart disease"}, "correct": ["A", "B", "C", "E"], "vi_explanation": "A, B, C, E. Mất ngủ, tăng cân, rối loạn tiêu hóa và bệnh tim mạch đều là triệu chứng của stress mãn tính.\nStress kéo dài làm suy giảm chứ không bao giờ giúp cải thiện trí nhớ hay tập trung (D).", "has_visual": false}, {"id": "SSG104_142", "index": 142, "question": "What are the two main factors in social comparison?", "options": {"A": "Similarity and friendliness.", "B": "Openness and independence.", "C": "Relevance and similarity.", "D": "Self-esteem and trustworthy."}, "correct": ["C"], "vi_explanation": "C. Mức độ liên quan và sự tương đồng (Relevance and similarity).\nTa chỉ thực sự so sánh mình với những người có điểm tương đồng và thuộc lĩnh vực ta quan tâm.", "has_visual": false}, {"id": "SSG104_147", "index": 147, "question": "What is the main advantage of social facilitation?", "options": {"A": "Feel better", "B": "Perform tasks improved", "C": "Work more independently", "D": "Have high chance of promotion"}, "correct": ["B"], "vi_explanation": "B. Cải thiện hiệu suất thực hiện nhiệm vụ (Perform tasks improved).\nHiện tượng Social facilitation cho thấy sự có mặt của người khác giúp làm tốt hơn các công việc đã quen thuộc.", "has_visual": false}, {"id": "SSG104_155", "index": 155, "question": "Which words below show emphasis?", "options": {"A": "Significantly, primarily, especially.", "B": "But, however, by contrast.", "C": "For example, to illustrate, like.", "D": "First, second, last."}, "correct": ["A"], "vi_explanation": "A. Significantly, primarily, especially.\nĐây là các trạng từ dùng để nhấn mạnh ý quan trọng trong câu.", "has_visual": false}, {"id": "SSG104_157", "index": 157, "question": "Which of the following behavioral responses is likely to be used?", "options": {"A": "Tolerance.", "B": "Enthusiasm.", "C": "Acceptance.", "D": "Resistance."}, "correct": ["D"], "vi_explanation": "D. Sự phản kháng (Resistance).\nTrong các hệ quả của việc lạm dụng quyền lực ép buộc, phản kháng là phản ứng hành vi điển hình dễ xảy ra.", "has_visual": false}, {"id": "SSG104_166", "index": 166, "question": "Which one is the key component in cooperation?", "options": {"A": "Honesty", "B": "Hard working", "C": "Generosity", "D": "Trust"}, "correct": ["D"], "vi_explanation": "D. Niềm tin (Trust).\nHợp tác bền vững đòi hỏi các bên tin tưởng vào thiện chí và cam kết của nhau.", "has_visual": false}, {"id": "SSG104_171", "index": 171, "question": "Some people consider social norms and the opinions of others to help justify their own positions in life, some others consider_____to perform better.", "options": {"A": "opinions and similarity.", "B": "performance and abilities.", "C": "opinions and values.", "D": "similarity and friendliness."}, "correct": ["B"], "vi_explanation": "B. Thành tích và năng lực (performance and abilities).\nTheo thuyết so sánh xã hội, con người vừa đối chiếu quan điểm vừa đối chiếu năng lực thực tế với người khác.", "has_visual": false}, {"id": "SSG104_178", "index": 178, "question": "When people can boost their own self-evaluations by comparing themselves to others ranked lower in a company, they are having", "options": {"A": "life side effect", "B": "bad behaviour", "C": "self-enhanced effect", "D": "self-evaluation maintenance"}, "correct": ["C"], "vi_explanation": "C. Hiệu ứng tự nâng cao bản thân (self-enhanced effect).\nSo sánh xuống (downward comparison) với người có vị trí thấp hơn giúp tăng cảm giác tự tin về giá trị bản thân.", "has_visual": false}, {"id": "SSG104_185", "index": 185, "question": "Which of the following domains of learning skills means \"What you should care about'?", "options": {"A": "Cognitive domain", "B": "Affective domain", "C": "Psychomotor domain", "D": "Reflective domain"}, "correct": ["B"], "vi_explanation": "B. Lĩnh vực Cảm xúc/Thái độ (Affective domain).\nAffective liên quan đến giá trị, thái độ và những điều bạn thực sự quan tâm; Cognitive là biết gì, Psychomotor là làm được gì.", "has_visual": false}, {"id": "SSG104_192", "index": 192, "question": "What does it help you by asking \"What don't I see?\"?", "options": {"A": "Clarifying the way information was constructed.", "B": "Challenging reasoning.", "C": "Uncovering biases.", "D": "Uncovering the position of the speaker."}, "correct": ["C"], "vi_explanation": "C. Khám phá những thiên kiến ẩn giấu (Uncovering biases).\nTự hỏi \"Mình đang bỏ sót góc nhìn nào?\" giúp nhận ra các định kiến hoặc phần thông tin bị che khuất.", "has_visual": false}, {"id": "SSG104_193", "index": 193, "question": "People can claim that they can live independently and separately but they actually have", "options": {"A": "a need to belong.", "B": "a need to be included.", "C": "a need to talk to someone.", "D": "None of these correct."}, "correct": ["A"], "vi_explanation": "A. Nhu cầu được thuộc về (a need to belong).\nCon người là sinh vật xã hội, dù sống độc lập vẫn luôn có nhu cầu gắn kết và được cộng đồng đón nhận.", "has_visual": false}, {"id": "SSG104_203", "index": 203, "question": "Which of the following is NOT a way to combat stress?", "options": {"A": "Take proper physical care of yourself", "B": "Prioritize your time", "C": "Avoid drugs and alcohol", "D": "Drop out of clubs or extracurricular activities"}, "correct": ["D"], "vi_explanation": "D. Bỏ hết các câu lạc bộ hay hoạt động ngoại khóa.\nHoạt động ngoại khóa lành mạnh giúp kết nối xã hội và giải tỏa áp lực; bỏ hết chúng dễ gây cô lập hơn.", "has_visual": false}, {"id": "SSG104_208", "index": 208, "question": "Learning objectives are ____________________ . that specify what someone will know, care about, or be able to do as a result of a learning experience.", "options": {"A": "Goals.", "B": "Purposes.", "C": "Targets.", "D": "lans."}, "correct": ["A"], "vi_explanation": "A. Mục tiêu (Goals).\nLearning objectives là các mục tiêu cụ thể mô tả người học sẽ biết, quan tâm hoặc làm được gì sau bài học.", "has_visual": false}, {"id": "SSG104_219", "index": 219, "question": "In which of the following skill levels would you judge, check and critique the value of material?", "options": {"A": "Applying", "B": "Analyzing", "C": "Evaluating", "D": "Creating"}, "correct": ["C"], "vi_explanation": "C. Đánh giá (Evaluating).\nĐánh giá, kiểm tra và phê bình giá trị của thông tin dựa trên tiêu chí là đặc trưng của mức Evaluating.", "has_visual": false}, {"id": "SSG104_221", "index": 221, "question": "Choose the best answer for this question \"Why should we hire you?\" (Soạn bởi Thủy Tiên)", "options": {"A": "Nothing! I'm perfect!", "B": "I am a professional in this way", "C": "I'd really love to bring my diverse skill set to your company-", "D": "l deserved"}, "correct": ["C"], "vi_explanation": "C. \"Tôi rất mong muốn mang bộ kỹ năng đa dạng của mình đóng góp cho công ty.\"\nCâu trả lời vừa tự tin, khiêm tốn vừa gắn năng lực cá nhân với lợi ích của doanh nghiệp.", "has_visual": false}, {"id": "SSG104_223", "index": 223, "question": "Social comparison can lead to", "options": {"A": "impaots on self—esteem, feeling of victory, feeling of humbleness", "B": "impacts on self—esteem, feeling of envy, feeling of regret", "C": "impacts on self—esteem, feeling of love, feeling of being superior", "D": "Impacts on self-satisfaction, self—esteem, feeling of loser"}, "correct": ["B"], "vi_explanation": "B. Tác động đến lòng tự trọng, cảm giác ghen tị và cảm giác hối tiếc.\nSo sánh xã hội mang lại cả ảnh hưởng tích cực lẫn các cảm xúc tiêu cực như tự ti, đố kỵ hay tiếc nuối.", "has_visual": false}, {"id": "SSG104_228", "index": 228, "question": "Which of the following is incorrect about cultural intelligence?", "options": {"A": "Cultural intelligence develops as people become more aware of the influence of culture.", "B": "A competency and skill known as cultural intelligence enables people to work and behave effectively in cross-cultural settings.", "C": "Cultural intelligence is merely developed through travelling experience.", "D": "Adapting an individual's behavior to the norms of other cultures shows an aspect of cultural intelligence."}, "correct": ["C"], "vi_explanation": "C. \"Trí tuệ văn hóa chỉ đơn thuần phát triển qua đi du lịch\" là SAI.\nCultural intelligence còn được rèn luyện qua đọc sách, làm việc đa văn hóa, học hỏi và tự điều chỉnh hành vi.", "has_visual": false}, {"id": "SSG104_231", "index": 231, "question": "People who consider upward comparison as a threat, have", "options": {"A": "negative mindset.", "B": "growth mindset.", "C": "fixed mindset.", "D": "jealous feelings."}, "correct": ["C"], "vi_explanation": "C. Tư duy cố định (fixed mindset).\nNgười mang tư duy cố định sợ người giỏi hơn đe dọa giá trị bản thân thay vì xem họ là động lực học hỏi (growth mindset).", "has_visual": false}, {"id": "SSG104_233", "index": 233, "question": "What are the basics when making social comparison?", "options": {"A": "Similarity and compliance.", "B": "Openness and friendliness.", "C": "Relevance and similarity.", "D": "Self-esteem and independence."}, "correct": ["C"], "vi_explanation": "C. Mức độ liên quan và sự tương đồng (Relevance and similarity).\nHai điều kiện nền tảng quyết định ta chọn ai làm đối tượng so sánh xã hội.", "has_visual": false}, {"id": "SSG104_235", "index": 235, "question": "______________ is \"the ability to judge, check, and even critique the value of material for a given pur", "options": {"A": "Applying", "B": "Evaluating", "C": "Analyzing", "D": "Creating"}, "correct": ["B"], "vi_explanation": "B. Đánh giá (Evaluating).\nKhả năng phán xét, kiểm chứng và phản biện giá trị tài liệu cho mục tiêu nhất định thuộc bậc Evaluating.", "has_visual": false}, {"id": "SSG104_236", "index": 236, "question": "As a Software Engineering student, you will be able to explain at a basic level the concepts architecture, operating systems, computer networks, databases... Which learning-skill stage Taxonomy do they refer to?", "options": {"A": "Applying", "B": "Understanding", "C": "Analyzing", "D": "Evaluating"}, "correct": ["B"], "vi_explanation": "B. Hiểu (Understanding).\nViệc giải thích được các khái niệm cơ bản bằng lời của mình chứng tỏ người học đã nắm được bản chất ở mức Understanding.", "has_visual": false}, {"id": "SSG104_253", "index": 253, "question": "What is the final best practice for boosting multicultural skills?", "options": {"A": "Developing cultural intelligence", "B": "Developing cognitive complexity", "C": "Developing cultural competence", "D": "Developing cross-cultural skills"}, "correct": ["B"], "vi_explanation": "B. Phát triển độ phức tạp nhận thức (Developing cognitive complexity).\nĐây là kỹ năng bậc cao cuối cùng giúp nhìn nhận một vấn đề đa văn hóa dưới nhiều lăng kính tinh tế thay vì rập khuôn. (Kèm ảnh sơ đồ.)", "has_visual": true, "image_local": "images/SSG104_253.png", "images": ["https://o.quizlet.com/QtCXh9hTnSxlysgct-OPvA_m.png"]}, {"id": "SSG104_259", "index": 259, "question": "What is NOT TRUE about the effect of upward comparison?", "options": {"A": "Dissatisfaction.", "B": "Inspiration.", "C": "Gratitude.", "D": "Envy."}, "correct": ["C"], "vi_explanation": "C. Lòng biết ơn (Gratitude).\nSo sánh lên (Upward comparison) thường tạo cảm hứng phấn đấu hoặc cảm giác bất mãn, đố kỵ — không đặc trưng bởi lòng biết ơn.", "has_visual": false}, {"id": "SSG104_262", "index": 262, "question": "Which technology can help students establish a sense of community with their class and engage in ongoing threaded conversations on assigned readings and topics highlighting diverse points of view?", "options": {"A": "Interactive whiteboards", "B": "Discussion boards", "C": "Student-response systems", "D": "Digital camcorders"}, "correct": ["B"], "vi_explanation": "B. Diễn đàn thảo luận trực tuyến (Discussion boards).\nGiúp sinh viên trao đổi luồng bình luận sâu sắc theo từng chủ đề bài đọc và lắng nghe góc nhìn đa dạng.", "has_visual": false}, {"id": "SSG104_271", "index": 271, "question": "What can be inferred from the Dunning-Kruger Effect?", "options": {"A": "The unskilled people are more likely to underestimate their own abilities.", "B": "Top performers are more likely to underestimate their own abilities.", "C": "The least experienced and knowledgeable people are not likely to overestimate their own abilities.", "D": "Experts tend to overestimate their own abilities."}, "correct": ["B"], "vi_explanation": "B. Những người làm tốt nhất (top performers) lại thường đánh giá thấp năng lực bản thân hơn thực tế.\nVì họ hiểu lĩnh vực đó sâu nên biết còn nhiều điều mình chưa giỏi, ngược lại người kém lại quá tự tin.", "has_visual": false}, {"id": "SSG104_277", "index": 277, "question": "One of the key findings in the Dunning-Kruger effect experiments is top performers tend to", "options": {"A": "overestimate their skills.", "B": "rank themselves above average.", "C": "underestimate their skills.", "D": "always satisfied with results."}, "correct": ["C"], "vi_explanation": "C. Đánh giá thấp kỹ năng của chính mình (underestimate their skills).\nĐặc trưng của hiệu ứng Dunning–Kruger ở nhóm năng lực cao là họ cho rằng người khác cũng dễ dàng làm được như mình.", "has_visual": false}, {"id": "SSG104_282", "index": 282, "question": "In order to make good impression, positive words convey optimism and confidence are", "options": {"A": "regret, sorry, terror.", "B": "trouble, unable, happy.", "C": "wrong, obnoxious, yes.", "D": "willing, thank, appreciate."}, "correct": ["D"], "vi_explanation": "D. willing, thank, appreciate.\nĐây là nhóm từ tích cực thể hiện sự sẵn lòng, biết ơn và chuyên nghiệp, trái ngược với các từ tiêu cực ở A, B, C.", "has_visual": false}, {"id": "SSG104_290", "index": 290, "question": "What is NOT a strategy to develop yourself as a critical thinker?", "options": {"A": "Scheduling physical activity into your day.", "B": "Challenge yourself to see familiar things in new ways.", "C": "Express yourself.", "D": "No thought during leisure time."}, "correct": ["D"], "vi_explanation": "D. \"Không suy nghĩ gì trong thời gian rảnh\" không phải cách rèn tư duy phản biện.\nRèn luyện đòi hỏi vận động thể chất, tự phản tỉnh, diễn đạt ý kiến và nhìn sự vật theo góc mới.", "has_visual": false}, {"id": "SSG104_291", "index": 291, "question": "Strategy (ies) to develop yourself as a critical thinker", "options": {"A": "Redefine the way you see things", "B": "Reflect and practice", "C": "Express yourself", "D": "All are correct"}, "correct": ["D"], "vi_explanation": "D. Tất cả các chiến lược trên đều đúng.\nTái định nghĩa góc nhìn, suy ngẫm thực hành và bày tỏ quan điểm đều giúp nâng cao tư duy phản biện.", "has_visual": false}, {"id": "SSG104_297", "index": 297, "question": "PDCA stands for:", "options": {"A": "Plan-demonstrate check - articulate.", "B": "Prepare-demonstrate - calibrate - act.", "C": "Plan-do check - act.", "D": "Prepare-do-check-act."}, "correct": ["C"], "vi_explanation": "C. Plan – Do – Check – Act.\nChu trình cải tiến liên tục 4 bước (Lập kế hoạch – Thực hiện – Kiểm tra – Điều chỉnh) của Deming.", "has_visual": false}, {"id": "SSG104_303", "index": 303, "question": "Which of the following intervention techniques should be used sparingly?", "options": {"A": "Adaptation.", "B": "Structural.", "C": "Managerial.", "D": "Voluntary or involuntary removal."}, "correct": ["C"], "vi_explanation": "C. Can thiệp bằng quyền quản lý (Managerial).\nGiảng viên/quản lý trực tiếp đứng ra dàn xếp chỉ nên dùng hạn chế khi nhóm tự giải quyết không nổi, tránh tạo tâm lý ỷ lại.", "has_visual": false}, {"id": "SSG104_328", "index": 328, "question": "Which is TRUE about short-term orientation culture?", "options": {"A": "Many countries in Asia value a short-term orientation.", "B": "If you work within a culture that has a short-term orientation, you may need to place greater emphasis on reciprocation of greetings, gifts, and rewards.", "C": "Short-term orientation is often marked by persistence, thrift and frugality, and an order to relationships based on age and status.", "D": "All of these."}, "correct": ["B"], "vi_explanation": "B. Cần chú trọng nhiều hơn đến việc đáp lễ qua lời chào, quà tặng và phần thưởng tức thì.\nVăn hóa định hướng ngắn hạn (Short-term orientation) coi trọng kết quả trước mắt và nghi thức trao đổi qua lại, khác với dài hạn ở các nước Đông Á (C).", "has_visual": false}, {"id": "SSG104_335", "index": 335, "question": "What is TRUE about divergent cultural dimensions? (choose 2 options)", "options": {"A": "Cultural viewpoint is a continuum or range.", "B": "Tension may arise as cultural expectations precede the interaction.", "C": "The masculine-feminine dichotomy examines the extent to which men or women hold the culture.", "D": "Some cultures which are highly tolerant of uncertainty tend to be resistant to change and risks."}, "correct": ["A", "B"], "vi_explanation": "A, B. Quan điểm văn hóa trải trên một dải liên tục (continuum) và căng thẳng có thể nảy sinh từ kỳ vọng văn hóa trước khi tương tác.\nC và D mô tả sai lệch về chiều kích nam tính–nữ tính và mức độ né tránh rủi ro.", "has_visual": false}, {"id": "SSG104_339", "index": 339, "question": "What is the negative effect of downward comparison?", "options": {"A": "Envy.", "B": "Dissatisfaction.", "C": "Scorn.", "D": "Pessimistic."}, "correct": ["C"], "vi_explanation": "C. Sự khinh thường/coi nhẹ người khác (Scorn).\nKhi so sánh xuống (downward comparison) với người kém hơn, mặt trái tiêu cực là dễ sinh tâm lý tự cao và coi thường họ. (Kèm xem ảnh.)", "has_visual": true, "image_local": "images/SSG104_339.jpg", "images": ["https://o.quizlet.com/3Uu.zB4GKZt8sl8RX7VT.g_m.jpg"]}, {"id": "SSG104_344", "index": 344, "question": "What is an action Plan?", "options": {"A": "A list of specific steps needed to be done to reach a goal.", "B": "An exercise program to increase your strength.", "C": "A list of goals that need to be reached to obtain a vision.", "D": "The result of a self-assessment."}, "correct": ["A"], "vi_explanation": "A. Danh sách các bước hành động cụ thể cần làm để đạt mục tiêu.\nAction plan biến mục tiêu chung thành đầu việc rõ ràng có thể thực thi.", "has_visual": false}, {"id": "SSG104_348", "index": 348, "question": "The best way to convey friendliness is to..", "options": {"A": "smile.", "B": "speak slowly.", "C": "tell a joke.", "D": "use a tone of importance."}, "correct": ["A"], "vi_explanation": "A. Mỉm cười (smile).\nNụ cười tự nhiên là tín hiệu phi ngôn ngữ đơn giản và hiệu quả nhất thể hiện sự thân thiện.", "has_visual": false}, {"id": "SSG104_349", "index": 349, "question": "Which effect describes best this statement \"People in general had a better academic self-concept if they were a big frog in a small pond rather than a small frog in a large one\"", "options": {"A": "Crowd psychology effect", "B": "Frog Pond Effect", "C": "Dunning-Kruger Effect", "D": "Greenhouse effect"}, "correct": ["B"], "vi_explanation": "B. Hiệu ứng Con ếch trong ao nhỏ (Frog Pond Effect).\nHọc sinh có xu hướng tự tin về học lực hơn khi đứng đầu một môi trường nhỏ so với đứng giữa trong môi trường toàn người xuất sắc.", "has_visual": false}, {"id": "SSG104_350", "index": 350, "question": "The \"Psychomotor Domain\" of learning skills means", "options": {"A": "What you should know.", "B": "What you should care about.", "C": "What you should be able to do.", "D": "None of these is correct."}, "correct": ["C"], "vi_explanation": "C. Những gì bạn có thể làm được (What you should be able to do).\nPsychomotor gắn với kỹ năng thực hành/thao tác; Cognitive là biết gì (know) và Affective là quan tâm gì (care).", "has_visual": false}, {"id": "SSG104_352", "index": 352, "question": "When do you need to work alone?", "options": {"A": "Highly complex tasks or problems", "B": "Minimum discretion is required", "C": "High level of choice and uncertainty", "D": "Decisions by consensus are essential"}, "correct": ["B"], "vi_explanation": "B. Khi công việc ít đòi hỏi quyền tự quyết linh hoạt (Minimum discretion is required).\nCông việc đơn giản, quy chuẩn sẵn không cần thảo luận đồng thuận hay phối hợp phức tạp thì làm một mình hiệu quả hơn.", "has_visual": false}]}, {"id": "thinking", "title": "Tư duy phản biện, Sáng tạo & Bloom", "tag": "Phản biện & Bloom", "questions": [{"id": "SSG104_009", "index": 9, "question": "To write an effective proposal, which rhetorical element(s) does the writer have to maintain?", "options": {"A": "Ethos, Hathos and Logic", "B": "Athos, Pathos and Logos", "C": "Ethos, Pathos and Logos", "D": "Ethic, Participation and Logic"}, "correct": ["C"], "vi_explanation": "C. Ethos (uy tín), Pathos (cảm xúc) và Logos (lý trí/logic).\nĐây là 3 yếu tố tu từ học kinh điển của Aristotle giúp bài đề xuất (proposal) có sức thuyết phục toàn diện.", "has_visual": false}, {"id": "SSG104_011", "index": 11, "question": "What is a straw man fallacy?", "options": {"A": "a weak argument set up to be easily refuted, distracting attention from stronger arguments", "B": "state or assert that something is the case, typically without providing evidence or proof.", "C": "when multiple partners work together toward a common goal that will benefit everyone", "D": "a group of players forming one side in a competitive game or sport"}, "correct": ["A"], "vi_explanation": "A. Ngụy biện bù nhìn (Straw man): dựng lên một phiên bản yếu hơn của luận điểm đối phương để dễ dàng bác bỏ.\nCách này đánh lạc hướng khỏi lập luận cốt lõi thực sự của người đối diện.", "has_visual": false}, {"id": "SSG104_028", "index": 28, "question": "Which statement IS NOT TRUE about social comparison?", "options": {"A": "Social comparison can provide the push you need to rise to the occasion and increase your motivation, therefore making progress toward your goals-", "B": "Social comparison has many negative aspects", "C": "Social comparison is a natural psychological tendency", "D": "It is an ugly phenomenon to be avoided"}, "correct": ["D"], "vi_explanation": "D. \"So sánh xã hội là hiện tượng xấu xa cần né tránh hoàn toàn\" là SAI.\nĐây là xu hướng tâm lý tự nhiên của con người và có thể tạo động lực phấn đấu nếu biết kiểm soát.", "has_visual": false}, {"id": "SSG104_030", "index": 30, "question": "Which of the following is the best option for an abstract in a report?", "options": {"A": "The \"Love yourself\" project is an initiative project that involves activities aim at assisting college students from universities in Vietnam. It primary goal is to provide a platform for students to express their inner thoughts and feelings and activites to takecare themself, along with activities for sharing, identifying, and providing timely support for psychological issues faced by students. Consequently, the project aims to create a comfortable environment for students to practice mindfulness and takecare physical and mental health.", "B": "The \"Love yourself\" project is implemented by students of FPT Can Tho University", "C": "The \"Love yourself\" project will implementation within 6 weeks", "D": "The \"Love yourself\" project has five expected results"}, "correct": ["A"], "vi_explanation": "A. Tóm tắt đầy đủ mục tiêu cốt lõi, đối tượng hưởng lợi và tác động chính của dự án.\nCác lựa chọn B, C, D quá sơ sài, chỉ nêu 1 chi tiết vụn vặt thay vì khái quát toàn dự án.", "has_visual": false}, {"id": "SSG104_032", "index": 32, "question": "\"Circular argument\" is a type of fallcies in which:", "options": {"A": "A weak argument set up to be easily refuted, distracting attention from stronger arguments", "B": "The proposition is used to prove itself. Assumes the very thing it aims to prove.", "C": "Appeals to a common belief of some people, often prejudicial, and states everyone holds this belief. Also called the Bandwagon Fallacy, as people \"jump on the bandwagon\" of a perceived popular view.", "D": "We claimthe truth of the very matter in question, as if it were already an obvious conclusion."}, "correct": ["B"], "vi_explanation": "B. Lập luận vòng quanh (Circular argument): dùng chính điều cần chứng minh để làm bằng chứng cho nó.\nVí dụ điển hình là kết luận quay ngược lại giả định ban đầu mà không có chứng cứ độc lập.", "has_visual": false}, {"id": "SSG104_055", "index": 55, "question": "How do critical thinking and creative thinking complement each other in a university team project?", "options": {"A": "They compete for dominance, hindering the team's progress.", "B": "Critical thinking accompanying creative thinking fosters fresh perspectives to look at problems and Situations.", "C": "Creative thinking solely focuses on intuition, while critical thinking emphasizes logical analysis.", "D": "Critical and creative thinking are separate and don't contribute to each other in a team context."}, "correct": ["B"], "vi_explanation": "B. Tư duy phản biện kết hợp tư duy sáng tạo mở ra góc nhìn mới mẻ khi giải quyết vấn đề.\nHai dạng tư duy bổ trợ lẫn nhau: sáng tạo giúp nảy ý tưởng, phản biện giúp sàng lọc và hoàn thiện ý tưởng.", "has_visual": false}, {"id": "SSG104_056", "index": 56, "question": "In which way does \"Wikis\" contribute to our ability to be critical and creative thinkers?", "options": {"A": "Wikis can help students coordinate, compile, synthesize, and present individual or group projects or research.", "B": "Wikis can help students build and share group resources and knowledge.", "C": "Wikis can help students provide peer review, feedback, and critiques.", "D": "All of these are correct"}, "correct": ["D"], "vi_explanation": "D. Tất cả các ý trên đều đúng.\nWiki hỗ trợ làm việc chung, chia sẻ kho tri thức và nhận xét chéo lẫn nhau hiệu quả.", "has_visual": false}, {"id": "SSG104_058", "index": 58, "question": "Which is NOT a fiction about Creative Thinking?", "options": {"A": "Every problem has only one solution or one right answer", "B": "The best answer or solution or method has already been discovered", "C": "Creative answers are technologically complex", "D": "Creative solution should be answer for all problems"}, "correct": ["D"], "vi_explanation": "D. \"Giải pháp sáng tạo phải trả lời được mọi vấn đề\" là lựa chọn được chốt theo đáp án chuẩn của giảng viên.\nLưu ý các câu A, B, C đều là những lầm tưởng phổ biến về tư duy sáng tạo; bộ đề chọn D theo đáp án giảng viên cung cấp.", "has_visual": false}, {"id": "SSG104_062", "index": 62, "question": "Which action does belong to the strategy 'Identify available solutions'?", "options": {"A": "Identify the problem", "B": "Organize the information logically", "C": "Compare and contrast possible solutions", "D": "Defend your solution"}, "correct": ["C"], "vi_explanation": "C. So sánh và đối chiếu các giải pháp khả thi.\nBước xác định giải pháp khả thi (Identify available solutions) gồm liệt kê và so sánh ưu nhược điểm các phương án.", "has_visual": false}, {"id": "SSG104_080", "index": 80, "question": "In a communication transaction, feedback represents", "options": {"A": "a group's physical and psychological environment.", "B": "anything that interferes with or inhibits effective communication.", "C": "the media through which group members share messages.", "D": "the response or reaction to a message-"}, "correct": ["D"], "vi_explanation": "D. Phản hồi hoặc sự đáp lại đối với một thông điệp.\nTrong mô hình truyền thông, feedback là tín hiệu người nhận gửi ngược lại để người gửi biết thông điệp được tiếp nhận ra sao.", "has_visual": false}, {"id": "SSG104_081", "index": 81, "question": "Among the tips for creative thinking, what does \"Sensing\" mean?", "options": {"A": "Be a good observer of people, nature, and events around you", "B": "Be em pathetic with other people", "C": "Have more fun learning", "D": "Be open to insight as ideas pop into your mind"}, "correct": ["A"], "vi_explanation": "A. Quan sát tinh tế con người, thiên nhiên và sự việc xung quanh.\n\"Sensing\" trong sáng tạo nhấn mạnh việc dùng các giác quan thu thập chất liệu từ đời sống.", "has_visual": false}, {"id": "SSG104_093", "index": 93, "question": "How can develop your creative thinking skill through \"Drawing\"?", "options": {"A": "Develop ideas and expand their possibilities", "B": "Use mind-mapping to capture ideas", "C": "Explain how your ideas move beyond the status quo and contribute to a discussion", "D": "Take notes"}, "correct": ["B"], "vi_explanation": "B. Dùng sơ đồ tư duy (mind-mapping) để nắm bắt ý tưởng.\nVẽ sơ đồ nhánh giúp trực quan hóa mối liên kết giữa các ý tưởng trong quá trình sáng tạo. (Kèm xem ảnh minh họa đính kèm.)", "has_visual": true, "image_local": "images/SSG104_093.png", "images": ["https://o.quizlet.com/82pKHG.O4p-d7IMCPYJXww_m.png"]}, {"id": "SSG104_095", "index": 95, "question": "Which of the following are brainstorm tips for creative thinking?", "options": {"A": "Sensing, thinking.", "B": "Imagining and drawing.", "C": "Moving resting, speaking and writing.", "D": "All of the above."}, "correct": ["D"], "vi_explanation": "D. Tất cả các đáp án trên đều đúng.\nCác mẹo kích thích sáng tạo bao gồm quan sát, suy ngẫm, tưởng tượng, vẽ, vận động, nghỉ ngơi, nói và viết.", "has_visual": false}, {"id": "SSG104_102", "index": 102, "question": "In the process of writing an essay to demonstrate your position in the issue of going for or against the Covid-19 vaccine, you compare and contrast different arguments given by both sides- Which problem-solving strategy do you use in this case?", "options": {"A": "Define the problem", "B": "Identify available solutions", "C": "Select your solution", "D": "Examine alternative solutions"}, "correct": ["D"], "vi_explanation": "D. Xem xét các giải pháp thay thế (Examine alternative solutions).\nSo sánh, đối chiếu lập luận từ cả hai phía ủng hộ và phản đối là bước cân nhắc các phương án thay thế.", "has_visual": false}, {"id": "SSG104_103", "index": 103, "question": "When you solve a problem with oritioal thinking, what is the first main step that you should take?", "options": {"A": "Call for help", "B": "Define the problem", "C": "Get a bite to eat", "D": "Identify possible solutions"}, "correct": ["B"], "vi_explanation": "B. Xác định rõ vấn đề (Define the problem).\nTrước khi tìm giải pháp hay hành động, bước đầu tiên luôn là hiểu đúng bản chất vấn đề cần giải quyết.", "has_visual": false}, {"id": "SSG104_119", "index": 119, "question": "Which strategy of evaluating information with critical thinking requires you to ask and answer such logic questions as \"What question are we trying to answer?\", \"What point of view is being expressed?\" and \"What are the implications?\"?", "options": {"A": "Read for understanding by using text coding", "B": "Examine arguments", "C": "Clarify thinking", "D": "Cultivate \"habits of mind\""}, "correct": ["C"], "vi_explanation": "C. Làm rõ tư duy (Clarify thinking).\nĐặt các câu hỏi về mục tiêu câu hỏi, góc nhìn và hệ quả giúp làm sáng tỏ mạch lập luận của thông tin. (Kèm xem ảnh slide.)", "has_visual": true, "image_local": "images/SSG104_119.jpg", "images": ["https://o.quizlet.com/NPjLCb3o8fo2wrIx8SrNUw_m.jpg"]}, {"id": "SSG104_120", "index": 120, "question": "Which of the following is not a cognitive skill level?", "options": {"A": "Understanding.", "B": "Remembering.", "C": "Guiding.", "D": "Applying."}, "correct": ["C"], "vi_explanation": "C. Guiding (Hướng dẫn) không phải một cấp độ nhận thức trong thang Bloom.\nThang Bloom gồm: Remembering, Understanding, Applying, Analyzing, Evaluating, Creating.", "has_visual": false}, {"id": "SSG104_123", "index": 123, "question": "Why do people join in different groups? (chọn 2 đáp án)", "options": {"A": "Groups meet their psychological needs", "B": "Groups meet their social needs", "C": "People can reduce the insecurity of \"standing alone\".", "D": "People feel stronger"}, "correct": ["A", "B"], "vi_explanation": "A, B. Con người tham gia nhóm để đáp ứng nhu cầu tâm lý và nhu cầu xã hội.\nNhóm vừa mang lại cảm giác gắn bó vừa giúp thỏa mãn nhu cầu tương tác và hỗ trợ tâm lý.", "has_visual": false}, {"id": "SSG104_129", "index": 129, "question": "Which needs is the highest in Maslow's Hierarchy?", "options": {"A": "Physiological Needs.", "B": "Esteem Needs.", "C": "Self Actualization Needs.", "D": "Safety Needs."}, "correct": ["C"], "vi_explanation": "C. Nhu cầu tự thể hiện bản thân (Self Actualization Needs).\nĐây là đỉnh cao nhất trong tháp 5 tầng nhu cầu của Maslow.", "has_visual": false}, {"id": "SSG104_130", "index": 130, "question": "What is critical thinking?", "options": {"A": "Memorizing.", "B": "Group thinking.", "C": "Skepticism, examining assumptions, challenging reasoning and uncovering bioses.", "D": "Blind acceptance of authority."}, "correct": ["C"], "vi_explanation": "C. Hoài nghi có cơ sở, kiểm tra giả định, chất vấn lập luận và vạch trần thiên kiến.\nĐây là bản chất cốt lõi của tư duy phản biện, khác với học vẹt hay nghe theo mù quáng.", "has_visual": false}, {"id": "SSG104_131", "index": 131, "question": "What is Critical thinking?", "options": {"A": "Is clear, reasonable; reflective thinking focused on deciding what to believe or do", "B": "Is a way of thinking to criticize what other people say", "C": "Is reflective thinking focused on claiming and proving other people your ideas or opinions", "D": "ls simple thinking that memorizing facts or blindly accepting what you hear or read"}, "correct": ["A"], "vi_explanation": "A. Tư duy rõ ràng, hợp lý và có suy ngẫm để quyết định nên tin hoặc làm gì.\nĐịnh nghĩa kinh điển về Critical Thinking nhấn mạnh tính lý trí và tự phản tỉnh.", "has_visual": false}, {"id": "SSG104_134", "index": 134, "question": "Which of the following are attributes of a creative thinker? (Select 3 options)", "options": {"A": "Imaginative", "B": "Curious", "C": "Sluggish", "D": "Optimistic", "E": "Imitative"}, "correct": ["A", "B", "D"], "vi_explanation": "A, B, D. Giàu trí tưởng tượng, tò mò và lạc quan là phẩm chất tiêu biểu của người tư duy sáng tạo.\nLười biếng (Sluggish) hay bắt chước rập khuôn (Imitative) đi ngược lại tinh thần sáng tạo.", "has_visual": false}, {"id": "SSG104_138", "index": 138, "question": "Which pieces of technology are likely to help users increase their critical and creative thinking skills during the stage of Understanding in the Bloom's taxonomy? (choose 2 options)", "options": {"A": "Lectora.", "B": "Email.", "C": "Youtube.", "D": "Flickr."}, "correct": ["A", "C"], "vi_explanation": "A, C. Lectora và YouTube giúp trình bày bài giảng, video trực quan hỗ trợ người học hiểu sâu kiến thức (mức Understanding trong thang Bloom).\nEmail và Flickr thiên về gửi thư và lưu trữ ảnh.", "has_visual": false}, {"id": "SSG104_146", "index": 146, "question": "What are the characteristics of Critical Thinking?", "options": {"A": "Examining assumptions.", "B": "Challenging reasoning.", "C": "Uncovering biases.", "D": "All of these are correct."}, "correct": ["D"], "vi_explanation": "D. Tất cả các đặc điểm trên đều đúng.\nTư duy phản biện luôn bao gồm kiểm tra giả định, chất vấn lập luận và nhận diện thiên kiến.", "has_visual": false}, {"id": "SSG104_159", "index": 159, "question": "What is NOT a characteristic of the Creating stage in the Bloom's Taxonomy?", "options": {"A": "You are able to put parts together to form a coherent or unique new whole.", "B": "You implement the material in new and concrete situations.", "C": "You can reorganize elements into a new pattern or structure.", "D": "You use methods of generating, planning, or producing."}, "correct": ["B"], "vi_explanation": "B. \"Áp dụng kiến thức vào tình huống cụ thể mới\" thuộc mức Applying chứ không phải Creating.\nBậc Creating (Sáng tạo) tập trung lắp ghép, tổ chức lại các phần thành cấu trúc hoàn toàn mới.", "has_visual": false}, {"id": "SSG104_160", "index": 160, "question": "According to Bloom's Taxonomy, is \"the ability to put parts together to form a coherent or unique new whole\".", "options": {"A": "Applying", "B": "Analyzing", "C": "Evaluating", "D": "Creating"}, "correct": ["D"], "vi_explanation": "D. Creating (Sáng tạo).\nĐúng định nghĩa bậc cao nhất của thang Bloom: kết hợp các yếu tố thành một chỉnh thể mới mẻ và độc đáo.", "has_visual": false}, {"id": "SSG104_161", "index": 161, "question": "What is pattern of thought?", "options": {"A": "Is the mental process you use to form associations and models of the world", "B": "Is the mark of an educated mind to be able to entertain a thought without accepting it", "C": "Is the act of thinking that produces thoughts, which arise as ideas, images, sounds, or even emotions", "D": "Is the manipulation of information to form concepts, to engage in problem-solving, to reason, and to make decisions"}, "correct": ["A"], "vi_explanation": "A. Quá trình tâm trí hình thành các liên kết và mô hình nhận thức về thế giới.\nPattern of thought là khuôn mẫu suy nghĩ giúp não bộ phân loại và xử lý thông tin quen thuộc.", "has_visual": false}, {"id": "SSG104_167", "index": 167, "question": "You are given a task to design a poster for an upcoming event at your university. You decide to visit a botanic garden for inspiration. Which tip of creative thinking do you seem to use in this case?", "options": {"A": "Sensing", "B": "Imagining", "C": "Moving", "D": "Leaming"}, "correct": ["A"], "vi_explanation": "A. Sensing (Quan sát/Cảm nhận thực tế).\nĐi tham quan vườn thực vật để lấy cảm hứng thị giác cho thiết kế poster là vận dụng giác quan thu thập chất liệu.", "has_visual": false}, {"id": "SSG104_170", "index": 170, "question": "Which of the following statements is NOT correct about a creative thinker?", "options": {"A": "Be curious, optimistic.", "B": "See problems as limits of development.", "C": "Always challenge assumptions and suspend judgment.", "D": "Be imaginative."}, "correct": ["B"], "vi_explanation": "B. \"Xem vấn đề là giới hạn cản trở phát triển\" là SAI.\nNgười có tư duy sáng tạo coi vấn đề là cơ hội để tìm hướng đi mới mẻ hơn.", "has_visual": false}, {"id": "SSG104_184", "index": 184, "question": "What are three main categories or \"domains\" of the learning skills?", "options": {"A": "Cognitive domain, Affective domain, Reflective domain.", "B": "Cognitive domain, Affective domain, Proactive domain.", "C": "Cognitive domain, Affective domain, Psychomotor domain.", "D": "Cognitive domain, Reflective domain, Psychomotor domain."}, "correct": ["C"], "vi_explanation": "C. Nhận thức (Cognitive), Cảm xúc/Thái độ (Affective) và Tâm vận động/Kỹ năng (Psychomotor).\nĐây là 3 lĩnh vực kinh điển trong hệ thống phân loại mục tiêu học tập của Bloom.", "has_visual": false}, {"id": "SSG104_186", "index": 186, "question": "What does Ethos refer to?", "options": {"A": "Credibility and ethics.", "B": "Passion and enthusiasm.", "C": "Logic or reason.", "D": "Emotion and generosity."}, "correct": ["A"], "vi_explanation": "A. Uy tín và đạo đức của người nói/viết (Credibility and ethics).\nEthos thuyết phục người đọc nhờ chuyên môn, sự trung thực và đáng tin cậy.", "has_visual": false}, {"id": "SSG104_187", "index": 187, "question": "Which statement is NOT true about creativity?", "options": {"A": "All humans are innately creative, especially if creativity is understood as a problem-solving skill.", "B": "As a creative thinker, you are curious, optimistic, and imaginative.", "C": "Creativity is inspired when there is a problem to solve.", "D": "Human is not innately creative."}, "correct": ["D"], "vi_explanation": "D. \"Con người vốn dĩ không có tính sáng tạo bẩm sinh\" là SAI.\nMỗi người đều có khả năng sáng tạo bẩm sinh, đặc biệt khi cần giải quyết vấn đề.", "has_visual": false}, {"id": "SSG104_196", "index": 196, "question": "Which of the following is a step to stimulate the creative thinking?", "options": {"A": "Allow your mind to wander a few times everyday", "B": "Trust that it will all work out", "C": "Resist the urge to investigate", "D": "Tackle everything at once"}, "correct": ["A"], "vi_explanation": "A. Cho phép tâm trí lang thang suy nghĩ tự do vài lần mỗi ngày.\nKhoảng lặng thả lỏng giúp não kết nối các ý tưởng rời rạc một cách tự nhiên.", "has_visual": false}, {"id": "SSG104_207", "index": 207, "question": "___________ is \"the ability to grasp or construct meaning from oral, written, and graphic messages\"..", "options": {"A": "Remembering", "B": "Understanding", "C": "Analyzing", "D": "Applying"}, "correct": ["B"], "vi_explanation": "B. Hiểu (Understanding).\nNắm bắt và rút ra ý nghĩa từ thông điệp nói, viết hoặc hình ảnh là định nghĩa của bậc Understanding trong thang Bloom.", "has_visual": false}, {"id": "SSG104_216", "index": 216, "question": "Which is the highest learning-skill level of Bloom's Taxonomy?", "options": {"A": "Analyze.", "B": "Apply.", "C": "Evaluate.", "D": "Create."}, "correct": ["D"], "vi_explanation": "D. Sáng tạo (Create).\nThứ tự thang Bloom từ thấp lên cao: Remember → Understand → Apply → Analyze → Evaluate → Create.", "has_visual": false}, {"id": "SSG104_241", "index": 241, "question": "What is thought?", "options": {"A": "Is the mental process you use to form associations and models of the world.", "B": "Is the mark of an educated mind to be able to entertain a thought without accepting it.", "C": "Is the act of thinking that produces thoughts, which arise as ideas, images, sounds, or even emotions.", "D": "Is the manipulation of information to form concepts, to engage in problem-solving, to reason, and to make decisions."}, "correct": ["C"], "vi_explanation": "C. Hoạt động suy nghĩ tạo ra ý nghĩ dưới dạng ý tưởng, hình ảnh, âm thanh hoặc cảm xúc.\nPhân biệt với Pattern of thought (A) là mô hình liên kết nhận thức trong não.", "has_visual": false}, {"id": "SSG104_246", "index": 246, "question": "Why are creative thinking skills a type of problem-solving? (choose 2 options)", "options": {"A": "Alternative ideas need to be generated-", "B": "Different assumptions are under scrutiny-", "C": "One needs to use sound reasoning to solve the problem.", "D": "It involves using strategies to clear the mind so that our thoughts and ideas can transcen..limitations of a problem."}, "correct": ["A", "D"], "vi_explanation": "A, D. Cần tạo ra nhiều ý tưởng thay thế và mở rộng tư duy vượt khỏi giới hạn thông thường của vấn đề.\nHai yếu tố này giải thích vì sao tư duy sáng tạo là một công cụ giải quyết vấn đề hiệu quả.", "has_visual": false}, {"id": "SSG104_251", "index": 251, "question": "When you solve a problem with critical thinking, what is the first main step that you should talk..", "options": {"A": "Call for help", "B": "Define the problem", "C": "Get a bite to eat", "D": "Identify possible solutions"}, "correct": ["B"], "vi_explanation": "B. Xác định rõ vấn đề (Define the problem).\nLuôn phải định nghĩa đúng vấn đề trước khi đi tìm nguyên nhân hay giải pháp.", "has_visual": false}, {"id": "SSG104_258", "index": 258, "question": "Which is FALSE about Maslow hierarchy of needs?", "options": {"A": "Maslcw's i-fierarchy of Needs includes control, inclusion, and affection needs.", "B": "Maslcmfs basic need is safety need.", "C": "Moslovis Hierarchy of Needs ranks critical needs in the following order: physiological, safety, belongingness, esteem, and self-actualization", "D": "Maslcm's basic need is physiological need."}, "correct": ["A"], "vi_explanation": "A. \"Tháp Maslow gồm nhu cầu kiểm soát, hòa nhập và yêu thương\" là SAI.\nBa nhu cầu kiểm soát, hòa nhập, yêu thương thuộc thuyết FIRO của Schutz, còn Maslow gồm 5 tầng: Sinh lý, An toàn, Thuộc về, Tôn trọng, Tự thể hiện.", "has_visual": false}, {"id": "SSG104_269", "index": 269, "question": "In order to \"Define the problem\", which actions should we take?", "options": {"A": "Identify the problem, Identify facts, Provide examples, Organize the information logically.", "B": "Identify the problem, Identify your most important goals.", "C": "Identify the problem, Provide as many supporting details as possible, Provide examples, Organize the information logically.", "D": "Identify the problem, Provide as many supporting details as possible, Identify your most important goals, Gather information and facts."}, "correct": ["C"], "vi_explanation": "C. Nhận diện vấn đề, cung cấp chi tiết hỗ trợ, nêu ví dụ và sắp xếp thông tin logic.\nĐây là 4 hành động cụ thể nằm trong bước \"Define the problem\" (theo ảnh giáo trình đi kèm).", "has_visual": true, "image_local": "images/SSG104_269.png", "images": ["https://o.quizlet.com/IXpdbESOL5fMrf7GDKZKPw_m.png"]}, {"id": "SSG104_275", "index": 275, "question": "The \"Applying\" skill of Bloom's Taxonomy is:", "options": {"A": "Ability to recognize or recall gained knowledge.", "B": "Ability to use learned material (or implement the material) in new and concrete situations.", "C": "Ability to judge, check, and even critique the value of material for a given purpose.", "D": "Ability to grasp or construct meaning from oral, written, and graphic messages."}, "correct": ["B"], "vi_explanation": "B. Khả năng sử dụng/áp dụng kiến thức đã học vào tình huống mới và cụ thể.\nĐúng định nghĩa bậc Applying trong thang Bloom.", "has_visual": false}, {"id": "SSG104_276", "index": 276, "question": "Which questions do we tend to ask in the process of creative thinking? (choose 3 options)", "options": {"A": "Can I combine perspectives/solutions?", "B": "What else is out there?", "C": "Why not?", "D": "What is good about...?"}, "correct": ["A", "B", "C"], "vi_explanation": "A, B, C. Tự hỏi \"Có thể kết hợp các góc nhìn không?\", \"Còn cách nào khác ngoài kia không?\" và \"Tại sao không?\".\nĐây là những câu hỏi mở kích thích tư duy sáng tạo vượt khuôn mẫu.", "has_visual": false}, {"id": "SSG104_284", "index": 284, "question": "Regarding problem-solving action checklist, which of the following should be conducted in \"...bị che rồi ..solutions\" stage?", "options": {"A": "Compare and contrast possible solutions", "B": "Provide as many supporting details as possible", "C": "Organize the information logically", "D": "Defend your solution"}, "correct": ["A"], "vi_explanation": "A. So sánh và đối chiếu các giải pháp khả thi (Compare and contrast possible solutions).\nDù tiêu đề bị che chữ, phần nội dung mô tả đúng bước \"Identify available solutions\".", "has_visual": false}, {"id": "SSG104_286", "index": 286, "question": "What are the characteristics of Critical thinking?", "options": {"A": "Examining assumptions.", "B": "Challenging reasoning.", "C": "Uncovering biases.", "D": "All of these are correct."}, "correct": ["D"], "vi_explanation": "D. Tất cả các ý trên đều đúng.\nTư duy phản biện đòi hỏi kiểm tra giả định, chất vấn lập luận và nhận diện thiên kiến.", "has_visual": false}, {"id": "SSG104_288", "index": 288, "question": "Which is NOT a characteristic of Critical thinking?", "options": {"A": "Skepticism.", "B": "Group thinking.", "C": "Examining assumptions.", "D": "Uncovering biases."}, "correct": ["B"], "vi_explanation": "B. Tư duy bầy đàn/nhóm (Group thinking).\nCritical thinking đề cao hoài nghi độc lập chứ không a dua theo đám đông.", "has_visual": false}, {"id": "SSG104_292", "index": 292, "question": "College is a great ground for enhancing creative thinking skills as in the below examples, EXCEPT", "options": {"A": "Design sample exam questions to test your knowledge as you study for a final", "B": "Devise a social media strategy for a club on campus", "C": "Create plan for better communication with your colleagues", "D": "Propose an education plan for a major you are designing for yourself"}, "correct": ["C"], "vi_explanation": "C. \"Lập kế hoạch giao tiếp tốt hơn với đồng nghiệp\" không phải ví dụ đặc thù của môi trường đại học như A, B, D.\nA, B, D đều là bối cảnh sinh viên ôn thi, hoạt động CLB hoặc thiết kế ngành học ở trường.", "has_visual": false}, {"id": "SSG104_294", "index": 294, "question": "What is the meaning of the word \"Logic\" in the Ancient Greek loglike?", "options": {"A": "A process of questioning information and data", "B": "It means asking probing questions", "C": "The science or art of reasoning", "D": "It refers to using knowledge, facts, and data to solve problems"}, "correct": ["C"], "vi_explanation": "C. Khoa học hoặc nghệ thuật lập luận (The science or art of reasoning).\n\"Logic\" bắt nguồn từ tiếng Hy Lạp cổ \"logike\" chỉ nghệ thuật tư duy và suy luận chặt chẽ.", "has_visual": false}, {"id": "SSG104_306", "index": 306, "question": "Strategies to stimulate your creative thinking include:", "options": {"A": "Sleep on it.", "B": "Put yourself in nerve-racking situations once in a while to fire up your brain.", "C": "Keep a notebook with you so you always have a way to record fleeting thoughts.", "D": "All of these are correct."}, "correct": ["D"], "vi_explanation": "D. Tất cả các chiến lược trên đều đúng.\nNgủ một giấc cho não xử lý ngầm, đặt mình vào áp lực vừa phải và mang sổ tay ghi nhanh ý tưởng đều kích thích sáng tạo.", "has_visual": false}, {"id": "SSG104_309", "index": 309, "question": "Creative thinking is", "options": {"A": "a way of employing strategies to clear your mind so that your thoughts and ideas can transcend what appear to be the limitations of a problem", "B": "important because it helps you look at problems and situations from a fresh perspective", "C": "a way to develop novel or unorthodox solutions that do not depend wholly on past or current solutions", "D": "All of these are correct"}, "correct": ["D"], "vi_explanation": "D. Tất cả các định nghĩa trên đều đúng.\nTư duy sáng tạo giúp vượt qua lối mòn, nhìn vấn đề từ góc mới và tạo giải pháp độc đáo.", "has_visual": false}, {"id": "SSG104_311", "index": 311, "question": "What is the similarity of Critical thinking and Problem-solving? (Soạn bởi Thủy Tiên)", "options": {"A": "They both focus on identifying, selecting, defending solution.", "B": "They both refer to using knowledge, facts, and data to solve problems effectively.", "C": "They are efficient and rewarding process.", "D": "They are fundamentally process of questioning information and data."}, "correct": ["B"], "vi_explanation": "B. Cả hai đều dựa trên việc sử dụng kiến thức, sự kiện và dữ liệu để giải quyết vấn đề hiệu quả.\nTư duy phản biện làm nền tảng phân tích cho quá trình giải quyết vấn đề.", "has_visual": false}, {"id": "SSG104_319", "index": 319, "question": "All of the followings are the ways to use critical thinking to evaluate information, EXCEPT", "options": {"A": "Being receptive to having your opinions changed.", "B": "Having an inquiring mind.", "C": "Accepting something without asking for evidence.", "D": "Questioning your own conclusions."}, "correct": ["C"], "vi_explanation": "C. \"Chấp nhận thông tin mà không cần hỏi bằng chứng\" là NGOẠI LỆ.\nTư duy phản biện luôn đòi hỏi kiểm chứng chứng cứ trước khi tin.", "has_visual": false}, {"id": "SSG104_321", "index": 321, "question": "Which of the following statements is NOT correct?", "options": {"A": "The word \"Logic\" comes from the Ancient Greek logike.", "B": "\"Logic\" refers to the science or art of reasoning.", "C": "\"Logic\" allows a person to evaluate arguments and reasoning.", "D": "\"Logic\" cannot help to distinguish between good and bad reasoning."}, "correct": ["D"], "vi_explanation": "D. \"Logic không giúp phân biệt lập luận đúng và sai\" là phát biểu KHÔNG ĐÚNG.\nChính logic là công cụ cốt lõi giúp đánh giá tính hợp lý và phân biệt suy luận đúng sai.", "has_visual": false}, {"id": "SSG104_322", "index": 322, "question": "What do we do when we use logic? (choose 2 options)", "options": {"A": "We evaluate the strength of arguments.", "B": "We distinguish between true and false information.", "C": "We collect as much data as possible.", "D": "We examine the underlying reasons."}, "correct": ["A", "B"], "vi_explanation": "A, B. Đánh giá sức mạnh lập luận và phân biệt thông tin đúng – sai.\nĐây là hai chức năng trọng tâm khi vận dụng tư duy logic.", "has_visual": false}, {"id": "SSG104_337", "index": 337, "question": "You are given a task to design a poster for an upcoming event at your university. You decide garden for inspiration. Which tip of creative thinking do you seem to use in this case?", "options": {"A": "Sensing.", "B": "Imagining.", "C": "Moving.", "D": "Learning."}, "correct": ["A"], "vi_explanation": "A. Sensing (Quan sát thực tế).\nTìm kiếm cảm hứng trực tiếp từ thiên nhiên/vườn thực vật bằng giác quan là áp dụng mẹo Sensing.", "has_visual": false}, {"id": "SSG104_338", "index": 338, "question": "Which is a fact about Creative Thinking?", "options": {"A": "Every problem has only one solution or one right answer", "B": "Ideas either come or they don't. Nothing will help -certainly not structure", "C": "The best answer or solution or method has already been discovered", "D": "Only few problems require complex technological solutions"}, "correct": ["D"], "vi_explanation": "D. Chỉ một số ít vấn đề mới cần đến giải pháp công nghệ phức tạp.\nĐây là sự thật (Fact), còn A, B, C đều là các lầm tưởng sai lầm (Fiction) về tư duy sáng tạo.", "has_visual": false}, {"id": "SSG104_340", "index": 340, "question": "Which is the lowest learning-skill level of Bloom's Taxonomy?", "options": {"A": "Remember.", "B": "Understand.", "C": "Analyze.", "D": "Apply."}, "correct": ["A"], "vi_explanation": "A. Ghi nhớ (Remember).\nĐây là tầng nền tảng thấp nhất trong tháp nhận thức 6 cấp độ của Bloom.", "has_visual": false}]}, {"id": "writing", "title": "Viết chuyên nghiệp, Báo cáo, Proposal & Đạo văn", "tag": "Viết & Proposal", "questions": [{"id": "SSG104_004", "index": 4, "question": "Why is audience analysis important for persuasive speech?", "options": {"A": "It helps to tailor the speech to entertain the audience.", "B": "It allows the speaker to understand the range of opinions and beliefs.", "C": "It ensures that the audience will agree with the speaker's view.", "D": "It is not important to analyse the audience; the speaker should focus on the content only."}, "correct": ["B"], "vi_explanation": "B. Giúp người nói hiểu rõ phổ quan điểm và niềm tin của khán giả.\nPhân tích người nghe giúp điều chỉnh lập luận thuyết phục chạm đúng mối quan tâm của họ.", "has_visual": false}, {"id": "SSG104_005", "index": 5, "question": "Which of the following is the best example of constructive feedbacks?", "options": {"A": "Your proposal is disorganized, contains computational errors, and is a writing disaster.", "B": "You aren't paying attention to the customer when you are having a conversation with someone else at the same time.", "C": "Why can't you stay focus? It is only 10 o'clock in the morning.", "D": "All the elements of a good proposal are here; they just need to be reordered. By placing the strongest element first, we can capture and hold the reader's attention."}, "correct": ["D"], "vi_explanation": "D. Ghi nhận yếu tố tốt trước rồi góp ý cách sắp xếp lại để đạt hiệu quả cao hơn.\nPhản hồi mang tính xây dựng tập trung vào cải thiện bài làm và giữ tinh thần tích cực, tránh công kích cá nhân.", "has_visual": false}, {"id": "SSG104_017", "index": 17, "question": "At what point in a business meeting should group members approve the agenda and minutes?", "options": {"A": "right after the call to order", "B": "right after routine reports are shared", "C": "before the discussion of new business", "D": "right before final announcements by members"}, "correct": ["A"], "vi_explanation": "A. Ngay sau phần khai mạc cuộc họp (call to order).\nThông qua chương trình họp (agenda) và biên bản kỳ trước giúp cả nhóm thống nhất nội dung trước khi vào báo cáo hay thảo luận mới.", "has_visual": false}, {"id": "SSG104_021", "index": 21, "question": "You may maintain less eye contact with audiences who are...", "options": {"A": "new to your team", "B": "very interested in your presentation", "C": "want to ask questions", "D": "not showing interest in your presentation"}, "correct": ["D"], "vi_explanation": "D. Những khán giả không tỏ ra hứng thú với bài thuyết trình.\nVẫn cần quét mắt khắp phòng nhưng nên hạn chế dồn ánh nhìn vào người mất tập trung để giữ nhịp năng lượng tích cực.", "has_visual": false}, {"id": "SSG104_031", "index": 31, "question": "Which of the following reasons is sound justification for scheduling or attending a group meeting?", "options": {"A": "You hate to write reports and memos", "B": "You prefer not to do the research yourself", "C": "You feel lost without colleagues", "D": "Group input and interaction are critical"}, "correct": ["D"], "vi_explanation": "D. Khi ý kiến đóng góp và tương tác tập thể là yếu tố then chốt.\nChỉ nên họp khi thực sự cần bàn bạc chung để ra quyết định chứ không phải vì lười làm việc độc lập.", "has_visual": false}, {"id": "SSG104_038", "index": 38, "question": "Who is the meeting contributor?", "options": {"A": "Sleeper", "B": "Whisperer", "C": "Latecomer", "D": "Reporter"}, "correct": ["D"], "vi_explanation": "D. Người báo cáo/đóng góp nội dung (Reporter).\nSleeper, Whisperer, Latecomer đều là các kiểu hành vi gây gián đoạn cuộc họp.", "has_visual": false}, {"id": "SSG104_039", "index": 39, "question": "What is the difference between Hierarchical structure and Matrix team?", "options": {"A": "While the Matrix team provides a stable backbone to the organization, the Hierarchical structure does not.", "B": "Matrix teams are more common in small and medium-size organizations, while Hierarchical structure is typical for large and multi-national organizations.", "C": "Hierarchical structure provides more flexible management for an organization than Matrix team.", "D": "In Hierarchical structure, the reporting direction is mainly one-way (staff report to a single supervisor), while in the Matrix team, the reporting direction is more diverse (staff report to different managers for different aspects of their work)."}, "correct": ["D"], "vi_explanation": "D. Cấu trúc phân cấp báo cáo một chiều lên 1 cấp trên; nhóm ma trận báo cáo đa chiều cho nhiều quản lý khác nhau.\nMatrix team kết hợp quản lý theo chức năng và theo dự án nên một nhân sự có thể có nhiều đầu mối báo cáo.", "has_visual": false}, {"id": "SSG104_043", "index": 43, "question": "The checklist for ensuring that a report fulfills its goals include: (Choose 3 answers)", "options": {"A": "Information is accurate, complete, and documented", "B": "Figures, tables, and art are clear and correctly labeled", "C": "A report presents as much progress as possible, event if not all the goals were achieved.", "D": "A report represents your best effort"}, "correct": ["A", "B", "D"], "vi_explanation": "A, B, D. Dữ liệu chính xác có trích dẫn, hình bảng rõ ràng có nhãn, và thể hiện nỗ lực tốt nhất.\nChọn lọc thông tin đúng trọng tâm và trung thực, không phải nhồi nhét càng nhiều càng tốt (C).", "has_visual": false}, {"id": "SSG104_044", "index": 44, "question": "The purpose of a business proposal is to ....", "options": {"A": "raise a problem", "B": "reflect on work", "C": "narrate what you have done", "D": "make a persuasive appeal"}, "correct": ["D"], "vi_explanation": "D. Đưa ra lời đề nghị mang tính thuyết phục (make a persuasive appeal).\nMục đích chính của bản đề xuất kinh doanh (Business proposal) là thuyết phục đối tác/khách hàng chấp thuận giải pháp của mình.", "has_visual": false}, {"id": "SSG104_082", "index": 82, "question": "Which element is NOT a part of a report?", "options": {"A": "Conclusion", "B": "Body", "C": "Minutes", "D": "Cover"}, "correct": ["C"], "vi_explanation": "C. Biên bản cuộc họp (Minutes).\nBáo cáo (Report) gồm trang bìa, thân bài, kết luận... chứ không bao gồm biên bản họp.", "has_visual": false}, {"id": "SSG104_088", "index": 88, "question": "The most important section of a proposal is the", "options": {"A": "cost.", "B": "solution.", "C": "purpose statement", "D": "backgrOund."}, "correct": ["B"], "vi_explanation": "B. Phần giải pháp (solution).\nTrong proposal, khách hàng quan tâm nhất là bạn giải quyết vấn đề của họ bằng cách nào. (Lưu ý thêm: nếu hỏi phần quan trọng nhất của thư xin việc thì là tóm tắt năng lực.)", "has_visual": false}, {"id": "SSG104_090", "index": 90, "question": "Which of the following statement is NOT the goal of using visual aids?", "options": {"A": "Show your audience that you can describe ideas in various ways", "B": "Make your speech more interesting", "C": "Enhance your credibility as a speaker", "D": "Communicate complex or intriguing information in a short period of time"}, "correct": ["A"], "vi_explanation": "A. \"Khoe với khán giả rằng bạn có thể diễn đạt ý theo nhiều cách\" không phải mục tiêu của công cụ trực quan.\nVisual aids nhằm tăng hứng thú, tăng uy tín và truyền tải thông tin phức tạp nhanh hơn.", "has_visual": false}, {"id": "SSG104_091", "index": 91, "question": "The written record of a group's discussion and activities is _", "options": {"A": "a meeting minute", "B": "a report", "C": "an agenda", "D": "a note"}, "correct": ["A"], "vi_explanation": "A. Biên bản cuộc họp (a meeting minute).\nLà bản ghi chép chính thức về nội dung thảo luận, quyết định và hành động của nhóm trong buổi họp.", "has_visual": false}, {"id": "SSG104_101", "index": 101, "question": "What is an elevator speech?", "options": {"A": "The expression of or the ability to express thoughts and feelings by articulate sounds.", "B": "the presentation with irrelevant data and the rehearsal of the speech.", "C": "an act or process of presenting a claim to move, motivate, or change your life.", "D": "a presentation that persuades the listener in less than thirty seconds, or around a hundred words."}, "correct": ["D"], "vi_explanation": "D. Bài trình bày thuyết phục người nghe trong dưới 30 giây hoặc khoảng 100 từ.\nElevator speech được thiết kế ngắn gọn như một chuyến đi thang máy để truyền đạt thông điệp cốt lõi ngay lập tức.", "has_visual": false}, {"id": "SSG104_113", "index": 113, "question": "Which of the following should be discussed in the Market Analysis section in a business proposal?", "options": {"A": "How will the potential buyer benefit from your product or service?", "B": "What currently exists in the marketplace and how does your solution com pare?", "C": "What will potential buyer learn about you?", "D": "How will the relationship between your company and the potential buyer be discussed?"}, "correct": ["B"], "vi_explanation": "B. Thị trường hiện có gì và giải pháp của bạn so với đối thủ ra sao.\nMục Phân tích thị trường (Market Analysis) làm rõ bối cảnh cạnh tranh và lợi thế khác biệt của giải pháp đề xuất.", "has_visual": false}, {"id": "SSG104_114", "index": 114, "question": "Who do staffs report to in a matrix team?", "options": {"A": "General manager", "B": "Single manager", "C": "Different managers", "D": "CEO of the organizatio"}, "correct": ["C"], "vi_explanation": "C. Nhiều quản lý khác nhau (Different managers).\nTrong mô hình nhóm ma trận, nhân viên thường báo cáo song song cho cả quản lý bộ phận chuyên môn và trưởng dự án.", "has_visual": false}, {"id": "SSG104_122", "index": 122, "question": "What is the requirement of thinking at the level of college? (choose 2 options)", "options": {"A": "You need to apply understanding learnt during lectures correctly to solve problems in given situations.", "B": "It is important to recognize or recall knowledge you've already gained.", "C": "You need to relate abstract ideas to practical situations.", "D": "You need the ability to break down or distinguish the parts of material into its components, so that its organizational structure may be better understood."}, "correct": ["A", "D"], "vi_explanation": "A, D. Bậc đại học đòi hỏi biết vận dụng kiến thức đã học để giải quyết vấn đề thực tế (Applying) và biết phân tích cấu trúc vấn đề thành các phần (Analyzing).\nChỉ nhớ thuộc lòng (B) thuộc bậc nhận thức thấp hơn.", "has_visual": false}, {"id": "SSG104_126", "index": 126, "question": "What is abstract in a report? (Thủy Tiên)", "options": {"A": "Title fly", "B": "Key words to introduce the research topic", "C": "Introduction part", "D": "Include aims and outcome of the research"}, "correct": ["D"], "vi_explanation": "D. Tóm tắt mục tiêu và kết quả của nghiên cứu (Include aims and outcome).\nAbstract là bản cô đọng toàn bộ báo cáo gồm mục đích, phương pháp và kết quả chính.", "has_visual": false}, {"id": "SSG104_132", "index": 132, "question": "Researchers have identified two key ingredients to effective teamwork as the following (check 2 options)", "options": {"A": "competition amang group members.", "B": "the ability of group members.", "C": "group unity.", "D": "a shared mental representation of the task."}, "correct": ["C", "D"], "vi_explanation": "C, D. Sự đoàn kết của nhóm (group unity) và mô hình nhận thức chung về nhiệm vụ (shared mental representation).\nCạnh tranh nội bộ (A) hay chỉ có năng lực cá nhân rời rạc chưa đủ tạo nên làm việc nhóm hiệu quả.", "has_visual": false}, {"id": "SSG104_143", "index": 143, "question": "David has just been given the task of delivering an oral presentation to the marketing department of the organization he joined two months ago. The first thing David should do is...", "options": {"A": "analyze the audience", "B": "determine the purpose of the presentation", "C": "draft an outline", "D": "gather supporting data"}, "correct": ["B"], "vi_explanation": "B. Xác định rõ mục đích của bài thuyết trình.\nBiết mình nói để làm gì (thông báo, thuyết phục hay hướng dẫn) là bước đầu tiên trước khi phân tích khán giả và lập dàn ý.", "has_visual": false}, {"id": "SSG104_149", "index": 149, "question": "A team is called contract team if", "options": {"A": "Team members have other duties to perform in their normal functional units.", "B": "Team retains their responsibility for both their daily work and project work.", "C": "Team members report to different managers.", "D": "Team is brought in from outside in order to do project work."}, "correct": ["D"], "vi_explanation": "D. Nhóm được thuê từ bên ngoài vào để thực hiện công việc dự án.\nĐó là định nghĩa chuẩn của Contract team.", "has_visual": false}, {"id": "SSG104_153", "index": 153, "question": "Specific revision requires attention to the following: format, facts, names, spelling, punctuation, and", "options": {"A": "Content.", "B": "Grammar.", "C": "Organization.", "D": "Style."}, "correct": ["B"], "vi_explanation": "B. Ngữ pháp (Grammar).\nKhâu hiệu đính chi tiết (Specific revision) rà soát từng lỗi kỹ thuật gồm định dạng, số liệu, tên riêng, chính tả, dấu câu và ngữ pháp.", "has_visual": false}, {"id": "SSG104_165", "index": 165, "question": "What is included in the body of the report?", "options": {"A": "Label, report, features title, author.", "B": "Background, Methodology, Results, Analysis and Recommendations.", "C": "List of citations, A list of the main sections, image.", "D": "Highlight topic, methods, data, and results."}, "correct": ["B"], "vi_explanation": "B. Bối cảnh (Background), Phương pháp, Kết quả, Phân tích và Khuyến nghị.\nĐây là các phần nội dung chính nằm trong phần Thân (Body) của một báo cáo.", "has_visual": false}, {"id": "SSG104_168", "index": 168, "question": "Which of the following best describes the term \"readability\"?", "options": {"A": "It is only one aspect of your document.", "B": "It includes an introduction, body, and conclusion as part of your document..", "C": "It refers to the reader's ability to read and comprehend the document.", "D": "It involves word choice and grammatical structures."}, "correct": ["C"], "vi_explanation": "C. Khả năng người đọc có thể đọc và hiểu nội dung tài liệu một cách trôi chảy.\nReadability phản ánh mức độ dễ đọc, dễ tiếp thu của văn bản đối với độc giả.", "has_visual": false}, {"id": "SSG104_179", "index": 179, "question": "The solution to a research problem is presented in the report as a part of the", "options": {"A": "appendix", "B": "conclusion", "C": "recommendation", "D": "findings"}, "correct": ["C"], "vi_explanation": "C. Phần Khuyến nghị (recommendation).\nKết luận tổng hợp phát hiện nghiên cứu, còn giải pháp đề xuất cụ thể cho vấn đề được trình bày ở phần Recommendation.", "has_visual": false}, {"id": "SSG104_188", "index": 188, "question": "Michelle is new staff of Marketing department in FPT Software company. Her manager told her to prepare a report to review activity of the department in the last 3 months.\nWhich type of report is that?", "options": {"A": "Progress.", "B": "Financial.", "C": "Feasibility.", "D": "Needs assessment."}, "correct": ["A"], "vi_explanation": "A. Báo cáo tiến độ (Progress report).\nTổng hợp hoạt động của phòng ban trong 3 tháng gần nhất để sếp nắm tình hình chính là Progress report.", "has_visual": false}, {"id": "SSG104_212", "index": 212, "question": "What is TRUE about solicited proposal?", "options": {"A": "They are the \"cold calls\" of business writing.", "B": "They are typically general rather than customer-specific.", "C": "They are only in the form of a direct verbal.", "D": "They are normally indirect, open-bid to the public, and formally published for everyone to see."}, "correct": ["D"], "vi_explanation": "D. Thường là đề xuất gián tiếp, đấu thầu mở công khai theo hồ sơ mời thầu chính thức.\nKhác với unsolicited proposal (tự chào mời kiểu \"cold call\"), solicited proposal đáp lại lời mời công khai từ bên mua.", "has_visual": false}, {"id": "SSG104_225", "index": 225, "question": "What are the four main categories that will provide a template for general revision?", "options": {"A": "Format, Facts, Names, Spelling", "B": "Format, Organization, Punctuation, Grammar", "C": "Content, Format, Grammar, Readabnity", "D": "Content, Organization, Style, and Readability"}, "correct": ["D"], "vi_explanation": "D. Nội dung (Content), Bố cục (Organization), Văn phong (Style) và Khả năng đọc hiểu (Readability).\nĐây là 4 hạng mục lớn ở bước rà soát tổng thể (General revision), còn chính tả/dấu câu nằm ở rà soát chi tiết.", "has_visual": false}, {"id": "SSG104_243", "index": 243, "question": "You start planning a proposal by", "options": {"A": "determining the factors.", "B": "determining the solutions.", "C": "scheduling the study.", "D": "stating the problem."}, "correct": ["D"], "vi_explanation": "D. Nêu rõ vấn đề (stating the problem).\nMọi bản đề xuất (proposal) đều phải bắt đầu từ việc xác định vấn đề cần giải quyết thì mới đề xuất giải pháp thuyết phục.", "has_visual": false}, {"id": "SSG104_247", "index": 247, "question": "What are included in a report abstract?", "options": {"A": "Highlight topic, methods, data, and results", "B": "A list of the main parts of the report", "C": "Label, report, features title, author", "D": "Methodology"}, "correct": ["A"], "vi_explanation": "A. Nêu bật chủ đề, phương pháp, dữ liệu và kết quả chính.\nAbstract tóm lược những gì người đọc cần biết nhanh về toàn bộ báo cáo.", "has_visual": false}, {"id": "SSG104_252", "index": 252, "question": "What type of report is used to provide project status updates to management?", "options": {"A": "Progress Report", "B": "Recommendation Report", "C": "Summary Report", "D": "Financial Report"}, "correct": ["A"], "vi_explanation": "A. Báo cáo tiến độ (Progress Report).\nCập nhật tình hình thực hiện dự án theo định kỳ cho cấp quản lý là chức năng của Progress report.", "has_visual": false}, {"id": "SSG104_280", "index": 280, "question": "To produce a good opening in a persuasive message, you should keep it", "options": {"A": "Neutral.", "B": "Negative and impersonal.", "C": "Impersonal.", "D": "Positive and personal."}, "correct": ["D"], "vi_explanation": "D. Tích cực và mang tính cá nhân hóa (Positive and personal).\nLời mở đầu thân thiện, tích cực giúp tạo thiện cảm ngay lập tức cho thông điệp thuyết phục.", "has_visual": false}, {"id": "SSG104_287", "index": 287, "question": "Which of the following is NOT a component of a business proposal?", "options": {"A": "Company description", "B": "Background", "C": "Market analysis", "D": "Timeline"}, "correct": ["A"], "vi_explanation": "A. Mô tả công ty (Company description) không nằm trong danh sách các phần cốt lõi của business proposal trong slide bài học.\nCác phần chuẩn gồm Background, Market analysis, Timeline, Solution... (Theo ghi chú giảng viên đã xác nhận A.)", "has_visual": true, "image_local": "images/SSG104_287.jpg", "images": ["https://o.quizlet.com/Xng0MgS71JvXQPrsUGJyqA_m.jpg"]}, {"id": "SSG104_300", "index": 300, "question": "Susan is a new staff of IT team 3 in FPT Software company. Her senior told her to prepare a report to instruct their Japanese customer how the new app works. Which type of report is that?", "options": {"A": "Technical", "B": "Financial", "C": "Feasibility", "D": "Needs assessment"}, "correct": ["A"], "vi_explanation": "A. Báo cáo kỹ thuật (Technical report).\nTài liệu hướng dẫn khách hàng cách vận hành ứng dụng phần mềm mới thuộc loại báo cáo/tài liệu kỹ thuật.", "has_visual": false}, {"id": "SSG104_307", "index": 307, "question": "Which of the following best describes the term \"readability\"?", "options": {"A": "It is only one aspect of your document.", "B": "It includes an introduction, body, and conclusion as part of your document.", "C": "It refers to the reader's ability to read and comprehend the document.", "D": "It involves word choice and grammatical structures."}, "correct": ["C"], "vi_explanation": "C. Đề cập đến khả năng người đọc có thể đọc và hiểu rõ văn bản.\nReadability đánh giá mức độ mạch lạc và dễ tiếp thu đối với độc giả.", "has_visual": false}, {"id": "SSG104_308", "index": 308, "question": "When preparing report content, you should ask all of the questions below EXCEPT", "options": {"A": "Whom the report is about and/or prepared for?", "B": "What was done, what problems were addressed, and the results, including conclusions and/or recommendations?", "C": "Where the subject studied occurred?", "D": "How much do your manager pay you to write the report?"}, "correct": ["D"], "vi_explanation": "D. \"Sếp trả cho bạn bao nhiêu tiền để viết báo cáo\" không liên quan đến nội dung báo cáo.\nKhi chuẩn bị nội dung báo cáo cần trả lời câu hỏi cho ai, làm gì, kết quả nào và ở đâu.", "has_visual": false}, {"id": "SSG104_312", "index": 312, "question": "Laura has an important meeting tomorrow to present her solution to the city People Committ improving students' life. Which of the following is good advice for her to prepare herself for th", "options": {"A": "Use emotional appeals.", "B": "Simplify the students' problems to make the solution look easy.", "C": "Hide numbers and facts if the committee do not ask.", "D": "Prepare the presentation with relevant data and rehearsal the speech carefully."}, "correct": ["D"], "vi_explanation": "D. Chuẩn bị bài thuyết trình với dữ liệu xác thực và tập dượt kỹ lưỡng.\nTrình bày trước hội đồng cần số liệu thuyết phục và sự chuẩn bị nghiêm túc thay vì cảm tính hay giấu số liệu.", "has_visual": false}, {"id": "SSG104_325", "index": 325, "question": "What kind of information should we discuss in the Background section of a business proposal ?", "options": {"A": "Current exists in the marketplace, including competing products or services.", "B": "The ideas of your project.", "C": "The history of your product, service , and/or company and the relationship between you buyer and/or similar companies.", "D": "The design of your documents."}, "correct": ["C"], "vi_explanation": "C. Lịch sử sản phẩm/dịch vụ/công ty và mối quan hệ trước đây với khách hàng.\nMục Background đặt nền móng ngữ cảnh cho bản đề xuất trước khi bàn đến thị trường (Market analysis) và giải pháp.", "has_visual": false}]}, {"id": "leadership", "title": "Lãnh đạo & Quyền lực", "tag": "Lãnh đạo & Quyền lực", "questions": [{"id": "SSG104_003", "index": 3, "question": "How does a leader effectively demonstrate inspirational influence within a team?", "options": {"A": "By strictly enforcing rules and regulations.", "B": "By using social or interpersonal influence.", "C": "By micromanaging team members to ensure task completion.", "D": "By relying solely on positional authority to make decisions."}, "correct": ["B"], "vi_explanation": "B. Sử dụng sức ảnh hưởng xã hội và kỹ năng giao tiếp giữa các cá nhân.\nẢnh hưởng truyền cảm hứng (inspirational influence) dựa vào sự kết nối và khích lệ chứ không ép buộc bằng quyền lực chức vụ hay vi quản lý.", "has_visual": false}, {"id": "SSG104_008", "index": 8, "question": "Power-over can be seen in which of the following situations?", "options": {"A": "A leader empowering a group through cooperation", "B": "A member dominating the conversation and controlling the group's resources", "C": "A group respecting each other's opinions and working collaboratively", "D": "A leader suggests ideas without imposing them on others"}, "correct": ["B"], "vi_explanation": "B. Một thành viên độc chiếm cuộc trò chuyện và kiểm soát tài nguyên của nhóm.\nPower-over là dạng quyền lực áp đặt, chi phối và kiểm soát người khác.", "has_visual": false}, {"id": "SSG104_015", "index": 15, "question": "You are a volunteer to organize a charity book sale. The leader is proactive but shows very little effectiveness and lets people talk for too long without saying anything. You lose the patience, so you decide to gently remind the leader to stay on track and move on. At first the leader didn't like you doing this, but now it's okay. What stage of Tuckman's Group Development Stages is the group in now?", "options": {"A": "Forming", "B": "Storming", "C": "Norming", "D": "Performing"}, "correct": ["C"], "vi_explanation": "C. Norming (Giai đoạn ổn định quy chuẩn).\nBan đầu trưởng nhóm khó chịu (Storming) nhưng nay đã chấp nhận góp ý để giữ đúng hướng — dấu hiệu nhóm bước vào giai đoạn thiết lập nề nếp chung (Norming).", "has_visual": false}, {"id": "SSG104_018", "index": 18, "question": "David's group is capable of achieving more than individuals acting alone. In addition, some jobs require multiple people to perform at the same time. Therefore, group members need to pool their talents, consciousness or strength to complete the task- Read the above scenario: what is best answer related to it?", "options": {"A": "Security", "B": "Self—esteem", "C": "Goal achievement", "D": "Power and control"}, "correct": ["C"], "vi_explanation": "C. Đạt được mục tiêu chung (Goal achievement).\nTình huống nhấn mạnh nhóm cần gom tài năng và sức lực để hoàn thành những công việc một cá nhân không tự làm nổi.", "has_visual": false}, {"id": "SSG104_019", "index": 19, "question": "A supervisor threatens to dismiss any member of the sales team who does not meet the sales quota by the end of the quarter. What type of power is this leader using?", "options": {"A": "Referent power.", "B": "Legitimate power.", "C": "Expert power.", "D": "Coercive power."}, "correct": ["D"], "vi_explanation": "D. Quyền lực cưỡng chế (Coercive power).\nDùng lời đe dọa sa thải nếu không đạt KPI là áp lực dựa trên hình phạt.", "has_visual": false}, {"id": "SSG104_024", "index": 24, "question": "Person A obtains the referent power when", "options": {"A": "A has a right to exert power in a certain domain.", "B": "A has credibility in a particular- and narrow-area as a result of experience and expertise.", "C": "others look up or admire A because of A's personal qualities, characteristics or reputation.", "D": "A has power over B because A controls rewards that B wants."}, "correct": ["C"], "vi_explanation": "C. Người khác ngưỡng mộ hoặc yêu quý A nhờ phẩm chất cá nhân và uy tín.\nĐó là bản chất của Referent power (quyền lực tham chiếu/sức hút cá nhân).", "has_visual": false}, {"id": "SSG104_026", "index": 26, "question": "Which power tactic is used in the following example?\nIn \"the Chapel Hill study\" on the 1968 presidential election, McCombs and Shaw demonstrated a strong correlation between one hundred Chapel Hill residents' thought on what was the most important election issue and what the local news media reported was the most important issue.", "options": {"A": "Controlling access to information", "B": "Selective use of objective criteria", "C": "Controlling the agenda", "D": "Using outside experts"}, "correct": ["C"], "vi_explanation": "C. Kiểm soát chương trình nghị sự / chủ đề quan tâm (Controlling the agenda).\nTruyền thông quyết định đưa tin vấn đề nào sẽ định hướng điều công chúng coi là trọng tâm (Agenda setting).", "has_visual": false}, {"id": "SSG104_029", "index": 29, "question": "What is the possible response in the consequence of legitimate power?", "options": {"A": "Resistance", "B": "Compliance", "C": "Commitment", "D": "Avoidance"}, "correct": ["B"], "vi_explanation": "B. Sự tuân thủ (Compliance).\nQuyền lực chính danh từ chức vụ (Legitimate power) thường tạo ra sự phục tùng theo quy định chứ chưa chắc tạo cam kết tự nguyện sâu sắc.", "has_visual": false}, {"id": "SSG104_035", "index": 35, "question": "All of the following criteria should be considered when determining who should be invited to a meeting EXCEPT: (Soạn bởi TIÊN)", "options": {"A": "individuals who will be affected directly by the outcome", "B": "individuals with special expertise", "C": "individuals who disagree or represent minority viewpoints", "D": "individuals who have the power to implement decisions", "E": "individuals who are uninvolved in the issues scheduled for discussion"}, "correct": ["E"], "vi_explanation": "E. Những người không liên quan gì đến vấn đề sắp bàn.\nMời người ngoài cuộc chỉ làm cuộc họp loãng và tốn thời gian.", "has_visual": false}, {"id": "SSG104_053", "index": 53, "question": "The person in charge of conducting a meeting is the..........", "options": {"A": "group leader", "B": "dominator", "C": "chairperson", "D": "recorder"}, "correct": ["C"], "vi_explanation": "C. Chủ tọa cuộc họp (chairperson).\nChairperson là người điều phối, dẫn dắt chương trình và giữ trật tự trong suốt cuộc họp.", "has_visual": false}, {"id": "SSG104_073", "index": 73, "question": "Regarding professional element, which format for electronic documents is mostly suggested using to preserve content location and avoid any inadvertent changes when it is displayed?", "options": {"A": "Excel", "B": "Word", "C": "Power Point", "D": "PDF"}, "correct": ["D"], "vi_explanation": "D. Định dạng PDF.\nPDF khóa cố định bố cục, font chữ và vị trí nội dung khi mở trên bất kỳ thiết bị nào.", "has_visual": false}, {"id": "SSG104_099", "index": 99, "question": "What is NOT TRUE about social comparison?", "options": {"A": "Social comparison is a natural psychological tendency and one that can exert a powerful influence on the way we feel and behave.", "B": "Social comparison is not an ugly phenomenon to be avoided.", "C": "The engine of social comparison can provide the push you need to rise to the occasion and increase your motivation, and therefore make progress toward your goals.", "D": "Social comparison and its effects on self-evaluation will not depend on personality and individual differences."}, "correct": ["D"], "vi_explanation": "D. \"So sánh xã hội không phụ thuộc vào tính cách và khác biệt cá nhân\" là SAI.\nMỗi người có mức độ nhạy cảm và phản ứng khác nhau trước việc so sánh tùy thuộc vào tính cách của họ.", "has_visual": false}, {"id": "SSG104_111", "index": 111, "question": "Reward Power exists when:", "options": {"A": "when person A has power over person B because A controls rewards that B wants.", "B": "when person 8 submits to person A because B feels that A has a right to exert power in a certain domain", "C": "person A has power over person B because A can administer some form of punishment to B.", "D": "person A gains power because A has knowledge or expertise relevant to B."}, "correct": ["A"], "vi_explanation": "A. A có quyền lực với B vì A kiểm soát những phần thưởng mà B mong muốn.\nReward power xuất phát từ khả năng ban phát lương thưởng, thăng tiến hoặc quyền lợi.", "has_visual": false}, {"id": "SSG104_115", "index": 115, "question": "Authority is another name of:", "options": {"A": "Legitimate Power", "B": "Coercive Power", "C": "Expert Power", "D": "Reward Power"}, "correct": ["A"], "vi_explanation": "A. Quyền lực chính danh (Legitimate Power).\nAuthority là thẩm quyền gắn liền với chức vụ chính thức trong tổ chức.", "has_visual": false}, {"id": "SSG104_116", "index": 116, "question": "Which of the following is NOT the reason for leaders to enable a broader social-connectedness between employees in the workplace?", "options": {"A": "People with friends at work tend to be happier and more productive.", "B": "Psychological wellbeing is at risk. as is cognitive performance. if people can't socialise at work", "C": "People with broad organisational knowledge that people like collaborating with seem to add the most value", "D": "The act of socialising with other people on a regular basis is increasingly being seen as necessary for maintaining and increasing the information highways within the brain. It helps people think better."}, "correct": ["C"], "vi_explanation": "C. Người có kiến thức tổ chức rộng dễ được thích hợp tác nhất — đây không phải lý do trực tiếp bàn về việc lãnh đạo mở rộng kết nối xã hội nơi công sở.\nCác ý A, B, D đều trực tiếp giải thích lợi ích của giao lưu xã hội đối với hạnh phúc, sức khỏe tâm lý và hiệu suất não bộ.", "has_visual": false}, {"id": "SSG104_121", "index": 121, "question": "Which is TRUE about persuasion?", "options": {"A": "Persuasion is forcing people to do as your request.", "B": "Persuasion is an act of leader giving order to followers without considering their will.", "C": "Persuasion can be implicit or explicit and only have positive effects.", "D": "Persuasion is an act or process of presenting arguments to move, motivate, or change your audience."}, "correct": ["D"], "vi_explanation": "D. Thuyết phục là quá trình trình bày lập luận để lay động, tạo động lực hoặc thay đổi người nghe.\nThuyết phục tôn trọng sự tự nguyện của đối phương chứ không phải ép buộc hay ra lệnh một chiều.", "has_visual": false}, {"id": "SSG104_125", "index": 125, "question": "Which leadership theories is effective when the characteristics and behavior of the leader match the demands of the situation", "options": {"A": "The Trait Approach to Leadership.", "B": "Behavioral Approaches to Leadership.", "C": "Transformational, Visionary, and Charismatic Leadership.", "D": "Situational (Contingency) Approaches to Leadership"}, "correct": ["D"], "vi_explanation": "D. Tiếp cận lãnh đạo theo tình huống (Situational / Contingency Approaches).\nMô hình này nhấn mạnh hiệu quả lãnh đạo phụ thuộc vào sự phù hợp giữa hành vi người dẫn dắt và hoàn cảnh cụ thể.", "has_visual": false}, {"id": "SSG104_137", "index": 137, "question": "Which type of power can be generated by controlling such resources as money, love and information?", "options": {"A": "Power-over.", "B": "Power-with.", "C": "Power-from-within.", "D": "Legitimate power."}, "correct": ["A"], "vi_explanation": "A. Power-over.\nDạng quyền lực này hình thành bằng cách nắm giữ và kiểm soát các nguồn lực thiết yếu như tiền bạc, tình cảm hay thông tin.", "has_visual": false}, {"id": "SSG104_141", "index": 141, "question": "In your group, you can freely express your thoughts and needs, and are assigned with tasks which match your personal capacities. Which type of power that you seem to experience?", "options": {"A": "Independent power.", "B": "Power-from-within.", "C": "Expert power.", "D": "Power-with."}, "correct": ["D"], "vi_explanation": "D. Power-with (quyền lực đồng hành).\nMôi trường mọi người bình đẳng, tự do góp ý và được giao việc hợp năng lực thể hiện tinh thần chia sẻ quyền lực cùng nhau.", "has_visual": false}, {"id": "SSG104_145", "index": 145, "question": "Coercive power is also referred to as:", "options": {"A": "Respect power.", "B": "Team power.", "C": "Discipline power.", "D": "Punishment power."}, "correct": ["D"], "vi_explanation": "D. Quyền lực trừng phạt (Punishment power).\nCoercive power dựa trên khả năng đe dọa hoặc áp dụng hình phạt nếu đối phương không tuân theo.", "has_visual": false}, {"id": "SSG104_148", "index": 148, "question": "Who may NOT be invited to a meeting?", "options": {"A": "individuals who will be affected directly by the outcome.", "B": "individuals who disagree or represent minority viewpoints.", "C": "individuals who have the power to implement decisions.", "D": "individuals who are uninvolved in the issues for discussion."}, "correct": ["D"], "vi_explanation": "D. Những người không liên quan tới vấn đề thảo luận.\nChỉ nên mời người có chuyên môn, người có quyền quyết định, người chịu tác động hoặc người có góc nhìn phản biện.", "has_visual": false}, {"id": "SSG104_163", "index": 163, "question": "Which four group-level factors can combine to cause groupthink?", "options": {"A": "Cohesion, isolation, biased leadership, and decisional stress.", "B": "Disintegration, isolation, biased group members, decisional stress.", "C": "Deperidence, cohesion, biased leader, individual's stress.", "D": "Isolation, disintegration, firm leadership, decisional stress."}, "correct": ["A"], "vi_explanation": "A. Gắn kết quá mức, cô lập nhóm, lãnh đạo thiên kiến và áp lực ra quyết định.\nĐây là 4 yếu tố cấp độ nhóm dễ đẩy tập thể rơi vào bẫy tư duy nhóm (Groupthink).", "has_visual": false}, {"id": "SSG104_173", "index": 173, "question": "____________cultures focus on the needs of the nation, community, family, or group of workers", "options": {"A": "Collectivist", "B": "Individualistic", "C": "Low-Power Distance", "D": "High-Power Distance"}, "correct": ["A"], "vi_explanation": "A. Văn hóa tập thể (Collectivist).\nĐề cao lợi ích chung của gia đình, cộng đồng, tập thể hơn lợi ích cá nhân riêng lẻ.", "has_visual": false}, {"id": "SSG104_177", "index": 177, "question": "To use THIS power: Punish in private, Inform subordinates of rules and penalties or THIS power can be used without jeopardizing personal integrity.", "options": {"A": "Reward power.", "B": "Legitimate power.", "C": "Evaluation criteria.", "D": "Coercive power."}, "correct": ["D"], "vi_explanation": "D. Quyền lực cưỡng chế (Coercive power).\nNguyên tắc dùng hình phạt mà không mất uy tín là: phạt kín đáo, thông báo rõ quy tắc/mức phạt trước và áp dụng công bằng.", "has_visual": false}, {"id": "SSG104_181", "index": 181, "question": "What is a characteristic of an informal leader? (choose 2 options)", "options": {"A": "Assigned role by a group.", "B": "Group acknowledge as their leader.", "C": "A formal capacity recognized by both those inside and outside the group.", "D": "Being encouraged to exercise the full set of management roles by high-involvement organizations."}, "correct": ["B", "D"], "vi_explanation": "B, D. Được nhóm tự công nhận là người dẫn dắt và được tổ chức trao quyền tự chủ cao.\nThủ lĩnh không chính thức (Informal leader) nổi lên từ uy tín thực tế chứ không do chức danh hành chính bổ nhiệm (A, C).", "has_visual": false}, {"id": "SSG104_189", "index": 189, "question": "Which of the following is NOT a strategy to avoid the occurrence of Groupthink?", "options": {"A": "Appointing devils' advocates in discussions.", "B": "Using outside experts.", "C": "Having a charismatic leader of the group.", "D": "Allocating different groups for different tasks."}, "correct": ["C"], "vi_explanation": "C. Có một người lãnh đạo cực kỳ cuốn hút/quyền uy (charismatic leader).\nLãnh đạo quá có uy tín dễ khiến cấp dưới ngại phản biện, vô tình làm tăng nguy cơ Groupthink thay vì ngăn chặn.", "has_visual": false}, {"id": "SSG104_191", "index": 191, "question": "John may try to bargain with Katy if ____________", "options": {"A": "Katy has more modest power over John, but John is still largely power dependent.", "B": "John has more power than Katy.", "C": "Katy has more power than John.", "D": "Katy has significant power and John is highly dependent."}, "correct": ["A"], "vi_explanation": "A. Katy có quyền lực ở mức vừa phải đối với John nhưng John vẫn phụ thuộc đáng kể.\nKhi sự chênh lệch quyền lực không quá tuyệt đối, bên yếu thế vẫn còn dư địa để thương lượng mặc cả thay vì cam chịu. (Theo ghi chú giảng viên đã chốt đáp án A.)", "has_visual": true, "image_local": "images/SSG104_191.jpg", "images": ["https://o.quizlet.com/jceQRbVkVnOzzdnUFxeKFQ_m.jpg"]}, {"id": "SSG104_194", "index": 194, "question": "What are the possible behavior responses in the consequences of power?", "options": {"A": "Trustworthiness and betrayal.", "B": "Complaint and compliance.", "C": "Commitment and compliance.", "D": "Trustworthiness and resistance."}, "correct": ["C"], "vi_explanation": "C. Sự cam kết (Commitment) và sự tuân thủ (Compliance).\nCùng với sự phản kháng (Resistance), đây là các phản ứng hành vi điển hình trước việc sử dụng quyền lực.", "has_visual": false}, {"id": "SSG104_200", "index": 200, "question": "The power of a strong individual in a group of equals, the power not to command, but to suggest and be listened to, to begin something and see it happen\" can be used to describe which type of power.", "options": {"A": "Power-from-within.", "B": "Power-with.", "C": "Power-over.", "D": "None of these answers."}, "correct": ["B"], "vi_explanation": "B. Power-with.\nLà sức mạnh của sự gợi ý, lắng nghe và đồng thuận giữa những người bình đẳng thay vì ra lệnh áp đặt.", "has_visual": false}, {"id": "SSG104_213", "index": 213, "question": "Which of the following idioms can be used to describe the relationship between power and oppression.", "options": {"A": "A blessing in disguise", "B": "The best of both worlds", "C": "Get out of hand", "D": "Two sides of the same coin"}, "correct": ["D"], "vi_explanation": "D. Hai mặt của cùng một đồng xu (Two sides of the same coin).\nQuyền lực và sự áp bức thường song hành chặt chẽ như hai mặt đối lập của cùng một hiện tượng.", "has_visual": false}, {"id": "SSG104_218", "index": 218, "question": "In the Leader Trait Research which trait includes strong analytical abilities?", "options": {"A": "Self-confidence.", "B": "Leadership motivation.", "C": "Drive.", "D": "Cognitive ability."}, "correct": ["D"], "vi_explanation": "D. Năng lực nhận thức (Cognitive ability).\nGồm tư duy phân tích, tổng hợp thông tin và giải quyết vấn đề phức tạp ở người lãnh đạo.", "has_visual": false}, {"id": "SSG104_234", "index": 234, "question": "Of all the bases of power available to man, which power is the most often used, most often c most difficult to control?", "options": {"A": "Reward Power.", "B": "Coercive power.", "C": "Referent Power.", "D": "Legitimate Power."}, "correct": ["B"], "vi_explanation": "B. Quyền lực cưỡng chế (Coercive power).\nDù dễ bị lạm dụng nhất nhưng hình phạt lại khó kiểm soát hệ lụy tâm lý và sự phản kháng ngầm.", "has_visual": false}, {"id": "SSG104_238", "index": 238, "question": "What is the best demonstration of counterpower?", "options": {"A": "B feels less need to acquiesce to A because of B's temporary job-", "B": "B is highly susceptible to the supervisor's influence-", "C": "B has other sources of power to buffer the effects of A's power.", "D": "All of them are incorrect."}, "correct": ["C"], "vi_explanation": "C. B có những nguồn quyền lực khác để giảm bớt tác động quyền lực từ A.\nCounterpower là sức mạnh đối trọng giúp bên yếu thế giữ cân bằng và không phụ thuộc một chiều.", "has_visual": false}, {"id": "SSG104_240", "index": 240, "question": "Which power of the following exists when person B submits to person A because B feels tha exert power in a certain domain?", "options": {"A": "Expert Power.", "B": "Legitimate Power.", "C": "Reward Power.", "D": "Coercive Power."}, "correct": ["B"], "vi_explanation": "B. Quyền lực chính danh (Legitimate Power).\nB chấp nhận phục tùng vì công nhận A có thẩm quyền hợp pháp trong phạm vi chức vụ đó.", "has_visual": false}, {"id": "SSG104_270", "index": 270, "question": "When does a person obtain the expert power?", "options": {"A": "Person A has higher status than person B.", "B": "Person A has more expertise knowledge than person B.", "C": "Person A group is bigger than person B.", "D": "Person A has more friend than person B."}, "correct": ["B"], "vi_explanation": "B. Người A có kiến thức chuyên môn sâu rộng hơn người B.\nExpert power bắt nguồn từ trình độ chuyên môn và kinh nghiệm đáng tin cậy.", "has_visual": false}, {"id": "SSG104_273", "index": 273, "question": "Arises from our sense of connection, our bonding with other human beings, and with the environment\" can be used to describe which type of power?", "options": {"A": "Power-from-within.", "B": "Power-with.", "C": "Power-over.", "D": "None of these answers."}, "correct": ["A"], "vi_explanation": "A. Power-from-within (nội lực bên trong).\nSức mạnh nội tại nảy sinh từ sự kết nối sâu sắc với bản thân, con người và môi trường xung quanh. (Kèm xem ảnh minh họa.)", "has_visual": true, "image_local": "images/SSG104_273.png", "images": ["https://o.quizlet.com/NZFLNlD3fBOQSwjQ25zp1A_m.png"]}, {"id": "SSG104_274", "index": 274, "question": "The word \"power\" literally means:", "options": {"A": "\"To be able to\"", "B": "\"The influence\"", "C": "'The strength\"", "D": "None of these answers"}, "correct": ["A"], "vi_explanation": "A. \"To be able to\" (có khả năng làm gì đó).\nTheo nghĩa gốc từ điển/từ nguyên Latin (posse), \"power\" nghĩa đen là năng lực thực hiện hành động. (Lưu ý thêm theo ghi chú gốc: có thể phụ thuộc quan điểm giảng viên.)", "has_visual": false}, {"id": "SSG104_293", "index": 293, "question": "What is NOT true about the leader-member exchange theory?", "options": {"A": "It focuses attention on consequences associated with the leadership process.", "B": "It views leadership as consisting of a number of dyadic relationships linking the leader ....", "C": "Low-quality exchange relationships tend to be associated with lower levels of performance, commitment, and satisfaction-", "D": "The quality of the relationship is reflected by the degree of success in task performance."}, "correct": ["D"], "vi_explanation": "D. \"Chất lượng mối quan hệ được phản ánh qua mức độ thành công khi làm việc\" là SAI theo thuyết LMX.\nThuyết Trao đổi Lãnh đạo–Thành viên (LMX) xem lãnh đạo xây dựng các mối quan hệ cặp đôi (dyadic) chất lượng cao/thấp khác nhau, ảnh hưởng đến hiệu suất chứ không định nghĩa ngược lại.", "has_visual": false}, {"id": "SSG104_299", "index": 299, "question": "What is NOT TRUE about power-with?", "options": {"A": "It is the power to suggest and be listened to.", "B": "It arises from our sense of connection.", "C": "The leader must not abuse his power.", "D": "Respect and equality are shown in the group."}, "correct": ["B"], "vi_explanation": "B. \"Xuất phát từ cảm giác kết nối với con người và môi trường\" là định nghĩa của Power-from-within, KHÔNG phải Power-with.\nPower-with là quyền lực chia sẻ bình đẳng trong tập thể biết lắng nghe lẫn nhau. (Kèm xem ảnh.)", "has_visual": true, "image_local": "images/SSG104_299.jpg", "images": ["https://o.quizlet.com/peEQ3G0lJ9X.hhw-rMeoAg_m.jpg"]}, {"id": "SSG104_305", "index": 305, "question": "Which of the following provides a great advantage to the leader in their relationships with tea?", "options": {"A": "Authority to control teammates", "B": "Superior status", "C": "Cultural intelligence", "D": "Explicit in communication"}, "correct": ["C"], "vi_explanation": "C. Trí tuệ văn hóa (Cultural intelligence).\nHiểu và thích ứng nhạy bén với sự khác biệt văn hóa giúp người lãnh đạo gắn kết hiệu quả với mọi thành viên trong nhóm.", "has_visual": false}, {"id": "SSG104_327", "index": 327, "question": "Status can be defined as:", "options": {"A": "A person's perceived level of importance or significance within a particular context.", "B": "A result of power, with its roots in global colonialism and conquests", "C": "An action can deny certain groups jobs that pay living wages, can establish unequal. can deny affordable housing, and the list goes on", "D": "None of these above"}, "correct": ["A"], "vi_explanation": "A. Mức độ quan trọng hoặc vị thế được nhìn nhận của một người trong bối cảnh nhất định.\nStatus phản ánh vị trí xã hội hay thứ bậc được công nhận trong tập thể.", "has_visual": false}, {"id": "SSG104_331", "index": 331, "question": "Four group level factors that combine to cause groupthink are", "options": {"A": "cohesion, isolation, biased leadership, decisional stress.", "B": "cohesion, isolation, discouragement, biased leadership.", "C": "cohesion, isolation, decisional stress, aggressiveness.", "D": "isolation, biased leadership, aggressiveness, discouragement."}, "correct": ["A"], "vi_explanation": "A. Gắn kết cao, cô lập nhóm, lãnh đạo thiên kiến và áp lực ra quyết định.\nBốn nguyên nhân cấp nhóm kinh điển dẫn đến hội chứng Groupthink.", "has_visual": false}]}, {"id": "comm", "title": "Giao tiếp, Phi ngôn ngữ & Cuộc họp", "tag": "Giao tiếp & Họp", "questions": [{"id": "SSG104_002", "index": 2, "question": "All of the statements below are true about business letters, EXCEPT:", "options": {"A": "While e-mail and text messages may be used more frequently today, the effective business letter remains a common form of written communication", "B": "Letters are no longer used in business context since people prefer to convey information via shorter messages like emails or memos.", "C": "Just like an e-mail with an attachment, the letter sometimes has additional documents that are delivered with it.", "D": "Letters are brief, print messages often used externally to inform or persuade customers, vendors, or the public."}, "correct": ["B"], "vi_explanation": "B. \"Thư thương mại không còn được dùng nữa\" là phát biểu SAI.\nDù email và tin nhắn phổ biến hơn, business letter vẫn là hình thức giao tiếp trang trọng quen thuộc với đối tác và khách hàng bên ngoài.", "has_visual": false}, {"id": "SSG104_012", "index": 12, "question": "Why is it important to close a professional email with a signature block that contains your name and business contact information?", "options": {"A": "To fill space at the bottom of the email.", "B": "To make the email appear longer and more detailed", "C": "To provide recipients with your identity and contact details for easy follow-up.", "D": "To comply with legal requirements for all types of emails"}, "correct": ["C"], "vi_explanation": "C. Cung cấp danh tính và thông tin liên hệ để người nhận tiện phản hồi lại.\nChữ ký email chuyên nghiệp giúp xác nhận người gửi và tạo thuận lợi cho việc liên lạc tiếp theo.", "has_visual": false}, {"id": "SSG104_042", "index": 42, "question": "Why is it important to use a good format for effective business e-mails, particularly in a professional setting?", "options": {"A": "Create competent impression.", "B": "Support for communicating effectively.", "C": "Reflect professionalism and follow the rules of netiquette", "D": "All bove"}, "correct": ["D"], "vi_explanation": "D. Tất cả các ý trên đều đúng.\nĐịnh dạng email chuẩn mực vừa tạo ấn tượng chuyên nghiệp, vừa giúp truyền đạt rõ ý và tuân thủ phép lịch sự trên mạng (netiquette).", "has_visual": false}, {"id": "SSG104_061", "index": 61, "question": "Which of the statements below are NOT correct about nonverbal communication? (choose 2 options)", "options": {"A": "Nonverbal communication is irreversible.", "B": "Nonverbal communication is the process of conveying a message without the use of words.", "C": "It is possible to separate one nonverbal action from the context of all the other verbal and nonverbal communication acts.", "D": "Most people tend to believe the nonverbal message over the verbal message since we often react faster than we think, therefore nonverbal responses communicate our initial reaction before we can process it through language or formulate an appropriate response.", "E": "Nonverbal cues are always clear, so that we do not need contextual clues to understand them."}, "correct": ["C", "E"], "vi_explanation": "C, E. Có thể tách rời hành động phi ngôn ngữ khỏi bối cảnh (sai) và tín hiệu phi ngôn ngữ luôn rõ ràng không cần ngữ cảnh (sai).\nGiao tiếp phi ngôn ngữ luôn gắn chặt với ngữ cảnh và dễ bị hiểu nhầm nếu tách rời.", "has_visual": false}, {"id": "SSG104_065", "index": 65, "question": "Which is TRUE about minutes for meeting?", "options": {"A": "Minutes are a written document that serves to record the interaction and summarize the major points raised, decisions taken, and actions assigned.", "B": "The main purpose of minutes is to get buy-in from decision-makers", "C": "Minutes are normally used for communicating policies, procedures, or related official business within an organization.", "D": "Minutes are brief messages sent to recipients that are often outside the organization."}, "correct": ["A"], "vi_explanation": "A. Biên bản họp là văn bản ghi lại nội dung trao đổi, các điểm chính, quyết định đã chốt và đầu việc phân công.\nCác phương án B, C, D lần lượt mô tả đề xuất, thông báo nội bộ hoặc thư đối ngoại.", "has_visual": false}, {"id": "SSG104_069", "index": 69, "question": "The study of body movements is key to understanding nonverbal communication, called:", "options": {"A": "Kinesics", "B": "Chronemics", "C": "Proxemics", "D": "Haptics"}, "correct": ["A"], "vi_explanation": "A. Kinesics (ngôn ngữ cơ thể/cử động).\nChronemics nghiên cứu thời gian, Proxemics là khoảng cách và Haptics là tiếp xúc chạm.", "has_visual": false}, {"id": "SSG104_070", "index": 70, "question": "What type of nonverbal communication involves the verbal and nonverbal aspects of speech?", "options": {"A": "Touch", "B": "Space", "C": "Artifacts", "D": "Paralanguage"}, "correct": ["D"], "vi_explanation": "D. Cận ngôn ngữ (Paralanguage).\nBao gồm âm lượng, tốc độ nói, ngữ điệu, ngập ngừng — tức các yếu tố phi từ ngữ đi kèm lời nói.", "has_visual": false}, {"id": "SSG104_075", "index": 75, "question": "What should be prepared before the meeting?", "options": {"A": "Plan meeting schedule", "B": "Decide how to meet", "C": "Invite meeting participants", "D": "All above"}, "correct": ["D"], "vi_explanation": "D. Tất cả các việc trên đều cần chuẩn bị trước khi họp.\nLên lịch, chọn hình thức họp và mời đúng thành phần giúp cuộc họp diễn ra trơn tru.", "has_visual": false}, {"id": "SSG104_077", "index": 77, "question": "What is nonverbal communication?", "options": {"A": "the process of conveying a message with the use of words", "B": "the process of convterm-276eying a message with only eye contact", "C": "the process of conveying a message without the use of words", "D": "the process of conveying a message with only gestures and facial expressions"}, "correct": ["C"], "vi_explanation": "C. Quá trình truyền tải thông điệp không dùng đến lời nói.\nGiao tiếp phi ngôn ngữ sử dụng cử chỉ, ánh mắt, giọng điệu, khoảng cách... thay cho câu chữ.", "has_visual": false}, {"id": "SSG104_084", "index": 84, "question": "Deborah Duarte and Nancy Snyder point out that \"technology cannot make up for poor planning or ill-conceived meetings. In fact, it can make the situation worse. \" In order to avoid such problems in a virtual meeting, you should:", "options": {"A": "begin a virtual meeting by sharing the meeting agenda.", "B": "invite more people to participate because virtual meeting are typically not restricted in size due to the number of seats in a conference room-", "C": "make sure that participants have access to the technology and know how to use it effectively.", "D": "use technology you've used before so you don't have to worry about testing it prior to meeting with the group."}, "correct": ["C"], "vi_explanation": "C. Đảm bảo mọi người tham dự đều truy cập được công nghệ và biết cách dùng hiệu quả.\nCông nghệ trục trặc sẽ làm buổi họp online rối loạn dù chuẩn bị nội dung tốt.", "has_visual": false}, {"id": "SSG104_085", "index": 85, "question": "Groups not only satisfy need to belong, but also provide information, assistance and ...", "options": {"A": "developed skills", "B": "better communication", "C": "social support", "D": "motivation"}, "correct": ["C"], "vi_explanation": "C. Sự hỗ trợ xã hội (social support).\nNgoài đáp ứng nhu cầu thuộc về và thông tin, nhóm còn là điểm tựa tinh thần và hỗ trợ thực tế cho thành viên.", "has_visual": false}, {"id": "SSG104_086", "index": 86, "question": "What is one disadvantages of having large group? (Thủy Tiên)", "options": {"A": "Overestimate their abilities", "B": "Rank themselves above average", "C": "More involvement", "D": "Reduce communication"}, "correct": ["D"], "vi_explanation": "D. Giảm hiệu quả giao tiếp (Reduce communication).\nNhóm quá đông khiến mỗi người ít cơ hội phát biểu và thông tin truyền đạt dễ bị nhiễu.", "has_visual": false}, {"id": "SSG104_089", "index": 89, "question": "This gesture is considered an insult in:", "options": {"A": "Japan", "B": "Brazil", "C": "France", "D": "India", "E": "Nigeria", "F": "Italy"}, "correct": ["B"], "vi_explanation": "B. Brazil.\nCử chỉ tay trong ảnh minh họa (vòng ngón cái và ngón trỏ) mang nghĩa thô tục/xúc phạm tại Brazil.", "has_visual": true, "image_local": "images/SSG104_089.png", "images": ["https://o.quizlet.com/Ml3nWgnREDCcKznG1RG9tw_m.png"]}, {"id": "SSG104_112", "index": 112, "question": "At the end of a meeting, you should", "options": {"A": "Be the first to leave the meeting room", "B": "Take group photo and have conversation with members to build personal relationships with them", "C": "Ask a lot of questions to test the team members' understanding of the discussion", "D": "Be brief and recapture the key points"}, "correct": ["D"], "vi_explanation": "D. Ngắn gọn và tóm tắt lại những điểm chính đã chốt.\nKết thúc cuộc họp đúng giờ với bản tóm tắt rõ ràng giúp mọi người nhớ đầu việc cần làm.", "has_visual": false}, {"id": "SSG104_133", "index": 133, "question": "Which statement is wrong about components of agenda", "options": {"A": "List of sponsors.", "B": "List of participants.", "C": "A list of points to be considered and a brief summary of relevant information.", "D": "Purposes of meeting."}, "correct": ["A"], "vi_explanation": "A. Danh sách nhà tài trợ (List of sponsors) không thuộc thành phần chuẩn của chương trình họp (agenda).\nAgenda gồm mục đích họp, người tham dự và danh mục các điểm cần thảo luận.", "has_visual": false}, {"id": "SSG104_144", "index": 144, "question": "Meetings give members a/an _________________ that boosts their motivation to implement group ideas and actions", "options": {"A": "opportunity to participate in the group decision making process.", "B": "chance to argue.", "C": "time to relax.", "D": "time to chat."}, "correct": ["A"], "vi_explanation": "A. Cơ hội tham gia vào quá trình ra quyết định của nhóm.\nKhi được góp tiếng nói vào quyết định chung, thành viên sẽ có động lực thực thi cao hơn hẳn.", "has_visual": false}, {"id": "SSG104_150", "index": 150, "question": "Good advice for meeting participants may include:", "options": {"A": "become angry for no good reason.", "B": "demand much more information than is needed.", "C": "offer much more information than is needed.", "D": "demonstrate professionalism in your verbal and nonverbal interactions."}, "correct": ["D"], "vi_explanation": "D. Thể hiện sự chuyên nghiệp trong cả giao tiếp bằng lời và phi ngôn ngữ.\nTác phong lịch sự, đúng mực giúp cuộc họp hiệu quả và tôn trọng lẫn nhau.", "has_visual": false}, {"id": "SSG104_151", "index": 151, "question": "Janet does not want to get involved in any disputes, discussion or conversations with her colleagues. She gets to work late and fails to show up at meetings as she wants to avoid any tasks may be assigned to her. However, she always wants to be a part of any success her team made. Economists call this kind of person is:", "options": {"A": "Pretending.", "B": "Untrustworthy.", "C": "Dishonest.", "D": "Free rider problem."}, "correct": ["D"], "vi_explanation": "D. Hiện tượng \"đi xe miễn phí\" (Free rider problem).\nJanet trốn việc, không đóng góp nhưng vẫn muốn hưởng thành quả chung của cả nhóm.", "has_visual": false}, {"id": "SSG104_152", "index": 152, "question": "Which of the following is bad advice for group meeting?", "options": {"A": "The group extends meeting time until they have the final decision satisfying all members.", "B": "The group accepts the will of the majority even though some members do not like that de", "C": "The group follows an approved agenda that promotes orderly business.", "D": "The group protects the rights of all members by guaranteeing everyone the right to speak"}, "correct": ["A"], "vi_explanation": "A. Kéo dài cuộc họp vô tận chỉ để chờ quyết định làm vừa lòng 100% mọi người.\nThực tế cuộc họp cần bám khung thời gian và tôn trọng nguyên tắc biểu quyết đa số.", "has_visual": false}, {"id": "SSG104_169", "index": 169, "question": "This gesture is considered an insult in:", "options": {"A": "Japan", "B": "Brazil", "C": "France", "D": "India", "E": "Nigeria", "F": "Italy"}, "correct": ["B"], "vi_explanation": "B. Brazil.\nTheo ảnh cử chỉ tay đi kèm câu hỏi (hình bàn tay tạo dấu hiệu), cử chỉ này bị coi là xúc phạm ở Brazil.", "has_visual": true, "image_local": "images/SSG104_169.png", "images": ["https://o.quizlet.com/wvxuWU6tCWDwXLCDb9C4XA_m.png"]}, {"id": "SSG104_180", "index": 180, "question": "When conducting a meeting, you should", "options": {"A": "Be bold and honest, not afraid to hurt people's feeling", "B": "Get every team member to voice out their feeling and opinions", "C": "Make it as short as possible because time is gold", "D": "Favor relationships"}, "correct": ["B"], "vi_explanation": "B. Khuyến khích mọi thành viên nói lên suy nghĩ và quan điểm của mình.\nNgười điều phối cần tạo không gian an toàn để thu thập đủ ý kiến đa chiều thay vì áp đặt hay vội vã.", "has_visual": false}, {"id": "SSG104_197", "index": 197, "question": "According to Barge, Lumsden, Parker, and Hoffman, all of the following recommended actions and attitudes can help you facilitate a meeting well, EXCEPT", "options": {"A": "Begin with something positive.", "B": "Make sure people understand their roles.", "C": "Keep to your agenda.", "D": "Begin the meeting only after all relevant group members have arrived."}, "correct": ["D"], "vi_explanation": "D. \"Chỉ bắt đầu họp khi toàn bộ thành viên có mặt đầy đủ\" là NGOẠI LỆ.\nChờ người đi muộn sẽ làm lãng phí thời gian của cả tập thể; nên bắt đầu đúng giờ theo lịch.", "has_visual": false}, {"id": "SSG104_198", "index": 198, "question": "The disadvantage of written messages is that they", "options": {"A": "Can have legal value.", "B": "Can be revised and edited to ensure they adhere to the principles of business communication.", "C": "Can be reread and studied, which is important if a message is long, is complex, or has been written in anger.", "D": "Can be viewed as being more formal, in part because they are permanent."}, "correct": ["D"], "vi_explanation": "D. Có thể bị xem là quá trang trọng/cứng nhắc một phần vì tính lưu trữ vĩnh viễn của nó.\nLưu ý câu A, B, C đều là ưu điểm của văn bản viết; chỉ D nêu mặt hạn chế khi cần sự linh hoạt, thân mật.", "has_visual": true, "image_local": "images/SSG104_198.png", "images": ["https://o.quizlet.com/rZ7Ib5YkrPGyPcPf-C5wTw_m.png"]}, {"id": "SSG104_205", "index": 205, "question": "Which behavior people often DON'T display when they are being deceptive", "options": {"A": "Reduction in eye contact while engaged in a conversation.", "B": "Awkward pauses in conversation.", "C": "Decreased rate of speech.", "D": "Increased smiling."}, "correct": ["D"], "vi_explanation": "D. Cười nhiều hơn (Increased smiling).\nKhi nói dối, người ta thường căng thẳng nên hay né tránh ánh mắt, ngập ngừng hoặc nói chậm lại chứ ít khi cười tự nhiên tăng lên.", "has_visual": false}, {"id": "SSG104_217", "index": 217, "question": "When sending attachments with an email, you should", "options": {"A": "not include an enclosure note because the attachments appear inline in the email body.", "B": "not include an enclosure note as the recipient can see that there are attachments in the email.", "C": "include the enclosure note because attachments are not always obvious when reading er of devices.", "D": "include a statement that the attachments are in a separate email and send attachments a email."}, "correct": ["C"], "vi_explanation": "C. Ghi rõ câu nhắc có file đính kèm trong nội dung email.\nVì trên một số thiết bị hoặc ứng dụng mail, file đính kèm có thể khó thấy hoặc dễ bị sót.", "has_visual": false}, {"id": "SSG104_220", "index": 220, "question": "A written document summarizing what has been discussed or decided, and what actions the group members are to take as a result of the meeting is called:", "options": {"A": "Summary", "B": "Minutes", "C": "Agenda", "D": "Record"}, "correct": ["B"], "vi_explanation": "B. Biên bản cuộc họp (Minutes).\nSummary là tóm tắt chung, Agenda là lịch trình họp trước khi diễn ra, còn Minutes là văn bản ghi chép chính thức kết quả và việc cần làm sau họp.", "has_visual": false}, {"id": "SSG104_226", "index": 226, "question": "Which is TRUE about the direct feedback?", "options": {"A": "It only occurs when all parties involved are together at the same time.", "B": "It is a response that does not directly come from source.", "C": "A message initiated by email to a specific person is a type of direct feedback.", "D": "It is a response that comes from the receiver."}, "correct": ["D"], "vi_explanation": "D. Là phản hồi trực tiếp đến từ người nhận thông điệp.\nDirect feedback xuất phát từ chính đối tượng tiếp nhận chứ không qua bên trung gian.", "has_visual": false}, {"id": "SSG104_250", "index": 250, "question": "Which is NOT a part of an email?", "options": {"A": "Subject lines", "B": "Sign-off", "C": "Signature", "D": "Topic"}, "correct": ["D"], "vi_explanation": "D. Topic (không phải tên thành phần cấu trúc của email; email dùng Subject line).\nMột email chuẩn gồm dòng tiêu đề (Subject), lời chào, nội dung, lời kết (Sign-off) và chữ ký (Signature).", "has_visual": false}, {"id": "SSG104_255", "index": 255, "question": "Which type of feedback is used for encouragement in response to a message?", "options": {"A": "Evaluative", "B": "Interpretive", "C": "Supportive", "D": "Probing"}, "correct": ["C"], "vi_explanation": "C. Phản hồi mang tính khích lệ/ủng hộ (Supportive).\nSupportive feedback truyền tải sự động viên, ghi nhận đối với người phát ngôn.", "has_visual": false}, {"id": "SSG104_256", "index": 256, "question": "Which type of feedback requests confirmation or clarification of a message, and is often expressed in the form of a question?", "options": {"A": "Evaluative", "B": "Interpretive", "C": "Supportive", "D": "Probing"}, "correct": ["B"], "vi_explanation": "B. Phản hồi diễn giải/kiểm chứng (Interpretive).\nThường đặt dưới dạng câu hỏi để xác nhận lại xem mình hiểu đúng ý người nói hay chưa.", "has_visual": false}, {"id": "SSG104_257", "index": 257, "question": "Which type of feedback communicates sympathy and empathy for the source of the message?", "options": {"A": "Evaluative", "B": "Interpretive", "C": "Supportive", "D": "Understanding"}, "correct": ["D"], "vi_explanation": "D. Phản hồi thấu hiểu (Understanding).\nThể hiện sự cảm thông và đồng cảm sâu sắc với người gửi thông điệp.", "has_visual": false}, {"id": "SSG104_264", "index": 264, "question": "Hung receives an email from the client about a project his team is working on, but he does not know the answer to it. He should", "options": {"A": "respond immediately with any information he thinks he knows about the inquiry", "B": "try to find out the answer himself and only reply when he finds out the information", "C": "not reply at all because he doesn't know the answer and it's not his concern", "D": "respond within 24 hours that he's searching for the answer to their question and will be contacting them again soon"}, "correct": ["D"], "vi_explanation": "D. Phản hồi trong vòng 24 giờ báo mình đang tìm câu trả lời và sẽ liên hệ lại sớm.\nKhách hàng đánh giá cao sự phản hồi nhanh và minh bạch hơn là im lặng chờ tìm xong mới trả lời.", "has_visual": false}, {"id": "SSG104_265", "index": 265, "question": "Eye contact with your team members can be maintained by", "options": {"A": "always looking at a few people.", "B": "always looking at your favourite people.", "C": "always looking at the nearest people.", "D": "looking at every individual in a regular pattern."}, "correct": ["D"], "vi_explanation": "D. Nhìn lần lượt từng thành viên theo nhịp tự nhiên.\nChia đều ánh mắt giúp tất cả mọi người đều cảm thấy được tôn trọng và lắng nghe.", "has_visual": false}, {"id": "SSG104_268", "index": 268, "question": "Which of the following is the best example of constructive feedback?", "options": {"A": "Not giving full attention to a customer gives the image that we don't think he or she is important.", "B": "I believe that using mobile phone for personal purpose during working hours is not allowed in this company, but it seems like you do not see the real benefit of this policy.", "C": "You are not paying attention to the customer when you are having a conversation with someone else at the same time.", "D": "You were trained that you'll make a more positive corporate impression if you give the customer your complete attention."}, "correct": ["D"], "vi_explanation": "D. Nhắc lại chuẩn mực đào tạo theo hướng tích cực: tập trung cho khách sẽ tạo ấn tượng tốt hơn.\nCâu D góp ý nhẹ nhàng về lợi ích hành vi thay vì chỉ trích gay gắt hay suy diễn như A, B, C.", "has_visual": false}, {"id": "SSG104_272", "index": 272, "question": "All of the following strategies are for keeping a meeting moving at a comfortable pace EXCEPT", "options": {"A": "Only begin the meeting until all important group members are present.", "B": "Place a time limit on each agenda item.", "C": "Stay focused on the meeting's goal.", "D": "Schedule another meeting to discuss unfinished business."}, "correct": ["A"], "vi_explanation": "A. \"Chỉ bắt đầu họp khi toàn bộ thành viên quan trọng có mặt đầy đủ\" là NGOẠI LỆ.\nChờ đợi làm chậm tiến độ chung; cần bắt đầu đúng giờ và giới hạn thời gian từng mục.", "has_visual": false}, {"id": "SSG104_278", "index": 278, "question": "Which of the following labels does NOT represent how member behavior can disrupt a meeting?", "options": {"A": "Loudmouth.", "B": "whisperer.", "C": "latecomer.", "D": "summarizer."}, "correct": ["D"], "vi_explanation": "D. Người tóm tắt ý (summarizer).\nSummarizer hỗ trợ làm rõ tiến trình họp, trái ngược với người nói dai (loudmouth), thì thầm (whisperer) hay đi trễ (latecomer).", "has_visual": false}, {"id": "SSG104_313", "index": 313, "question": "Nonverbal behavior that reflects positive attitude is.........", "options": {"A": "moving your knees and your feet toward to door", "B": "looking at your watch", "C": "playing with your jewelry", "D": "leaning your body toward the person with whom you are conversing"}, "correct": ["D"], "vi_explanation": "D. Nghiêng người về phía người đang trò chuyện cùng bạn.\nTư thế hướng về phía đối phương thể hiện sự chú tâm và thái độ tích cực, trái ngược với nhìn đồng hồ hay hướng chân ra cửa.", "has_visual": false}, {"id": "SSG104_314", "index": 314, "question": "\"Kinesics\" is the term for the study of:", "options": {"A": "Paralanguage", "B": "Body movements", "C": "Physical characteristics", "D": "Artifacts"}, "correct": ["B"], "vi_explanation": "B. Cử động cơ thể (Body movements).\nKinesics chuyên nghiên cứu ý nghĩa giao tiếp qua nét mặt, ánh mắt, cử chỉ và tư thế cơ thể.", "has_visual": false}, {"id": "SSG104_315", "index": 315, "question": "These tips below are guidelines for writing an effective email, EXCEPT:", "options": {"A": "If you include a link, test it to make sure it is complete.", "B": "Reread, revise, and review", "C": "Use \"Reply All\" actively to make sure everyone who received the initial e-mail can keep track on the on-going conversation.", "D": "Subject lines should be clear, brief, and specific.", "E": "Proper salutations should demonstrate respect and avoid mix-ups in case a message is accidentally sent to the wrong recipient."}, "correct": ["C"], "vi_explanation": "C. \"Dùng Reply All thật nhiều cho mọi người theo dõi\" là NGOẠI LỆ.\nLạm dụng Reply All gây spam hộp thư cho những người không liên quan trực tiếp.", "has_visual": false}, {"id": "SSG104_316", "index": 316, "question": "According to Edward Hall, the four main categories of distance used in communication are", "options": {"A": "Intimate, Touch, Gestures, and Public space.", "B": "Intimate, Personal, Social, and Public space.", "C": "Personal, Artifacts, Paralanguage, and Public space.", "D": "Personal, Facial expressions, Physical characteristics, and Public space."}, "correct": ["B"], "vi_explanation": "B. Thân mật (Intimate), Cá nhân (Personal), Xã hội (Social) và Công cộng (Public).\nĐây là 4 vùng khoảng cách giao tiếp kinh điển theo nghiên cứu Proxemics của Edward Hall.", "has_visual": false}, {"id": "SSG104_317", "index": 317, "question": "Below are guidelines for Facilitating a Meeting, EXCEPT:", "options": {"A": "Begin with something positive", "B": "Tend to housekeeping details", "C": "Make use of sarcasm and cynicism to make things fun and healthy", "D": "Expect the unexpected"}, "correct": ["C"], "vi_explanation": "C. \"Dùng lời châm biếm, mỉa mai cho vui\" là NGOẠI LỆ.\nChâm biếm dễ gây tổn thương, mất an toàn tâm lý và phá hỏng không khí cuộc họp.", "has_visual": false}, {"id": "SSG104_320", "index": 320, "question": "Which option below is NOT a reason for engaging in communication?", "options": {"A": "Understand our identity", "B": "Meet our needs", "C": "Understand communication contexts", "D": "Gain information", "E": "Manipulate other people"}, "correct": ["E"], "vi_explanation": "E. Thao túng người khác (Manipulate other people).\nGiao tiếp lành mạnh nhằm hiểu bản thân, đáp ứng nhu cầu, nắm bối cảnh và trao đổi thông tin — không phải để thao túng.", "has_visual": false}, {"id": "SSG104_323", "index": 323, "question": "Which of the following is the best option for a meeting that requires close contact and collabo", "options": {"A": "Use round tables or tables arranged in a circular pattern.", "B": "Use square tables.", "C": "Use rectangular tables.", "D": "Use U-shaped tables."}, "correct": ["A"], "vi_explanation": "A. Dùng bàn tròn hoặc xếp bàn theo vòng tròn.\nBố cục vòng tròn xóa bỏ vị trí áp đặt đầu bàn, giúp mọi người dễ nhìn nhau và trao đổi bình đẳng.", "has_visual": false}, {"id": "SSG104_347", "index": 347, "question": "Which traits are taking on increasing importance in the business world today?", "options": {"A": "Multiculturalism and cultural intelligence.", "B": "Verbal and nonverbal communication.", "C": "Cultural intelligence and language.", "D": "Style, pace, language and nonverbal communication."}, "correct": ["A"], "vi_explanation": "A. Đa văn hóa và trí tuệ văn hóa (Multiculturalism and cultural intelligence).\nTrong môi trường kinh doanh toàn cầu hóa, khả năng thấu hiểu và làm việc đa văn hóa ngày càng thiết yếu.", "has_visual": false}]}, {"id": "teamwork", "title": "Teamwork & Phát triển nhóm", "tag": "Teamwork", "questions": [{"id": "SSG104_001", "index": 1, "question": "In which stage of group development, members expose information about themselves in polite but tentative interactions, explore the purposes of the group and gather information about each other's interests, skills, and personal tendencies? (soạn độc quyền bởi Thủy Tiên)", "options": {"A": "Forming", "B": "Storming", "C": "Norming", "D": "Performing", "E": "Adjourning"}, "correct": ["A"], "vi_explanation": "A. Forming (Giai đoạn hình thành).\nỞ bước đầu tiên của mô hình Tuckman, các thành viên giao tiếp xã giao dè dặt để tìm hiểu mục tiêu nhóm, sở thích và năng lực của nhau. (Lưu ý thêm bảng/ảnh trong doc gốc của giảng viên.)", "has_visual": true, "image_local": "images/SSG104_001.png", "images": ["https://o.quizlet.com/UloHDr-LK75WmnC-IhWUVw_m.png"]}, {"id": "SSG104_006", "index": 6, "question": "Formal group is not used to", "options": {"A": "devise plans", "B": "negotiate", "C": "satisfy needs of affiliation", "D": "increase commitment"}, "correct": ["C"], "vi_explanation": "C. Nhóm chính thức (Formal group) không lập ra chủ yếu để thỏa mãn nhu cầu giao lưu tình cảm.\nNhóm chính thức do tổ chức thành lập để phân công công việc, lập kế hoạch và đạt mục tiêu tổ chức.", "has_visual": false}, {"id": "SSG104_013", "index": 13, "question": "What team consists of a group of people who come together as a distinct organizational unit to implement projects?", "options": {"A": "Project team", "B": "Functional team", "C": "Matrix team", "D": "Modern Teams"}, "correct": ["A"], "vi_explanation": "A. Nhóm dự án (Project team).\nĐây là nhóm tập hợp nhân sự thành một đơn vị riêng biệt để triển khai và hoàn thành một dự án cụ thể.", "has_visual": false}, {"id": "SSG104_020", "index": 20, "question": "Who will judge the success of a project in the contract team?", "options": {"A": "Senior managers", "B": "Department heads", "C": "Junior managers", "D": "Clients"}, "correct": ["D"], "vi_explanation": "D. Khách hàng (Clients).\nNhóm hợp đồng (Contract team) được thuê từ bên ngoài nên chính khách hàng là bên đánh giá kết quả dự án.", "has_visual": false}, {"id": "SSG104_033", "index": 33, "question": "Which stage is suitable for this following statement \"Mem bers implement plans and achieve goals\"?", "options": {"A": "Performing", "B": "Storming", "C": "Adjourning", "D": "Norming", "E": "Forming"}, "correct": ["A"], "vi_explanation": "A. Performing (Giai đoạn thực thi hiệu quả).\nKhi thành viên bắt tay triển khai kế hoạch và hoàn thành mục tiêu trơn tru là nhóm đang ở giai đoạn Performing.", "has_visual": false}, {"id": "SSG104_034", "index": 34, "question": "Which is the highest stage of Tuckman's Stages of Group Development?", "options": {"A": "Forming", "B": "Storming", "C": "Adjourning", "D": "Norming", "E": "Performing"}, "correct": ["E"], "vi_explanation": "E. Performing.\nPerforming là giai đoạn đạt độ trưởng thành và hiệu suất cao nhất trong 5 giai đoạn phát triển nhóm của Tuckman (trước khi giải thể Adjourning).", "has_visual": true, "image_local": "images/SSG104_034.jpg", "images": ["https://o.quizlet.com/dTfwjPYbYueMjAEw.C1hdQ_m.jpg"]}, {"id": "SSG104_047", "index": 47, "question": "Which of the following strategies CAN NOT support university students enhancing cultural intelligence?", "options": {"A": "Reading books written by authors from diverse cultural backgrounds.", "B": "Participating in intercultural workshops, seminars, festivals, and events.", "C": "Involving in work and travel abroad, or exchange learning program.", "D": "Working in a group with the same teammates in previous semesters."}, "correct": ["D"], "vi_explanation": "D. Chỉ làm việc nhóm với đúng những người bạn quen từ các kỳ trước.\nLàm việc mãi trong vòng tròn quen thuộc không giúp tiếp xúc với sự đa dạng văn hóa.", "has_visual": false}, {"id": "SSG104_054", "index": 54, "question": "Why does the tasks and goals set by teams cannot be achieved by each individual? (Choose 2 options)", "options": {"A": "Time and resource constraints", "B": "Few individuals possess all the competencies and related expertise", "C": "All members have competence and skills", "D": "Human resource is available"}, "correct": ["A", "B"], "vi_explanation": "A, B. Giới hạn thời gian/nguồn lực và hiếm có cá nhân nào sở hữu toàn bộ kỹ năng chuyên môn cần thiết.\nĐây là hai lý do cốt lõi buộc tổ chức phải lập nhóm làm việc.", "has_visual": false}, {"id": "SSG104_063", "index": 63, "question": "Which word best describes this statement \"The members need the help of one another to accomplish the purpose for which they joined the group\"", "options": {"A": "Sustainability", "B": "Interdependence", "C": "Interaction", "D": "Identity"}, "correct": ["B"], "vi_explanation": "B. Sự phụ thuộc lẫn nhau (Interdependence).\nThành viên cần sự hỗ trợ qua lại mới hoàn thành được mục tiêu chung của nhóm.", "has_visual": false}, {"id": "SSG104_087", "index": 87, "question": "Which of the following is NOT a negative outcomes of Groupthink occurring?", "options": {"A": "Not examinỉng altematives", "B": "No contingency pians", "C": "Not seeking expert opinion", "D": "Needing to seek outside expertise"}, "correct": ["D"], "vi_explanation": "D. \"Cần tìm kiếm ý kiến chuyên gia bên ngoài\" không phải hệ quả tiêu cực của Groupthink.\nNgược lại, nhóm bị Groupthink thường khép kín và phớt lờ chuyên gia bên ngoài.", "has_visual": false}, {"id": "SSG104_096", "index": 96, "question": "Those who have empathetic ability can", "options": {"A": "vicariously experience others' emotions", "B": "be ignored in group working", "C": "organize and distribute work between others and themselves", "D": "not take on others' perspectives and understand their emotional experiences"}, "correct": ["A"], "vi_explanation": "A. Có khả năng đặt mình vào vị trí người khác để cảm nhận cảm xúc của họ.\nĐó chính là định nghĩa của sự thấu cảm (Empathy).", "has_visual": false}, {"id": "SSG104_097", "index": 97, "question": "What does the word \"Team\" stand for?", "options": {"A": "Together Everything Access More", "B": "Together Everyone AcceptMore", "C": "Together Everyone Assist Members", "D": "Together Everyone Achieves More"}, "correct": ["D"], "vi_explanation": "D. Together Everyone Achieves More.\nCách viết tắt quen thuộc nhấn mạnh sức mạnh hợp lực của làm việc nhóm.", "has_visual": false}, {"id": "SSG104_100", "index": 100, "question": "Which of the following is not a characteristic of a team?", "options": {"A": "Interdependence", "B": "Sustainability", "C": "The ability to act together", "D": "Independence"}, "correct": ["D"], "vi_explanation": "D. Sự độc lập tách rời (Independence).\nNhóm (Team) gắn liền với sự phụ thuộc lẫn nhau (Interdependence), bền vững và cùng hành động — trái ngược với làm việc độc lập hoàn toàn.", "has_visual": false}, {"id": "SSG104_127", "index": 127, "question": "What is NOT an informal group?", "options": {"A": "Friend circles.", "B": "Airline flight crew.", "C": "Gossip groups.", "D": "People dining in a restaurant on the same evening."}, "correct": ["B"], "vi_explanation": "B. Phi hành đoàn máy bay (Airline flight crew).\nĐây là nhóm chính thức (Formal group) được phân công chức năng nhiệm vụ rõ ràng trong tổ chức.", "has_visual": false}, {"id": "SSG104_128", "index": 128, "question": "Which phenomenan does this following example lustrate?\n\"On such tasks, information known to many of the group members suggests that one alternative, say Option A, is best However, Option B is definitely the better choice, but all the facts that support Option B are only known to individual groups members.", "options": {"A": "Group polarization.", "B": "Comman knowledge effect.", "C": "Groupthink.", "D": "Conformity pressures."}, "correct": ["B"], "vi_explanation": "B. Hiệu ứng Tri thức chung (Common knowledge effect).\nNhóm thường bị cuốn theo thông tin mà nhiều người cùng biết (lựa chọn A) và bỏ qua thông tin quý giá chỉ vài cá nhân nắm giữ (lựa chọn B).", "has_visual": false}, {"id": "SSG104_158", "index": 158, "question": "Which age group is considered to have tentative choices and support a desire for autonomy?", "options": {"A": "12-17.", "B": "18-26.", "C": "27-31.", "D": "32-42."}, "correct": ["B"], "vi_explanation": "B. Nhóm tuổi 18–26.\nĐây là giai đoạn thanh niên thử nghiệm nhiều lựa chọn nghề nghiệp và khẳng định tính tự chủ.", "has_visual": false}, {"id": "SSG104_176", "index": 176, "question": "Team characteristics should include one of following factors", "options": {"A": "Interaction.", "B": "Short-term relation.", "C": "Act independently.", "D": "Unreacted members."}, "correct": ["A"], "vi_explanation": "A. Sự tương tác (Interaction).\nCác thành viên trong một nhóm thực thụ phải có sự giao tiếp, trao đổi và phối hợp qua lại.", "has_visual": false}, {"id": "SSG104_201", "index": 201, "question": "Which situation below is considered social loafing?", "options": {"A": "A single student works alone on a paper.", "B": "A student does all the group homework.", "C": "Three students work on homework together.", "D": "The whole group equally work hard on group assignment."}, "correct": ["B"], "vi_explanation": "B. Một sinh viên phải gánh làm hết bài tập nhóm (trong khi các thành viên khác ỷ lại).\nSocial loafing là hiện tượng một số thành viên giảm nỗ lực khi làm việc tập thể để người khác làm thay.", "has_visual": false}, {"id": "SSG104_206", "index": 206, "question": "Regarding the psychology of groups, we join groups to satisfy our need to belong, gain information and understanding through social comparison, achieve goals that might elude us if we worked alone, and.....", "options": {"A": "strengthen our bonds with others.", "B": "show our respect to others.", "C": "meet the requirements of a group-working environment.", "D": "define our sense of self and social identity."}, "correct": ["D"], "vi_explanation": "D. Định hình bản sắc cá nhân và bản sắc xã hội của chính mình (define our sense of self and social identity).\nNhóm giúp ta biết mình là ai trong mối tương quan với cộng đồng.", "has_visual": false}, {"id": "SSG104_244", "index": 244, "question": "What team consists of a group of people who come together as a distinct organizational unit project?", "options": {"A": "Project team", "B": "Functional team", "C": "Matrix team", "D": "Modern Teams"}, "correct": ["A"], "vi_explanation": "A. Nhóm dự án (Project team).\nNhóm tập hợp thành đơn vị riêng biệt chỉ để triển khai dự án.", "has_visual": false}, {"id": "SSG104_248", "index": 248, "question": "When one language is dominated in the group, what could happen to the person who can't speak it?", "options": {"A": "Less competent in a group.", "B": "Feel left out.", "C": "Be seen as contributing less.", "D": "All are correct."}, "correct": ["D"], "vi_explanation": "D. Tất cả các hệ quả trên đều đúng.\nRào cản ngôn ngữ khiến người không nói thạo ngôn ngữ chung dễ tự ti, bị gạt ra rìa và bị đánh giá thấp đóng góp.", "has_visual": false}, {"id": "SSG104_263", "index": 263, "question": "What is groupthink?", "options": {"A": "Group members share same thought in a specific topic", "B": "Group members are incapable of making a rational decision", "C": "Group members decide to support each other", "D": "Group members want to be alike in everything"}, "correct": ["A"], "vi_explanation": "A. Các thành viên cùng chia sẻ một suy nghĩ đồng nhất ở một chủ đề cụ thể (ưu tiên đồng thuận hơn phản biện).\nGroupthink xảy ra khi tập thể kìm nén ý kiến trái chiều để giữ sự hòa hợp bề mặt, dẫn đến quyết định thiếu sáng suốt.", "has_visual": false}, {"id": "SSG104_281", "index": 281, "question": "In group decision making process, if there are more people agreeing on certain point of view, we may consider the fact that the group has", "options": {"A": "complete agreement.", "B": "group polarization.", "C": "group sharing knowledge.", "D": "All resources are mobilized."}, "correct": ["B"], "vi_explanation": "B. Phân cực nhóm (group polarization).\nKhi nhiều người đồng tình với một xu hướng ban đầu, quan điểm chung của nhóm thường bị đẩy lên cực đoan hơn nữa.", "has_visual": false}, {"id": "SSG104_283", "index": 283, "question": "The cfistribution of resources between you and another person is 500 AUD and 100 AUD respectively after receiving profit by selling clothes. So what kind of social value orientation in this situation?", "options": {"A": "Competitive Orientation", "B": "Cooperative Orientation", "C": "Individualistic Orientation", "D": "All of above"}, "correct": ["A"], "vi_explanation": "A. Định hướng cạnh tranh (Competitive Orientation).\nMức chênh lệch nhận về quá lớn (500 AUD vs 100 AUD) cho thấy xu hướng tối đa hóa khoảng cách thắng thua vượt trội so với đối phương.", "has_visual": true, "image_local": "images/SSG104_283.jpg", "images": ["https://o.quizlet.com/jdIXjzYTEDdi7ZDXRoc8zg_m.jpg"]}, {"id": "SSG104_289", "index": 289, "question": "Which component is in situational influence of cooperation?", "options": {"A": "Hard working.", "B": "Group identification.", "C": "Open mind.", "D": "Generosity."}, "correct": ["B"], "vi_explanation": "B. Sự gắn kết/đồng nhất với nhóm (Group identification).\nKhi cá nhân coi mình thuộc về nhóm, yếu tố hoàn cảnh này thúc đẩy hành vi hợp tác tự nguyện.", "has_visual": false}, {"id": "SSG104_298", "index": 298, "question": "Formal groups are used to", "options": {"A": "organize and distribute work.", "B": "work independently.", "C": "make things more clearly.", "D": "feel like family."}, "correct": ["A"], "vi_explanation": "A. Tổ chức và phân công công việc.\nNhóm chính thức được thành lập có chủ đích nhằm phân chia trách nhiệm và hoàn thành nhiệm vụ tổ chức.", "has_visual": false}, {"id": "SSG104_304", "index": 304, "question": "One of the three categories of social value orientation (SVO) is?", "options": {"A": "Incompetent.", "B": "Cooperative.", "C": "Obsessive.", "D": "Generous."}, "correct": ["B"], "vi_explanation": "B. Hợp tác (Cooperative).\nBa nhóm chính trong định hướng giá trị xã hội (SVO) gồm: Hợp tác (Cooperative), Cá nhân (Individualistic) và Cạnh tranh (Competitive).", "has_visual": false}, {"id": "SSG104_333", "index": 333, "question": "How many people does \"a span of control\" structure averagely have in their team?", "options": {"A": "3.", "B": "5.", "C": "7.", "D": "10."}, "correct": ["B"], "vi_explanation": "B. Trung bình 5 người (trong khoảng lý tưởng 3–7 người theo phạm vi kiểm soát).\nTheo giáo trình chuẩn của môn, con số trung bình được chọn cho cấu trúc span of control tối ưu là 5.", "has_visual": false}]}, {"id": "conflict", "title": "Giải quyết xung đột", "tag": "Xung đột", "questions": [{"id": "SSG104_025", "index": 25, "question": "Which of the following can be seen as positive sides of conflict?", "options": {"A": "Help individuals and group members grow and develop self-identities", "B": "Affect the social climate of the group and inhibit group cohesiveness", "C": "Making people divert energies away from the performance", "D": "influence on stress and the psychophysical consequences of stress"}, "correct": ["A"], "vi_explanation": "A. Giúp cá nhân và thành viên hiểu rõ bản thân hơn và phát triển nhận thức.\nXung đột tích cực thúc đẩy nhìn nhận đa chiều và trưởng thành, trái ngược với các hệ quả tiêu cực ở B, C, D.", "has_visual": false}, {"id": "SSG104_037", "index": 37, "question": "Which of the following are the five modes for conflict resolution developed by Kenneth Thomas (1976)?", "options": {"A": "(1) competing, (2) collaborating, (3) compromising, (4) avoiding, and (5) accommodating", "B": "(1) competing, (2) combination, (3) aggravating, (4) resistance, and (5) ignore", "C": "(1) competing, (2) combination, (3) compromising, (4) avoiding, and (5) accommodating", "D": "(1) competing, (2) collaborating, (3) aggravating, (4) resistance, and (5) ignore"}, "correct": ["A"], "vi_explanation": "A. Competing (cạnh tranh), Collaborating (hợp tác), Compromising (thỏa hiệp), Avoiding (né tránh), Accommodating (nhượng bộ).\nĐây là đúng tên 5 phương thức giải quyết xung đột theo mô hình Thomas–Kilmann (1976).", "has_visual": true, "image_local": "images/SSG104_037.png", "images": ["https://o.quizlet.com/ngY1RCQSMTnFPJVqwUYf6g_m.png"]}, {"id": "SSG104_057", "index": 57, "question": "What role does effective communication and negotiation play in reducing conflicts within a team?", "options": {"A": "It tends to escalate conflicts.", "B": "It is irrelevant in conflict resolution.", "C": "It is a tool for understanding perspectives and finding work out problems.", "D": "It often involves outside training experts to help groups develop permanent mechanisms for working together."}, "correct": ["C"], "vi_explanation": "C. Là công cụ giúp thấu hiểu góc nhìn của nhau và tìm cách tháo gỡ vấn đề.\nGiao tiếp và đàm phán hiệu quả giúp giải quyết xung đột tận gốc ngay trong nội bộ.", "has_visual": false}, {"id": "SSG104_060", "index": 60, "question": "\"A and B are friends from school. A might give B gas money for B's motorbike because B drives A to school every day, even though that means A will have less spending money for the weekend.\"According to Social Value Orientation (SVO), in this situation, A is demonstrating:", "options": {"A": "Individualistic orientation", "B": "Cooperative orientation", "C": "Competitive orientation", "D": "Accommodating orientation"}, "correct": ["B"], "vi_explanation": "B. Định hướng hợp tác (Cooperative orientation).\nA sẵn sàng chia sẻ chi phí để cả hai cùng có lợi và duy trì sự công bằng dù bản thân ít tiền tiêu hơn.", "has_visual": false}, {"id": "SSG104_105", "index": 105, "question": "What is not a component of the Thomas five modes for conflict resolution? (Thủy Tiên)", "options": {"A": "Accommodating", "B": "Collaborating", "C": "Avoiding", "D": "Tolerating", "E": "Competing"}, "correct": ["D"], "vi_explanation": "D. Tolerating (Chịu đựng/dung thứ) không nằm trong 5 phương thức của Thomas.\nNăm phương thức chuẩn gồm: Competing, Collaborating, Compromising, Avoiding và Accommodating.", "has_visual": false}, {"id": "SSG104_124", "index": 124, "question": "What are conflict preventing strategies? (Select 4 options)", "options": {"A": "Use of rules and regulations.", "B": "Avoiding win lose situations.", "C": "Facilitating dialogue.", "D": "Providing stable, well structured tasks.", "E": "Emphasizing group goals and effectiveness."}, "correct": ["B", "C", "D", "E"], "vi_explanation": "B, C, D, E. Tránh tình huống thắng–thua, khuyến khích đối thoại, giao việc rõ ràng và nhấn mạnh mục tiêu chung đều giúp phòng ngừa xung đột.\nÁp đặt quá nhiều quy tắc cứng nhắc (A) dễ gây gò bó thay vì phòng ngừa tận gốc.", "has_visual": true, "image_local": "images/SSG104_124.jpg", "images": ["https://o.quizlet.com/9z1Jm9tDUO.mSKQX7jrkAw_m.jpg"]}, {"id": "SSG104_154", "index": 154, "question": "Which of the four key cultural differences could be considered offensive by some?", "options": {"A": "Direct versus indirect communication.", "B": "Accents and fluency.", "C": "Differing attitudes toward hierarchy.", "D": "Conflicting decision-making norms."}, "correct": ["A"], "vi_explanation": "A. Khác biệt giữa giao tiếp trực tiếp (thẳng thắn) và gián tiếp (vòng vo).\nSự khác biệt này dễ gây hiểu nhầm thành thô lỗ hoặc thiếu minh bạch giữa các nền văn hóa.", "has_visual": false}, {"id": "SSG104_162", "index": 162, "question": "An expressed struggle between interdependent parties over goals which they perceive as incompatible or resources which they perceive to be insufficient is the definition for?", "options": {"A": "Negotiation.", "B": "Conflict.", "C": "Frustration.", "D": "Competing."}, "correct": ["B"], "vi_explanation": "B. Xung đột (Conflict).\nLà cuộc đấu tranh được bộc lộ giữa các bên phụ thuộc lẫn nhau khi thấy mục tiêu xung khắc hoặc nguồn lực khan hiếm.", "has_visual": false}, {"id": "SSG104_195", "index": 195, "question": "Why is putting yourself in nerve-racking situations can sometimes stimulate your creative thinking?", "options": {"A": "Certain amounts of pressure are important to keep a creative task moving forward.", "B": "When we feel stressed, it enhance our mental capacity.", "C": "Fear and frustration can trigger a sense of responsibility.", "D": "Time constraints make the task more exciting."}, "correct": ["A"], "vi_explanation": "A. Một lượng áp lực vừa phải giúp thúc đẩy công việc sáng tạo tiến về phía trước.\nÁp lực thời hạn hoặc thử thách hợp lý kích thích não bộ tập trung giải quyết vấn đề nhanh nhạy hơn.", "has_visual": false}, {"id": "SSG104_227", "index": 227, "question": "When will we build a team?", "options": {"A": "For simple tasks or problems", "B": "When a broad range of competences and different skills are required", "C": "When high commitment is needed", "D": "When members' interests are different or in conflict"}, "correct": ["B"], "vi_explanation": "B. Khi công việc đòi hỏi phạm vi năng lực rộng và nhiều kỹ năng đa dạng.\nVới việc đơn giản, làm cá nhân sẽ nhanh hơn; chỉ lập nhóm khi cần phối hợp đa chuyên môn.", "has_visual": false}, {"id": "SSG104_237", "index": 237, "question": "Last stage in the model of the Conflict Process", "options": {"A": "Frustration", "B": "Conceptualization", "C": "Behavior", "D": "Outcome"}, "correct": ["D"], "vi_explanation": "D. Kết quả (Outcome).\nQuy trình 4 bước của Tiến trình Xung đột gồm: Frustration (Bất mãn) → Conceptualization (Nhận thức) → Behavior (Hành vi) → Outcome (Kết quả). (Kèm ảnh sơ đồ.)", "has_visual": true, "image_local": "images/SSG104_237.png", "images": ["https://o.quizlet.com/.7qVB.tkC.ZIkrJOfKCM6g_m.png"]}, {"id": "SSG104_245", "index": 245, "question": "Which mode of resolving conflict should be considered when potential disruption outweighs the benefits of resolution?", "options": {"A": "Collaborating", "B": "Compromising", "C": "Avoiding", "D": "Accommodating"}, "correct": ["C"], "vi_explanation": "C. Né tránh (Avoiding).\nKhi xung đột nhỏ hoặc cái giá của việc tranh cãi lớn hơn lợi ích đạt được, tạm lùi bước né tránh là lựa chọn khôn ngoan.", "has_visual": false}, {"id": "SSG104_249", "index": 249, "question": "When do the Conflicts of misperceived differences arise?", "options": {"A": "Reinforcing or weakening each other's impact.", "B": "Interpret each other's actions or emotions erroneously.", "C": "Differ over how to reach goals or pursue values.", "D": "Hold totally different values or rank the same values in a significantly different order."}, "correct": ["B"], "vi_explanation": "B. Khi các bên hiểu sai hành động hoặc cảm xúc của nhau.\nMisperceived differences xuất phát từ hiểu lầm về ý định hay thái độ chứ chưa chắc do khác biệt giá trị thật sự.", "has_visual": false}, {"id": "SSG104_254", "index": 254, "question": "Which of the following is NOT the characteristic of leadership?", "options": {"A": "Self-confidence and sense of personal identity", "B": "Readiness to absorb interpersonal stress", "C": "Maturity to not tolerate frustration and delay", "D": "Ability to influence other people's behavior"}, "correct": ["C"], "vi_explanation": "C. \"Trưởng thành đến mức không chịu nổi sự thất vọng hay chậm trễ\" là SAI.\nNgười lãnh đạo cần sự điềm tĩnh và sức chịu đựng áp lực cao chứ không nóng nảy thiếu kiên nhẫn.", "has_visual": false}, {"id": "SSG104_267", "index": 267, "question": "Which conflict-handling mode can be used when an issue is trivial, or when more important issues are pressing", "options": {"A": "Avoiding.", "B": "Competing.", "C": "Compromising.", "D": "Accommodating."}, "correct": ["A"], "vi_explanation": "A. Né tránh (Avoiding).\nKhi vấn đề nhỏ nhặt hoặc có việc cấp bách hơn, không cần tốn công tranh luận ngay.", "has_visual": false}, {"id": "SSG104_279", "index": 279, "question": "What is the first stage in the model of the Conflict Process?", "options": {"A": "Frustration.", "B": "Conceptualization.", "C": "Behavior.", "D": "Outcome."}, "correct": ["A"], "vi_explanation": "A. Sự bất mãn/nản lòng (Frustration).\nXung đột bắt đầu khi một bên cảm thấy mục tiêu hoặc lợi ích của mình bị cản trở, dẫn tới cảm giác thất vọng ban đầu.", "has_visual": false}, {"id": "SSG104_295", "index": 295, "question": "When conflicts arise, what intervention technique should be used as a last resort?", "options": {"A": "Adaptation.", "B": "Structural.", "C": "Managerial.", "D": "Voluntary or involuntary removal."}, "correct": ["D"], "vi_explanation": "D. Loại bỏ thành viên (tự nguyện hoặc buộc rời nhóm).\nChỉ khi mọi biện pháp thích nghi, điều chỉnh cấu trúc hay quản lý đều thất bại mới dùng tới bước cuối cùng này.", "has_visual": false}, {"id": "SSG104_318", "index": 318, "question": "What is the quickest and easiest solution to reduce conflict?", "options": {"A": "Physical separation.", "B": "Use of rules and regulations.", "C": "Third-party consultation.", "D": "Confrontation and negotiation."}, "correct": ["A"], "vi_explanation": "A. Tách biệt về mặt vật lý (Physical separation).\nCho các bên xung đột tạm tách khỏi không gian chung giúp hạ nhiệt nhanh nhất trước khi xử lý sâu hơn.", "has_visual": false}, {"id": "SSG104_336", "index": 336, "question": "Withdrawing from or suppression of conflict is termed .........", "options": {"A": "collaborating", "B": "forcing", "C": "accommodating", "D": "avoiding"}, "correct": ["D"], "vi_explanation": "D. Né tránh (Avoiding).\nRút lui khỏi xung đột hoặc kìm nén không đối mặt là biểu hiện của phương thức Avoiding.", "has_visual": false}, {"id": "SSG104_342", "index": 342, "question": "Which conflict-handling mode can be used when issues are more important to others than others and maintain cooperation", "options": {"A": "Avoiding.", "B": "Competing.", "C": "Compromising.", "D": "Accommodating."}, "correct": ["D"], "vi_explanation": "D. Nhượng bộ (Accommodating).\nKhi vấn đề quan trọng với người khác hơn với mình và cần giữ hòa khí, nhường phần hơn cho họ là hợp lý.", "has_visual": false}, {"id": "SSG104_343", "index": 343, "question": "In Tuckman's Group Development Stages, which characteristics are correct in the third stage", "options": {"A": "The group prepares to disband by completing its tasks, reduces levels of dependency am and dealing with any", "B": "The group focuses its energies and attention on its goals, displaying higher rates of task- decision-making, and problem-solving.", "C": "Disagreements about procedures and purposes surface, so criticism and conflict increase", "D": "Once the group agrees on its goals, procedures, and leadership, norms, roles, and social develop that increase the group's stability and cohesiveness"}, "correct": ["D"], "vi_explanation": "D. Giai đoạn thứ 3 (Norming): nhóm thống nhất mục tiêu, quy trình, chuẩn mực và vai trò giúp tăng ổn định, gắn kết.\nA là Adjourning, B là Performing, C là Storming.", "has_visual": false}]}]};
